\title{Emergent LLM behaviors are observationally equivalent to data leakage%
  \thanks{We thank Christopher Bail, Alexis Palmer, and Arthur Spirling for comments on a previous draft.}}

\author[1]{Christopher Barrie%
  \thanks{Assistant Professor of Sociology, New York University}}
\author[2]{Petter Törnberg%
  \thanks{Institute for Logic, Language, and Computation, University of Amsterdam}}

\affil[1]{New York University}
