\section{Additional notation and guide to appendices}

Let $\pi$ be some stationary policy.
Note that $P_\pi$ (defined above as the Markov chain over states induced by policy $\pi$ on the transition kernel $P$) is equal to $M^\pi P$. We also define $r_\pi = M^\pi r$. Then we have $V^\pi_\gamma = (I - \gamma P_\pi)^{-1} r_\pi$. $\infnorm{\cdot}$ and $\onenorm{\cdot}$ denote the usual $\ell_\infty$/$\ell_1$-norms, respectively. $\infinfnorm{W}$ denotes the $\infnorm{\cdot}\to\infnorm{\cdot}$ operator norm of a matrix $W$. In particular $\infinfnorm{(I -\gamma P_\pi)^{-1}} = \frac{1}{1-\gamma}$. We note that the action maximization operator $M$ and the policy matrix $M^\pi$ both satisfy monotonicity: $V \geq V'$ (elementwise, for $Q, Q' \in \R^{\S \times \A}$) implies $M(Q) \geq M(Q')$, and likewise that $M^\pi Q \geq M^\pi Q'$. These two operators also both satisfy the ``constant-shift'' property, that for any $c \in \R$ and any $Q \in \R^{\S \times \A}$, we have $M(Q + c \one) = c \one + M(Q)$ and $M^\pi(Q + c \one) = c \one + M^\pi(Q)$. Also we note that $M$ and $M^\pi$ are both $1$-Lipschitz with respect to $\infnorm{}$, that is $\infnorm{MQ - MQ'} \leq \infnorm{Q - Q'}$ and $\infnorm{M^\pi Q - M^\pi Q'} \leq \infnorm{Q - Q'}$.
For any vector $x$ we let $x^{\circ k}$ denote its elementwise $k$th power.
We let $\ind$ denote the usual indicator function used in probability where $\ind(E)$ is a random variable with value $1$ if the event $E$ holds and $0$ otherwise.

In Appendix \ref{sec:proof_of_main_theorem} we prove the main theorem, Theorem \ref{thm:main_theorem}. In Appendix \ref{sec:proof_transient_lb} we prove Theorem \ref{thm:transient_lb} and in Appendix \ref{sec:proof_dataset_lb} we prove Theorem \ref{thm:recurrent_lb}. Appendix \ref{sec:deferred_proofs} contains additional supporting results.




\section{Proof of main theorem}
\label{sec:proof_of_main_theorem}



\subsection{Well-definedness}
We also define a fixed-policy/policy evaluation version of $\Thpe$ which will be useful within the analysis. For any fixed stationary policy $\pi$, we let
\begin{align}
    \Thpe^\pi (Q)(s,a) &:= r(s,a) +\gamma\max \left\{  \Phat_{sa} T_{\beta(s,a)}( \Phat_{sa}, M^\pi Q) - b(s,a, M^\pi Q), \min_{s'}(M^\pi Q)(s') \right \} .\label{eq:defn_of_Thpe_pi}
\end{align}
We also define $\Vhpe^{\pi} := M^{\pi}  \Qhpe^{\pi}$, where $\Qhpe^{\pi}$ is the unique fixed point of $\Thpe^\pi$ (justified in the below lemma).

The following is a more comprehensive variant of Lemma \ref{lem:pessimistic_Bellman_operator_properties_short}.
\begin{lem}
\label{lem:pessimistic_Bellman_operator_properties}
\begin{enumerate}
    \item \label{lem:pessimistic_Bellman_operator_properties_pt1}
    $\Thpe$ satisfies the following properties:
    \begin{enumerate}
        \item Monotonicity: If $Q \geq Q'$ then $\Thpe(Q) \geq \Thpe(Q')$.
        \item Constant shift: For any $c \in \R$, $\Thpe(Q + c \one) = \Thpe(Q) + \gamma c \one$.
        \item $\gamma$-contractivity: $\Thpe$ is a $\gamma$-contraction and has a unique fixed point $\Qhpe^\star$.
        \item Boundedness: $\zero \leq \Qhpe^\star \leq \frac{1}{1-\gamma}\one$.
    \end{enumerate}
    \item For any fixed stationary deterministic policy $\pi$, the analogous statements hold for $\Thpe^{\pi}$: \label{lem:pessimistic_Bellman_operator_properties_pt2}
    \begin{enumerate}
        \item Monotonicity: If $Q \geq Q'$ then $\Thpe^\pi(Q) \geq \Thpe^\pi(Q')$.
        \item Constant shift: For any $c \in \R$, $\Thpe^\pi(Q + c \one) = \Thpe^\pi(Q) + \gamma c \one$.
        \item $\gamma$-contractivity: $\Thpe^\pi$ is a $\gamma$-contraction and has a unique fixed point $\Qhpe^\pi$.
        \item Boundedness: $\zero \leq \Qhpe^\pi \leq \frac{1}{1-\gamma}\one$.
    \end{enumerate}
    \item For any fixed stationary deterministic policy $\pi$, we have $\Qhpe^\star \geq \Qhpe^\pi$. \label{lem:pessimistic_Bellman_operator_properties_pt3}
\end{enumerate}
\end{lem}

\begin{proof}

We note that a few steps are similar to \citet[Lemma 1]{li_settling_2023}, but our new choice of penalty requires much more involved analysis. 

We define an auxiliary operator $\Tope : \R^\S \to \R^{\S\A}$ by, for any $V \in \R^\S$,
\begin{align*}
    \Tope (V)(s,a) &:= r(s,a) +\gamma\max \left\{  \Phat_{sa} T_{\beta(s,a)}( \Phat_{sa}, V) - b(s,a, V), \min_{s'}(V)(s') \right \} .
\end{align*}
We defer the verification of the following fact, which involves somewhat lengthy calculations, to Appendix \ref{sec:tope_monotonicity_proof}.
\begin{lem}
    \label{lem:tope_monotonicity}
    Let $V, V' \in \R^\S$ be arbitrary and suppose that $V \geq V'$. Then (elementwise)
    \begin{align*}
        \Tope(V) \geq \Tope(V').
    \end{align*}
\end{lem}
Given Lemma \ref{lem:tope_monotonicity}, we can relatively easily verify Lemma \ref{lem:pessimistic_Bellman_operator_properties}. We note that Lemma \ref{lem:tope_monotonicity} makes use of the quantile clipping in an essential way.

Now we will show item~\ref{lem:pessimistic_Bellman_operator_properties_pt1} except for the boundedness property. Notice that $\Thpe(Q) = \Tope(MQ)$ (for any $Q \in \R^{\S\A}$). Therefore letting $Q, Q' \in\R^{\S\A}$ with $Q \geq Q'$, we have by monotonicity of $M$ that $MQ \geq MQ'$, and thus by monotonicity of $\Tope$ we conclude that
\begin{align*}
    \Thpe(Q) = \Tope(MQ) \geq \Tope(MQ') = \Thpe(Q')
\end{align*}
as desired. Next we check the constant shift property of $\Tope$. Fix $c \in \R, V \in \R^\S$, and $s \in \S, a \in \A$. Then we have that $T_{\beta(s,a)}(\Phat_{sa}, V + c \one) = T_{\beta(s,a)}(\Phat_{sa}, V) + c \one$, regardless of whether $\beta(s,a) \in [0,1]$ or $\beta(s,a) > 1$, since when $\beta(s,a) > 1$ we have $T_{\beta(s,a)}(\Phat_{sa}, V + c \one) = \min_{s \in \S}(V + c \one) \one  = (\min_{s \in \S}(V) + c) \one$, and when $\beta(s,a) \leq 1$, by~\eqref{eq:qc_operator_defn} we have
\begin{align*}
    T_{\beta(s,a)}(\Phat_{sa}, V+ c \one)(s) &= \min\Bigg\{
        V(s) + c, 
        ~\sup \bigg\{V(s') + c : s' \in \S, \sum_{s'' \in \S : V(s'')+c \geq V(s') + c} \!\!\!\! \Phat_{sa}(s') \geq \beta \bigg\}
     \Bigg\} \\
     &= c + \min\Bigg\{
        V(s), 
        ~\sup \bigg\{V(s') : s' \in \S, \sum_{s'' \in \S : V(s'') \geq V(s')} \!\!\!\! \Phat_{sa}(s') \geq \beta \bigg\}
     \Bigg\}\\
     &= c + T_{\beta(s,a)}(\Phat_{sa}, V)(s).
\end{align*}
Therefore
\begin{align*}
    &\Var_{\Phat_{sa}}\left[ T_{\beta(s,a)}(\Phat_{sa}, V + c \one)\right] = \Var_{\Phat_{sa}}\left[ T_{\beta(s,a)}(\Phat_{sa}, V ) + c \one\right]= \Var_{\Phat_{sa}}\left[ T_{\beta(s,a)}(\Phat_{sa}, V ) \right]\\
    \text{and}\quad& \spannorm{T_{\beta(s,a)}(\Phat_{sa}, V + c \one)} = \spannorm{T_{\beta(s,a)}(\Phat_{sa}, V )+ c \one} = \spannorm{T_{\beta(s,a)}(\Phat_{sa}, V)}
\end{align*}
and therefore we have that
$b(s,a,V) = b(s,a,V+c \one)$. Additionally we have that
\begin{align*}
    \min_{s'}\left(V + c \one \right)(s') = \min_{s'} V(s') + c .
\end{align*}
Hence
\begin{align}
    \Tope(V + c \one)(s,a) &= r(s,a) +\gamma\max \left\{  \Phat_{sa} T_{{\beta(s,a)}}( \Phat_{sa}, V+ c \one) - b(s,a, V+ c \one), \min_{s'}(V+ c \one)(s') \right \} \nonumber\\
    &= r(s,a) +\gamma\max \left\{  \Phat_{sa} T_{{\beta(s,a)}}( \Phat_{sa}, V) + c  \Phat_{sa} \one - b(s,a, V), \min_{s'}(V)(s') + c \right \} \nonumber\\
    &= r(s,a) + \gamma c  + \gamma\max \left\{  \Phat_{sa} T_{{\beta(s,a)}}( \Phat_{sa}, V) - b(s,a, V), \min_{s'}(V)(s') \right \} \nonumber\\
    &=  \gamma c  + \Tope(V)(s,a) \label{eq:tope_eigenvector}
\end{align}
(since $\Phat_{sa} \one = 1$). Using~\eqref{eq:tope_eigenvector} and the fact that $M(Q + c \one) = MQ + c \one$ we can show that $\Thpe$ satisfies the constant shift property as well:
\begin{align*}
    \Thpe(Q + c \one) = \Tope(M(Q + c \one)) = \Tope(MQ + c \one) = \Tope(MQ )+ \gamma c \one = \Thpe(Q )+ \gamma c \one
\end{align*}
as desired. Finally we can check contractivity of $\Thpe$. We note that it suffices to show that $\Tope$ is $\gamma$-Lipschitz, since then we would have for any $Q_1, Q_2 \in \R^{\S\A}$ that
\begin{align*}
    \infnorm{\Thpe(Q_1) - \Thpe(Q_2)} = \infnorm{\Tope(MQ_1) - \Tope(MQ_2)} \leq \gamma \infnorm{MQ_1 - MQ_2} \leq \gamma \infnorm{Q_1 - Q_2}
\end{align*}
as desired, where the first inequality is due to the (assumed) Lipschitzness of $\Tope$ and the second inequality is due to the $1$-Lipschitzness of $M$. Now we verify that $\Tope$ is indeed $\gamma$-Lipschitz.
For any $V_1, V_2 \in \R^{\S}$ we have $V_1 \leq V_2 + \infnorm{V_1 - V_2}\one$ (elementwise), so by monotonicity of $\Tope$ (Lemma \ref{lem:tope_monotonicity}), and then using the fact that $\Tope$ satisfies the constant shift property (shown in~\eqref{eq:tope_eigenvector}) in the next inequality, we have
\begin{align*}
    \Tope(V_1) &\leq \Tope(V_2 + \infnorm{V_1-V_2}\one) \\
    &= \Tope(V_2) + \gamma \infnorm{V_1-V_2}\one
\end{align*}
so by rearranging
\begin{align*}
  \Tope(V_1)-\Tope(V_2) \leq   \gamma \infnorm{V_1-V_2}\one.
\end{align*}
By reversing the roles of $V_1$ and $V_2$ we also have
\begin{align*}
  \Tope(V_2)-\Tope(V_1) \leq   \gamma \infnorm{V_1-V_2}\one 
\end{align*}
or equivalently
\begin{align*}
    -\gamma \infnorm{V_1-V_2}\one \leq \Tope(V_1)-\Tope(V_2).
\end{align*}
Combining these two inequalities involving $\Tope(V_2)-\Tope(V_1)$ we conclude that $\infnorm{\Tope(V_1)-\Tope(V_2)} \leq \gamma \infnorm{V_1 - V_2}$ as desired and thus $\Thpe$ is a $\gamma$-contraction. By the Banach fixed-point theorem (e.g. \cite[Chapter 4.5]{pugh_real_2015}) this implies the existence of a unique fixed point of $\Thpe$, which we call $\Qhpe^\star$. (We check that $\zero \leq \Qhpe^\star \leq \frac{1}{1-\gamma}\one$ later.)

Now we will show item~\ref{lem:pessimistic_Bellman_operator_properties_pt2} except for the boundedness property. Notice that similarly to the previous case, $\Thpe^\pi(Q) = \Tope(M^\pi Q)$ (for any $Q \in \R^{\S\A}$). The only properties of $M$ used in the proofs for the previous case were monotonicity (that $Q \geq Q' \implies MQ \geq MQ'$), that $M(Q + c \one) = MQ + c \one$, and that $M$ is $1$-Lipschitz. All of these properties are also true with $M^\pi$ in place of $M$, so in fact all proofs used to verify item~\ref{lem:pessimistic_Bellman_operator_properties_pt1} can immediately be applied (with this minor modification) to also verify item~\ref{lem:pessimistic_Bellman_operator_properties_pt2}.

Next, item \ref{lem:pessimistic_Bellman_operator_properties_pt3} would follow by showing that for any fixed $Q\in \R^{SA}$ we have
\begin{align}
    \Thpe(Q) \geq \Thpe^\pi(Q) \label{eq:bellman_prop_pt3_key}
\end{align}
since then by a standard argument we can show for any integer $k \geq 0$ that
\begin{align*}
    \left(\Thpe\right)^{(k)}(\zero) \geq \left(\Thpe^\pi\right)^{(k)}(\zero)
\end{align*}
(where $(k)$ denotes $k$ compositions of an operator) and therefore that
\begin{align*}
    \Qhpe^\star = \lim_{k \to \infty } \left(\Thpe\right)^{(k)}(\zero) \geq \lim_{k \to \infty } \left(\Thpe^\pi\right)^{(k)}(\zero) = \Qhpe^\pi.
\end{align*}
So now we focus on showing~\eqref{eq:bellman_prop_pt3_key}, but this follows immediately from the fact that $M Q \geq M^\pi Q$ and that $\Tope$ is monotone (Lemma \ref{lem:tope_monotonicity}), since we have
\begin{align*}
    \Thpe(Q) = \Tope(MQ) \geq \Tope(M^\pi Q) = \Thpe^\pi(Q).
\end{align*}

Finally, we check both boundedness properties. Since we already have that $\Qhpe^{\pi} \leq \Qhpe^{\star}$, it suffices to show that $\zero \leq \Qhpe^{\pi}$ and that $\Qhpe^{\star} \leq \frac{1}{1-\gamma}\one$. First, note that we have $\Thpe^\pi(\zero) \geq \zero$, since for any $s\in \S, a \in \A$,
    \begin{align*}
        \Thpe^\pi(\zero)(s,a) &= r(s,a) + \gamma \max \left\{\Phat_{sa} T_\beta(\Phat_{sa}, M^\pi\zero) - b(s,a,M^\pi \zero), \min_{s'} (M^\pi\zero)(s')\right\} \\
        & \geq r(s,a) + \gamma \min_{s'} (M^\pi\zero)(s') = r(s,a) \geq 0.
    \end{align*}
Then by monotonicity of $\Thpe^\pi$ we have for any integer $k \geq 0$ that
\begin{align*}
    \left(\Thpe^\pi \right)^{(k)} (\zero) \geq \left(\Thpe^\pi \right)^{(k-1)} (\zero) \geq \cdots \geq \zero
\end{align*}
and so
\begin{align*}
    \Qhpe^\pi = \lim_{k \to \infty } \left(\Thpe^\pi\right)^{(k)}(\zero) \geq \zero
\end{align*}
as desired. Similarly, we have that $\Thpe(\one /(1-\gamma)) \leq \one /(1-\gamma)$, since for any $s\in \S, a \in \A$,
    \begin{align*}
        &\Thpe(\one /(1-\gamma))(s,a) \\
        &= r(s,a) + \gamma \max \left\{\Phat_{sa} T_\beta(\Phat_{sa}, M\one /(1-\gamma)) - b(s,a,M\one /(1-\gamma)), \min_{s'} (M\one /(1-\gamma))(s')\right\} \\
        &\leq 1 + \gamma \frac{1}{1-\gamma} = \frac{1}{1-\gamma}.
    \end{align*}
By an analogous argument to the previous bound, we have from monotonicity of $\Thpe$ that $\left(\Thpe \right)^{(k)} (\one /(1-\gamma)) \leq \one /(1-\gamma)$ for all positive integers $k$ and thus that $\Qhpe^\star \leq \one /(1-\gamma)$.
\end{proof}

In the above proof we defined the operator $\Tope$ and verified its Lipshitzness, which we state in the following lemma as $\Tope$ will appear again later.
\begin{lem}
    \label{lem:tope_additional_properties}
    $\Tope$ is $\gamma$-Lipschitz.
\end{lem}


\subsection{Optimization}
In this subsection we establish the basic properties of the outputs of Algorithm \ref{alg:LCBVI}.

\begin{lem}
    \label{lem:opt_guarantees}
    Algorithm \ref{alg:LCBVI} returns $\Qhat$ such that
    \begin{align*}
        \Qhat \leq \Qhpe^\star \leq \Qhat + \frac{1}{2\ntot}\one \quad \text{and} \quad \Thpe(\Qhat) \geq \Qhat.
    \end{align*}
\end{lem}
\begin{proof}
     First we note that $\Thpe(\zero) \geq \zero$, which follows easily from the definition~\eqref{eq:defn_of_Thpe} since (for arbitrary $s\in \S, a \in \A$)
    \begin{align*}
        \Thpe(\zero)(s,a) &= r(s,a) + \gamma \max \left\{\Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, M\zero) - b(s,a,M\zero), \min_{s'} (M\zero)(s')\right\} \\
        & \geq r(s,a) + \gamma \min_{s'} (M\zero)(s') = r(s,a) \geq 0.
    \end{align*}
    $\Thpe(\Qhat) \geq \Qhat$ follows from this fact and monotonicity of $\Thpe$ by standard arguments, since if for any $t \in \N$ we have that $\Thpe(\Qhat_t) \geq \Qhat_t $ then
    \begin{align*}
        \Thpe(\Qhat_{t+1}) = \Thpe\left(\Thpe(\Qhat_t)\right) \geq \Thpe\left(\Qhat_t\right)
    \end{align*}
    so by induction (since $\Qhat_0 = \zero$) $\Thpe(\Qhat_t) \geq \Qhat_t$ holds for $t = K$, and we have $\Qhat_K = \Qhat$ by definition.

    Now we argue that $\Qhat \leq \Qhpe^\star$, which follows from $\Thpe(\Qhat) \geq \Qhat$ and monotonicity of $\Thpe$ by standard arguments, since assuming for some $t \geq 1$ that $\Thpe^{(t)}(\Qhat) \geq \Qhat$, then we have
    by monotonicity that
    \begin{align*}
        \left(\Thpe \right)^{(t+1)}(\Qhat) = \left(\Thpe \right)\left(\Thpe^{(t)} (\Qhat)\right) \geq \Thpe(\Qhat) \geq \Qhat
    \end{align*}
    and so by induction $\left(\Thpe \right)^{(t)}(\Qhat) \geq \Qhat$ for all $t \geq1$, and thus
    \begin{align*}
        \Qhpe^\star = \lim_{t \to \infty} \left(\Thpe \right)^{(t)}(\Qhat) \geq \lim_{t \to \infty}\Qhat = \Qhat
    \end{align*}
    as desired.

    Finally we check that $\Qhpe^\star \leq \Qhat + \frac{1}{2\ntot}\one$.
    Again note that $\Qhat = \Qhat_\maxiter$.
    By the definition of $\maxiter = \left\lceil \frac{\log \left( \frac{2\ntot}{1-\gamma} \right)}{1-\gamma} \right \rceil$, as well as the fact that $\log(1/\gamma) \geq 1- \gamma$ for any $\gamma$, we have
    \begin{align*}
        \gamma^\maxiter = e^{\maxiter \log(\gamma)} \leq e^{\frac{\log \left( \frac{2\ntot}{1-\gamma} \right)}{1-\gamma}\log(\gamma)} = e^{\frac{\log \left( \frac{1-\gamma}{2\ntot} \right)}{1-\gamma}\log(1/\gamma)} \leq e^{\log \left( \frac{1-\gamma}{2\ntot} \right)} = \frac{1-\gamma}{2\ntot}.
    \end{align*}
    Using this bound, $\gamma$-contractivity, and the fact that $\zero \leq \Qhpe^\star \leq \frac{1}{1-\gamma}\one$ from Lemma \ref{lem:pessimistic_Bellman_operator_properties}, we have
    \begin{align*}
        \infnorm{\Qhat_\maxiter - \Qhpe^\star} &\leq \gamma^\maxiter \infnorm{\Qhat_0 - \Qhpe^\star} = \gamma^\maxiter \infnorm{\zero - \Qhpe^\star} \leq \gamma^\maxiter \frac{1}{1-\gamma} \leq \frac{1}{2\ntot}
    \end{align*}
    which implies $\Qhpe^\star \leq \Qhat + \frac{1}{2\ntot}\one$.
\end{proof}

\subsection{Concentration}
In this subsection we establish the key concentration inequalities, given in Lemmas \ref{lem:concentration_for_pessimism_Thpe} and \ref{lem:concentration_for_pessimism_Thpe_pistar}, using leave-one-out techniques. We start with two helper lemmas which abstractly handle the leave-one-out-based covering steps before proving Lemmas \ref{lem:concentration_for_pessimism_Thpe} and \ref{lem:concentration_for_pessimism_Thpe_pistar}.

\begin{lem}
\label{lem:concentration_helper_lemma}
    Fix some $\delta' > 0$ and some $s \in \S, a \in \A$. Suppose that for some random vector $X \in \R^\S$, there exists a (deterministic) set $U$ and some random variables $X_u \in \R^\S$ for each $u$ (that is, for each $u \in U$, $X_u$ is a random vector in $\R^\S$) such that
    \begin{enumerate}
        \item For all $u \in U$, $X_u$ is independent of all samples $S_{sa}^1, \dots, S_{sa}^{n(s,a)}$ drawn from $P(\cdot \mid s,a)$.
        \item Almost surely there exists some $u^\star \in U$ such that $\infnorm{X - X_{u^\star}} \leq \frac{1}{\ntot}$.
    \end{enumerate}
    Also assume $n(s,a) \geq 2$. Then with probability at least $1 - 6\delta'$, we have that
    \begin{align}
        \left|(\Phat_{sa} - P_{sa}) X \right| &\leq \spannorm{X}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}} +\frac{2}{\ntot}\left( 1 + \sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}}\right) \\
        \left|(\Phat_{sa} - P_{sa}) X \right|
        & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)}}+  \spannorm{X}\frac{\log (|U|/\delta')}{3 n(s,a)} \nonumber\\
        & \qquad + \frac{1}{\ntot}\left(2+ \sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)}}+ 2\frac{\log (|U|/\delta')}{3 n(s,a)}\right)  \\
        \left| \sqrt{\frac{n(s,a)}{n(s,a)-1}\Var_{\Phat_{sa}} \left[ X\right]} - \sqrt{\Var_{P_{sa}} \left[ X\right]} \right| &\leq  \spannorm{X} \sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \frac{1}{\ntot}\left(2\sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}}  + 3\right) \label{eq:concentration_helper_lemma_emp_var_term}\\
        \left|(\Phat_{sa} - P_{sa}) X \right| & \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)-1}}+\spannorm{X}\frac{7}{3}\frac{\log (|U|/\delta')}{ n(s,a)-1} \nonumber\\
        & \qquad+ \frac{1}{\ntot} \left(2 + 3\sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)-1}} + \frac{14}{3}\frac{ \log (|U|/\delta')}{n(s,a)-1} \right)
    \end{align}
\end{lem}
\begin{proof}
    We start by showing that
    \begin{align}
        \left|(\Phat_{sa} - P_{sa}) X \right| &\leq \left|(\Phat_{sa} - P_{sa}) X_{u^\star} \right| + \left|(\Phat_{sa} - P_{sa}) (X - X_{u^\star}) \right| \nonumber \\
        & \leq \left|(\Phat_{sa} - P_{sa}) X_{u^\star} \right| + \onenorm{\Phat_{sa} - P_{sa} } \infnorm{X - X_{u^\star}} \nonumber \\
        & \leq \left|(\Phat_{sa} - P_{sa}) X_{u^\star} \right| + \frac{2}{\ntot} \label{eq:concentration_covering_step_1}
    \end{align}
    where the final inequality is because $\onenorm{\Phat_{sa} - P_{sa} } \leq 2$ and $\infnorm{X - X_{u^\star}} \leq \frac{1}{\ntot}$.

    Then since for any fixed $u \in U$ we have $(\Phat_{sa} - P_{sa}) X_{u} = \sum_{i=1}^{n(s,a)} (X_{u}(S^i_{sa}) - P_{sa}X_{u})$, by Hoeffding's inequality conditioned on $X_u$ (since by assumption $X_{u}$ is independent from the $S^i_{sa}$ and each term in the above sum is contained within the interval $[\min X_{u}, \max X_{u}]$ which has length $\spannorm{X_{u}}$) we have that
    \begin{align*}
        \P \left( \left|\sum_{i=1}^{n(s,a)} (X_{u}(S^i_{sa}) - P_{sa}X_{u})\right| \geq \spannorm{X_{u}}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}}  ~\middle|~ X_u\right) \leq \frac{2 \delta'}{|U|}
    \end{align*}
    and so
    \begin{align*}
        \P \left( \left|\sum_{i=1}^{n(s,a)} (X_{u}(S^i_{sa}) - P_{sa}X_{u})\right| \geq \spannorm{X_{u}}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}}  \right) \leq \E \frac{2 \delta'}{|U|} = \frac{2 \delta'}{|U|}.
    \end{align*}
    Taking a union bound, the above inequality holds for all $u \in U$ with probability at least $1 - 2\delta'$.
    Finally, since
    \begin{align}
        \spannorm{X_{u^\star}} \leq \spannorm{X} + \spannorm{X_{u^\star} - X} \leq \spannorm{X} + 2\infnorm{X_{u^\star} - X} \leq \spannorm{X} + \frac{2}{\ntot}, \label{eq:concentration_covering_span_bound}
    \end{align}
    combining with~\eqref{eq:concentration_covering_step_1} we have that
    \begin{align*}
        \left|(\Phat_{sa} - P_{sa}) X \right| & \leq \frac{2}{\ntot} + \spannorm{X_{u^\star}}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}} \leq \frac{2}{\ntot} + \spannorm{X}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}} + \frac{2}{\ntot}\sqrt{\frac{\log |U|/\delta'}{2 n(s,a)}}.
    \end{align*}

    Next we would like to apply the concentration inequalities of \cite{maurer_empirical_2009}. To apply their theorems as stated, we must shift and normalize to define (for each $u \in U$)
    \begin{align*}
        X'_{u} := \frac{X_u - \min_{x \in \S}X_u(x)}{\spannorm{X_u }}
    \end{align*}
    so that $X'_{u} \in [0,1]$ almost surely. Fixing some $u \in U$ and applying \citet[Theorem 10]{maurer_empirical_2009}, assuming $n(s,a) \geq 2$, we have with probability at least $1 - 2 \delta'/|U|$ that
    \begin{align*}
        \left| \sqrt{\frac{n(s,a)}{n(s,a)-1}\Var_{\Phat_{sa}} \left[ X'_u\right]} - \sqrt{\Var_{P_{sa}} \left[ X'_u\right]} \right| &\leq \sqrt{\frac{2 \ln |U|/\delta'}{n(s,a)-1}}
    \end{align*}
    using the facts that by standard calculations, abbreviating $\nt = n(s,a)$ for convenience,
    \begin{align*}
        \E \left[\frac{1}{2\nt(\nt-1)} \sum_{i=1}^{\nt} \sum_{j=1}^{\nt} \left(X'_u(S^i_{sa}) - X'_u(S^j_{sa}) \right)^2 \right]&= \frac{\nt}{2\nt(\nt-1)} 0 + \frac{\nt(\nt-1)}{2\nt(\nt-1)}\E\left[ \left(X'_u(S^1_{sa}) - X'_u(S^2_{sa}) \right)^2 \right] \\
        &= \frac{1}{2} \left( 2\E \left[ \left(X'_u(S^1_{sa}) \right)^2\right] - 2\E \left[ X'_u(S^1_{sa}) \right]^2  \right) \\
        &= \Var \left[ X'_u(S^1_{sa}) \right] = \Var_{P_{sa}} \left[X'_u \right]
    \end{align*}
    and
    \begin{align*}
        \frac{1}{2\nt(\nt-1)} \sum_{i=1}^{\nt} \sum_{j=1}^{\nt} \left(\Vhpe^{s,u,s'}(S^i_{sa}) - \Vhpe^{s,u,s'}(S^j_{sa}) \right)^2 &= \frac{\nt}{\nt-1}\Phat_{sa} \left( X'_u - \Phat_{sa}X'_u\one  \right)^{\circ 2}\\
        &= \frac{\nt}{\nt-1}\Var_{\Phat_{sa}} \left[X'_u \right]
    \end{align*}
    (since \citet[Theorem 10]{maurer_empirical_2009} as stated involves the quantity $\frac{1}{2\nt(\nt-1)} \sum_{i=1}^{\nt} \sum_{j=1}^{\nt} \left(X'_u(S^i_{sa}) - X'_u(S^j_{sa}) \right)^2$ and its expectation). Taking a union bound and undoing the normalization and shifting, we have for all $u \in U$ that
    \begin{align}
        \left| \sqrt{\frac{n(s,a)}{n(s,a)-1}\Var_{\Phat_{sa}} \left[ X_u\right]} - \sqrt{\Var_{P_{sa}} \left[ X_u\right]} \right| &\leq \spannorm{X_u} \sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} \label{eq:concentration_variance_covering_step_1}
    \end{align}
    with probability at least $1 - 2 \delta'$. For any arbitrary probability distribution $\mu \in \R^\S$ we have that
    \begin{align}
        \left| \sqrt{\Var_\mu\left[ X \right] } - \sqrt{\Var_\mu\left[ X_{u^\star} \right] }\right| & \leq \frac{1}{\ntot} \label{eq:concentration_variance_covering_step_2}
    \end{align}
    since
    \begin{align*}
        \sqrt{\Var_\mu\left[ X \right] } &= \sqrt{\Var_\mu\left[ X_{u^\star} + (X - X_{u^\star}) \right] } \leq \sqrt{\Var_\mu\left[ X_{u^\star} \right]} + \sqrt{\Var_\mu\left[X - X_{u^\star} \right] }
    \end{align*}
    (where the inequality step follows from triangle inequality since $Y \mapsto \sqrt{\E Y^2}$ is a norm on random variables $Y$) and then we have
    \begin{align*}
        \sqrt{\Var_\mu\left[X - X_{u^\star} \right] } \leq \infnorm{X - X_{u^\star}} \leq \frac{1}{\ntot}.
    \end{align*}
    Thus combining~\eqref{eq:concentration_variance_covering_step_1} with~\eqref{eq:concentration_variance_covering_step_2} we conclude that
    \begin{align}
        &\left| \sqrt{\frac{n(s,a)}{n(s,a)-1}\Var_{\Phat_{sa}} \left[ X\right]} - \sqrt{\Var_{P_{sa}} \left[ X\right]} \right| \\
        &\qquad\leq \left| \sqrt{\frac{n(s,a)}{n(s,a)-1}\Var_{\Phat_{sa}} \left[ X_{u^\star}\right]} - \sqrt{\Var_{P_{sa}} \left[ X_{u^\star}\right]} \right| + \sqrt{\frac{n(s,a)}{n(s,a)-1}}\frac{1}{\ntot} + \frac{1}{\ntot}\nonumber\\
        & \qquad\leq \spannorm{X_{u^\star}} \sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \sqrt{\frac{n(s,a)}{n(s,a)-1}}\frac{1}{\ntot} + \frac{1}{\ntot} \nonumber\\
        & \qquad\leq \spannorm{X} \sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \frac{2}{\ntot}\sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \sqrt{\frac{n(s,a)}{n(s,a)-1}}\frac{1}{\ntot} + \frac{1}{\ntot} \label{eq:concentration_covering_true_vs_emp_var}
    \end{align}
    using~\eqref{eq:concentration_covering_span_bound} again in the final inequality.
    To obtain the slightly simplified bound~\eqref{eq:concentration_helper_lemma_emp_var_term} we use that by assumption $n(s,a) \geq 2$, so $\sqrt{\frac{n(s,a)}{n(s,a)-1}} \leq \sqrt{2} \leq 2$.

    Now, similarly to our use of Hoeffding's inequality, using Bernstein's inequality (e.g., \citet[Theorem 3]{maurer_empirical_2009}), as well as a union bound over all $u \in U$, we have that with probability at least $1 - 2 \delta'$, for all $u \in U$,
    \begin{align*}
        \left|(\Phat_{sa} - P_{sa}) X_{u} \right| \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ X_{u} \right] \log (|U|/\delta')}{n(s,a)}} + \spannorm{X_u}\frac{\log (|U|/\delta')}{3 n(s,a)}.
    \end{align*}
    Combining this inequality (for $u = u^\star$) along with~\eqref{eq:concentration_covering_step_1},~\eqref{eq:concentration_covering_span_bound}, and~\eqref{eq:concentration_variance_covering_step_2}, we obtain that
    \begin{align*}
        &\left|(\Phat_{sa} - P_{sa}) X \right| \\
        &\leq \left|(\Phat_{sa} - P_{sa}) X_{u^\star} \right| + \frac{2}{\ntot} \\
        & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ X_{u^\star} \right] \log (|U|/\delta')}{n(s,a)}} + \spannorm{X_u}\frac{\log (|U|/\delta')}{3 n(s,a)}+ \frac{2}{\ntot} \\
        & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)}}+ \frac{1}{\ntot} \sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)}} + \spannorm{X}\frac{\log (|U|/\delta')}{3 n(s,a)}+\frac{2}{\ntot}\frac{\log (|U|/\delta')}{3 n(s,a)}+ \frac{2}{\ntot}.
    \end{align*}
    Combining this with~\eqref{eq:concentration_covering_true_vs_emp_var} we furthermore obtain that
    \begin{align*}
        &\left|(\Phat_{sa} - P_{sa}) X \right| \\
        & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)}}+\spannorm{X}\frac{\log (|U|/\delta')}{3 n(s,a)}+ \frac{1}{\ntot} \left(\sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)}} +2\frac{\log (|U|/\delta')}{3 n(s,a)}+ 2\right) \\
        & \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)-1}}+\spannorm{X}\frac{\log (|U|/\delta')}{3 n(s,a)}+ \frac{1}{\ntot} \left(\sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)}} +2\frac{\log (|U|/\delta')}{3 n(s,a)}+ 2\right) \\
        & \qquad  + \sqrt{\frac{2  \log (|U|/\delta')}{n(s,a)}}\left(\spannorm{X} \sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \frac{2}{\ntot}\sqrt{\frac{2 \log |U|/\delta'}{n(s,a)-1}} + \sqrt{\frac{n(s,a)}{n(s,a)-1}}\frac{1}{\ntot} + \frac{1}{\ntot} \right) \\
        & \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)-1}}+\spannorm{X}\frac{7}{3}\frac{\log (|U|/\delta')}{ n(s,a)-1} \\
        & \qquad + \frac{1}{\ntot} \left(\sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)}} +2\frac{\log (|U|/\delta')}{3 n(s,a)}+ 2 + 2\frac{2 \log (|U|/\delta')}{n(s,a)-1} + 2\sqrt{\frac{2  \log (|U|/\delta')}{n(s,a)-1}}  \right) \\
        & \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ X \right] \log (|U|/\delta')}{n(s,a)-1}}+\spannorm{X}\frac{7}{3}\frac{\log (|U|/\delta')}{ n(s,a)-1} \\
        & \qquad+ \frac{1}{\ntot} \left(2 + 3\sqrt{\frac{2 \log (|U|/\delta')}{n(s,a)-1}} + \frac{14}{3}\frac{ \log (|U|/\delta')}{n(s,a)-1} \right).
    \end{align*}

\end{proof}


Now we develop several leave-one-out constructions which satisfy the conditions of Lemma \ref{lem:concentration_helper_lemma}.
\begin{lem}
    \label{lem:LOO_constructions}
    \begin{enumerate}
        \item (LOO construction for $\Vhpe^\star$) For each $s,a$, there exists a set $U^1_{sa} \subseteq \R$ with $|U^1_{sa}| \leq \frac{\ntot}{1-\gamma}$ and random vectors $(X^1_u)_{u \in U^1_{sa}}$ such that 1) for all $u \in U^1_{sa}$, $X^1_u$ is independent from $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$, and 2) almost surely there exists some $u \in U^1_{sa}$ such that $\infnorm{\Vhpe^\star - X^1_u} \leq \frac{1}{\ntot}$. \label{item:LOO_constructions_1}
        \item (LOO constructions for $T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\star)$) For each $s,a$, there exists a set $U^2_{sa}\subseteq \R$ with $|U^2_{sa}| \leq S\frac{\ntot}{1-\gamma}$ and random vectors $(X^2_u)_{u \in U^2_{sa}}$ such that 1) for all $u \in U^2_{sa}$, $X^2_u$ is independent from $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$, and 2) almost surely there exists some $u \in U^2_{sa}$ such that $\infnorm{T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\star) - X^2_u} \leq \frac{1}{\ntot}$. \label{item:LOO_constructions_2}
        \item (LOO construction for $\Vhpe^\pi$) Fix any policy $\pi$. For each $s,a$, there exists a set $U^3_{sa}\subseteq \R$ with $|U^3_{sa}| \leq \frac{\ntot}{1-\gamma}$ and random vectors $(X^3_u)_{u \in U^3_{sa}}$ such that 1) for all $u \in U^3_{sa}$, $X^3_u$ is independent from $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$, and 2) almost surely there exists some $u \in U^3_{sa}$ such that $\infnorm{\Vhpe^\pi - X^3_u} \leq \frac{1}{\ntot}$. \label{item:LOO_constructions_3}
        \item (LOO constructions for $T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\pi)$) Fix any policy $\pi$. For each $s,a$, there exists a set $U^4_{sa}\subseteq \R$ with $|U^4_{sa}| \leq S\frac{\ntot}{1-\gamma}$ and random vectors $(X^4_u)_{u \in U^4_{sa}}$ such that 1) for all $u \in U^4_{sa}$, $X^4_u$ is independent from $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$, and 2) almost surely there exists some $u \in U^4_{sa}$ such that $\infnorm{T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\pi) - X^4_u} \leq \frac{1}{\ntot}$. \label{item:LOO_constructions_4}
    \end{enumerate}
\end{lem}

\begin{proof}
    We start by showing \autoref{item:LOO_constructions_1}. Fix arbitrary $s \in \S, a \in \A$. For any $u \in \R$ we define the reward function $r^{s,u} \in \R^{\S \A}$, (random) transition matrix $\Phat^s \in \R^{\S\A \times \S}$, and (random) operator $\Tope^{s,u} : \R^\S \to \R^{\S\A}$ by (for arbitrary $s' \in \S, a' \in \S, V \in \R^\S$)
    \begin{align*}
        \Phat^{s}_{s'a'} &= \begin{cases}
            e_{s}^\top & s' = s \\
            \Phat_{s'a'} &  s' \neq s
        \end{cases} \\
        r^{s,u}(s',a') &= \begin{cases}
            u & s' = s \\
            r(s',a') &  s' \neq s
        \end{cases} \\
        \Tope^{s,u}(V)(s',a') &= r^{s,u}(s',a') +\gamma\max \left\{  \Phat^s_{s'a'} T_{\beta(s',a')}( \Phat^s_{s'a'}, V) - b^s(s',a', V), \min_{s''}(V)(s'') \right \}
    \end{align*}
    where
    \begin{align}
        b^{s}(s',a', V) := \max \left \{ \sqrt{\beta(s',a')   \Var_{\Phat^s_{s'a'}} \left[T_{\beta(s',a')}(\Phat^s_{s'a'}, V)\right]  } , \beta(s',a') \spannorm{ T_{\beta(s',a')}(\Phat^s_{s'a'}, V)} \right\} + \frac{5}{\ntot} \label{eq:LOO_penalty_term}
    \end{align}
    Note $e_{s}^\top$ is a vector which is all $0$ except for a $1$ in state $s$, meaning that state $s$ is absorbing in $\Phat^{s,u}$, for all actions. Also all actions receive reward $u$ in this state. All other state-action pairs have the same rewards and transition distributions as in the MDP $(\Phat, r)$. Also, we have defined $b^s$ and $\Tope^{s,u}$ in an identical manner to $b$ and $\Tope$, except we now use $r^{s,u}$ and $\Phat^{s}$ in place of $r$ and $\Phat$. Since all of the properties of $\Tope$ verified above only required $\Phat$ to be a valid transition matrix and for $r$ to be a vector in $[0,1]^{\S\A}$, the properties hold identically for $\Tope^{s,u}$, and thus by Lemma \ref{lem:tope_additional_properties} we have that $\Tope^{s,u}$ is $\gamma$-Lipschitz.

    Now we define $\Lhat^{s,u} : \R^\S \to \R^\S$ as $\Lhat^{s,u}(V) := M \Tope^{s,u} (V)$ (for any $V \in \R^\S$). By the $\gamma$-Lipschitzness of $\Tope^{s,u}$ and the $1$-Lipschitzness of $M$, we immediately have that $\Lhat^{s,u}$ is a $\gamma$-contraction, since
    \begin{align*}
        \infnorm{\Lhat^{s,u}(V_1) - \Lhat^{s,u}(V_2)} = \infnorm{M \Tope^{s,u}(V_1) - M \Tope^{s,u}(V_2) } \leq \infnorm{\Tope^{s,u}(V_1) -  \Tope^{s,u}(V_2)} \leq \gamma \infnorm{V_1 - V_2}
    \end{align*}
    for any $V_1, V_2 \in \R^\S$. Therefore contractivity implies that there exists a unique fixed point of $\Lhat^{s,u}$ (e.g. \cite[Chapter 4.5]{pugh_real_2015}), which we call $X^1_u$. Note that since $\Lhat^{s,u}$ is defined without using $\Phat_{sa}$, it is independent of all samples $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$ drawn from $P(\cdot \mid s,a)$.

    Now, as intermediate steps, we show the following two properties:
    \begin{enumerate}
        \item[A.] For any $u, u' \in \R$, we have $\infnorm{X^1_u - X^1_{u'}} \leq \frac{|u-u'|}{1-\gamma}$.
        \item[B.] Letting $U^\star = \Vhpe^\star(s) - \gamma \max_{\widetilde{a} \in \A}\max \left\{ \Phat^s_{s\widetilde{a}}T_{\beta(s,\widetilde{a})}(\Phat^s_{s\widetilde{a}}, \Vhpe^\star) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\}$, we have $X^1_{U^\star} = \Vhpe^\star$, and $U^\star \in [0,1]$. 
    \end{enumerate}

    For A, letting $u, u' \in \R$, we can calculate that
    \begin{align*}
        \infnorm{X^1_u - X^1_{u'}} &= \infnorm{\Lhat^{s,u}(X^1_u) - \Lhat^{s,u'}(X^1_{u'})} = \infnorm{M \Tope^{s,u}(X^1_u) - M\Tope^{s,u'}(X^1_{u'})} \\
        & \leq \infnorm{ \Tope^{s,u}(X^1_u) - \Tope^{s,u'}(X^1_{u'})} \\
        & =\infnorm{ r^{s,u} - r^{s,u'} + \Tope^{s,u'}(X^1_u) - \Tope^{s,u'}(X^1_{u'})} \\
        & \leq \infnorm{ r^{s,u} - r^{s,u'}} + \infnorm{\Tope^{s,u'}(X^1_u) - \Tope^{s,u'}(X^1_{u'})} \\
        & \leq |u-u'| + \gamma \infnorm{X^1_u - X^1_{u'}}
    \end{align*}
    where the key equality step was that $\Tope^{s,u}(X^1_u) = r^{s,u} - r^{s,u'} + \Tope^{s,u'}(X^1_u)$, and in the final inequality we used $\gamma$-Lipschitzness of $\Tope^{s,u'}$. Rearranging we obtain that $\infnorm{X^1_u - X^1_{u'}} \leq \frac{|u-u'|}{1-\gamma}$ as desired, verifying A.

    For B we first check that $X^1_{U^\star} = \Vhpe^\star$. It suffices to check that $M \Tope^{s, U^\star}(\Vhpe^\star) = M \Tope(\Vhpe^\star)$, because then we would have that 
    \begin{align*}
        \Lhat^{s,U^\star}(\Vhpe^\star) = M \Tope^{s, U^\star}(\Vhpe^\star) = M \Tope(\Vhpe^\star) = M\Thpe(\Qhpe^\star) = M \Qhpe^\star = \Vhpe^\star
    \end{align*}
    thus showing that $\Vhpe^\star$ is a fixed point of $\Lhat^{s,U^\star}$, and by uniqueness of this fixed point we must have $X^1_{U^\star} = \Vhpe^\star$. Comparing the definitions of $\Tope(\Vhpe^\star)$ and $\Tope^{s, U^\star}(\Vhpe^\star)$, it is immediate that $M \left(\Tope^{s, U^\star}(\Vhpe^\star)\right)(s') = M \left(\Tope(\Vhpe^\star)\right)(s')$ for all $s' \neq s$, so it remains to check the equality for $s' = s$. 

    First we argue that for all $a' \in \A$, we have $b^s(s, a', \Vhpe^\star ) = \frac{5}{\ntot}.$ If $\beta(s,a') > 1$ then we have $T_{\beta(s,a')}(\Phat^s_{sa'}, \Vhpe^\star) = \left(\min_{s'} \Vhpe^\star(s') \right)\one$, and if $\beta(s,a') \leq 1$ then we have $T_{\beta(s,a')}(\Phat^s_{sa'}, \Vhpe^\star) =  \Vhpe^\star(s)\one$, since $\Phat^s_{sa'} = e_s^\top$ ($\Phat^s_{sa'}$ transitions to state $s$ with probability $1$). Either way $T_{\beta(s,a')}(\Phat^s_{sa'}, \Vhpe^\star)$ is a multiple of the all-ones vector, which implies $\Var_{\Phat^s_{s'a'}} \left[T_{\beta(s',a')}(\Phat^s_{s'a'}, \Vhpe^\star)\right] = 0$ and $\spannorm{ T_{\beta(s',a')}(\Phat^s_{s'a'}, \Vhpe^\star)} = 0$, and thus that $b^s(s, a', \Vhpe^\star ) = \frac{5}{\ntot}.$ Therefore by the construction of $U^\star$ we have that
    \begin{align*}
        M \left(\Tope^{s, U^\star}(\Vhpe^\star)\right)(s) &= \max_{a'} U^\star + \gamma\max \left\{  \Phat^s_{sa'} T_{\beta(s,a')}( \Phat^s_{sa'}, \Vhpe^\star) - b^s(s,a', \Vhpe^\star), \min_{s''}(\Vhpe^\star)(s'') \right \} \\
        &= \max_{a'} U^\star +\gamma \max \left\{ \Phat^s_{sa'} T_{\beta(s,a')}( \Phat^s_{sa'}, \Vhpe^\star) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} \\
        &=   \Vhpe^\star(s) - \gamma \max_{\widetilde{a} \in \A}\max \left\{ \Phat^s_{s\widetilde{a}}T_{\beta(s,\widetilde{a})}(\Phat^s_{s\widetilde{a}}, \Vhpe^\star) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} \\
        & \qquad+\gamma \max_{a'} \max \left\{ \Phat^s_{sa'} T_{\beta(s,a')}( \Phat^s_{sa'}, \Vhpe^\star) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} \\
        &= \Vhpe^\star(s) = M \left(\Tope(\Vhpe^\star)\right)(s)
    \end{align*}
    as desired, so we have checked that $X^1_{U^\star} = \Vhpe^\star$.

    Now it remains to verify that $U^\star \in [0,1]$. Given our calculation of $T_{\beta(s,a')}(\Phat^s_{s a'}, \Vhpe^\star)$ (for any $a' \in \A$) above, we have the alternate expression for $U^\star$
    \begin{align*}
        U^\star &= \Vhpe^\star(s)  - \gamma \begin{cases}
            \max \left\{ \Vhpe^\star(s) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} & \exists a' \in \A : \beta(s, a') \leq 1 \\
            \max \left\{ \min_{s''} \Vhpe^\star(s'') - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} & \text{o.w.}
        \end{cases} \\
        &= \Vhpe^\star(s)  - \gamma \begin{cases}
            \max \left\{ \Vhpe^\star(s) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} & \exists a' \in \A : \beta(s, a') \leq 1 \\
             \min_{s''} \Vhpe^\star(s'') & \text{o.w.}
        \end{cases}.
    \end{align*}
    We consider the two cases in the above expression. If $\exists a' \in \A : \beta(s, a') \leq 1$, then we can upper bound $U^\star$ as
    \begin{align*}
        U^\star \leq  \Vhpe^\star(s) - \gamma \max \left\{ \Vhpe^\star(s) - \frac{5}{\ntot}, \min_{s''} \Vhpe^\star(s'')\right\} \leq \Vhpe^\star(s) - \gamma \Vhpe^\star(s) \leq (1-\gamma)\frac{1}{1-\gamma} = 1
    \end{align*}
    where the last inequality is due to the fact that $\Vhpe^\star = M \Qhpe^\star \leq M\frac{1}{1-\gamma}\one = \frac{1}{1-\gamma}\one$ (by Lemma \ref{lem:pessimistic_Bellman_operator_properties}). For the lower bound in this case, we have
    \begin{align*}
        U^\star = \min \left\{ (1-\gamma)\Vhpe^\star(s) + \frac{5}{\ntot}, \Vhpe^\star(s) - \min_{s''} \Vhpe^\star(s'')\right\}
    \end{align*}
    which is clearly $\geq 0$ (note the first term within the $\min$ is $\geq 0$ by Lemma \ref{lem:pessimistic_Bellman_operator_properties}). 

    Now we consider the case that there does not exist $a' \in \A $ such that $ \beta(s, a') \leq 1$, that is, the case that $\beta(s,a') > 1$ for all $a' \in \A$. Then as argued above we have for all $a' \in \A$ that $T_{\beta(s,a')}(\Phat_{sa'}, \Vhpe^\star) = \left(\min_{s''} \Vhpe^\star(s'') \right)\one$, and so by the definition of $\Thpe$ and the fact that $\Qhpe^\star $ is its fixed point and $\Vhpe^\star = M \Qhpe^\star$, we have
    \begin{align*}
        \Vhpe^\star(s) &=\max_{a' \in \A} r(s,a') +\gamma\max \left\{  \Phat_{sa'} T_{\beta(s,a')}( \Phat_{sa'}, \Vhpe^\star) - b(s,a', \Vhpe^\star), \min_{s''} \Vhpe^\star(s'') \right \} \\
        &= \max_{a' \in \A} r(s,a') +\gamma\max \left\{  \min_{s''} \Vhpe^\star(s'') -b(s,a', \Vhpe^\star), \min_{s''} \Vhpe^\star(s'') \right \} \\
        &= \max_{a' \in \A} r(s,a') +\gamma \min_{s''} \Vhpe^\star(s'') 
    \end{align*}
    (using the fact that $b(s,a', \Vhpe^\star) \geq 0$ to compute the max). Hence in this case
    \begin{align*}
        U^\star = \Vhpe^\star(s) - \gamma \min_{s''} \Vhpe^\star(s'') = \max_{a' \in \A} r(s,a') +\gamma \min_{s''} \Vhpe^\star(s'')-  \gamma \min_{s''} \Vhpe^\star(s'') = \max_{a' \in \A} r(s,a')
    \end{align*}
    which is clearly in $[0,1]$.
    We have thus verified B.

    Now unfix $u$ and let $U^1_{sa}$ be a set of $\frac{\ntot}{1-\gamma}$ points chosen by dividing $[0,1]$ into $\frac{\ntot}{1-\gamma}$ intervals and placing a point at the midpoint of each such interval. Note this guarantees that for any $x \in [0,1]$ there exists some $u \in U$ such that $|x-u| \leq \frac{1-\gamma}{2\ntot}$. Therefore, letting $\widetilde{U}^\star \in U$ be this closest point in $U$ to the value $U^\star $, we have by A and B that
    \begin{align*}
        \infnorm{X^1_{\widetilde{U}^\star} - \Vhpe^\star} = \infnorm{X^1_{\widetilde{U}^\star} - X^1_{U^\star}} \leq \frac{|\widetilde{U}^\star-U^\star|}{1-\gamma} \leq \frac{1}{1-\gamma}\frac{1-\gamma}{2\ntot} = \frac{1}{2\ntot} \leq \frac{1}{\ntot}.
    \end{align*}
    Therefore we have confirmed \autoref{item:LOO_constructions_1}.

    Now we continue to \autoref{item:LOO_constructions_2}. Fix $s \in \S, a \in \A$, and define $U^2_{sa} = U^1_{sa} \times \S$. For each $u, s' \in U^2_{sa}$, we define
    \begin{align*}
        X^2_{u,s'} = \clip(X^1_{u}, X^1_{u}(s')),
    \end{align*}
    that is, we clip all entries of the vector $X^1_{u}$ constructed in the previous part so that they are $\leq X^1_{u}(s')$. Since $X^1_{u}$ was independent of all samples $S^1_{sa}, \dots, S^{n(s,a)}_{sa}$ drawn from $P(\cdot \mid s,a)$, the same is true of $X^2_{u,s'}$. Define $S^\star(s,a)$ to be a state such that $Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^\star) = \Vhpe^\star(S^\star(s,a))$ (if multiple states satisfy this, we can break ties in some consistent manner). Then for any $u, s' \in U^2_{sa}$ we have
    \begin{align}
        \infnorm{T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\star) - X^2_{u,s'}} &= \infnorm{\clip\left(\Vhpe^\star, Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^\star)\right) - \clip(X^1_{u}, X^1_{u}(s'))} \nonumber\\
        &=\infnorm{\clip\left(\Vhpe^\star, \Vhpe^\star(S^\star(s,a))\right) - \clip(X^1_{u}, X^1_{u}(s'))} \nonumber\\
        &\leq \infnorm{\clip\left(\Vhpe^\star, \Vhpe^\star(S^\star(s,a))\right) - \clip\left(X^1_{u}, \Vhpe^\star(S^\star(s,a))\right)} \nonumber \\
         &\qquad +\infnorm{ \clip\left(X^1_{u}, \Vhpe^\star(S^\star(s,a))\right)  -\clip(X^1_{u}, X^1_{u}(s'))} \nonumber \\
         & \leq \infnorm{\Vhpe^\star - X^1_u} + \left|\Vhpe^\star(S^\star(s,a)) -  X^1_{u}(s')\right|. \label{eq:LOO_constructions_2_intermediate_bound}
    \end{align}
    From \autoref{item:LOO_constructions_1} we know there exists some $u \in U^1_{sa}$ such that $\infnorm{\Vhpe^\star - X^1_u} \leq \frac{1}{2\ntot}$, and furthermore if $s' = S^\star(s,a)$ then
    \begin{align*}
        \left|\Vhpe^\star(S^\star(s,a)) -  X^1_{u}(s')\right| = \left|\Vhpe^\star(s') -  X^1_{u}(s')\right| \leq \infnorm{\Vhpe^\star - X^1_u} \leq \frac{1}{2\ntot}.
    \end{align*}
    Combining these with~\eqref{eq:LOO_constructions_2_intermediate_bound} we conclude that almost surely there exists some $(u, s') \in U^1_{sa} \times \S = U^2_{sa}$ such that $\infnorm{T_{\beta(s,a)}(\Phat_{sa},\Vhpe^\star) - X^2_{u,s'}} \leq \frac{1}{\ntot}$ as desired. Therefore we have confirmed \autoref{item:LOO_constructions_2}.

    For \autoref{item:LOO_constructions_3} and \autoref{item:LOO_constructions_4}, we can use nearly identical constructions, with the only difference being that for \autoref{item:LOO_constructions_3} we define $X^3_u$ to be the fixed point of the operator $\Lhat^{\pi, s,u} : \R^\S \to \R^\S$ as $\Lhat^{\pi, s,u}(V) := M^\pi \Tope^{s,u} (V)$ (and otherwise use the same construction as for $X^1_u$), and then for \autoref{item:LOO_constructions_4} we use $X^3_u$ in place of $X^1_u$ in the construction for $X^2_u$. Thus, the key difference is replacing $M$ with $M^\pi$ within the construction for $X^3_u$, and since the only properties of $M$ used were $1$-Lipschitzness and that $M \one = \one$, which both hold with $M^\pi$ in place of $M$, and also the fact that $\Vhpe^\star = M \Qhpe^\star$ which is analogous to the fact that $\Vhpe^{\pi} = M^{\pi} \Qhpe^{\pi}$, all steps work in an analogous manner.
\end{proof}


Now we can prove the key concentration inequalities needed for the rest of the proof.

\begin{lem}
    \label{lem:concentration_for_pessimism_Thpe}
    With probability at least $1 - \delta$, for all $s \in \S, a \in \A$, if $n(s,a) \geq 1+8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, then
    \begin{align*}
         &\left|\left(\Phat_{sa}  - P_{sa}\right) T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right| \\
         & \qquad\leq \max \left \{ \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)\right]  } , \beta(s,a) \spannorm{ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)} \right\} + \frac{4.5}{\ntot} \\
         &\qquad =  b(s,a, \Vhpe^\star) - \frac{1}{2 \ntot}
    \end{align*}
    where $\alpha = 8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$ and $\beta(s,a) = \alpha/(n(s,a)-1)$.
\end{lem}
\begin{proof}
    Fix some $s \in \S$ and $a \in \A$. If $n(s,a) < 1+8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$ then we have nothing to check. Otherwise, we can immediately combine \autoref{item:LOO_constructions_2} of Lemma \ref{lem:LOO_constructions} (which gives $|U| \leq S\frac{\ntot}{1-\gamma}$) with Lemma \ref{lem:concentration_helper_lemma} (since our condition on $n(s,a)$ clearly implies $n(s,a) \geq 2$) to conclude that with probability at least $1 - 6 \delta'$,
    \begin{multline*}
        \left|(\Phat_{sa} - P_{sa}) T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right| \\
        \qquad \qquad \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right] \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{n(s,a)-1}}+\spannorm{T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)}\frac{7}{3}\frac{\log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{ n(s,a)-1} \\
         + \frac{1}{\ntot} \left(2 + 3\sqrt{\frac{2 \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{n(s,a)-1}} + \frac{14}{3}\frac{ \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{n(s,a)-1} \right).
    \end{multline*}
    Taking a union bound over all $s \in \S, a \in \A$, and setting $\delta' = \frac{\delta}{6SA}$, we obtain that with probability at least $1 - \delta$, for all $s \in \S, a \in \A$ where $n(s,a) \geq 1+8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, we have
    \begin{align*}
        &\left|(\Phat_{sa} - P_{sa}) T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right|  \\
        & \leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1}}+\spannorm{T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)}\frac{7}{3}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ n(s,a)-1} \\
         & \qquad\qquad\qquad+ \frac{1}{\ntot} \left(2 + 3\sqrt{\frac{2 \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1}} + \frac{14}{3}\frac{ \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1} \right)\\
          &\quad\leq \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1}}+\spannorm{T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)}\frac{7}{3}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ n(s,a)-1} + \frac{4.5}{\ntot} \\
          &\quad\leq 2\max \left\{ \sqrt{\frac{2 \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1}}, \spannorm{T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)}\frac{7}{3}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ n(s,a)-1} \right\} + \frac{4.5}{\ntot} \\
          &\quad= \max \left\{ \sqrt{\frac{8 \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star) \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)-1}}, \spannorm{T_{\beta(s,a)}(\Phat_{sa},  \Vhpe^\star)}\frac{14}{3}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ n(s,a)-1} \right\} + \frac{4.5}{\ntot} \\
          &\quad\leq b(s,a, \Vhpe^\star) - \frac{1}{2\ntot}.
    \end{align*}
    where the second inequality uses the assumption that $n(s,a) \geq 1+8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$ and the fact that $2 + 3 \sqrt{\frac{1}{4}} + \frac{14}{3}\frac{1}{8} < 4.5$, and then we bounded $a + b \leq 2 \max\{a,b\}$.
\end{proof}

\begin{lem}
    \label{lem:concentration_for_pessimism_Thpe_pistar}
    Fix any policy $\pistar$.
    With probability at least $1 - 2\delta$, for all $s \in \S, a \in \A$, if $n(s,a) \geq 1 + 8\ln \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, then
    \begin{align*}
         &\left|\left(\Phat_{sa}  - P_{sa}\right) T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) \right| \\
         &\qquad \leq \max \left \{ \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})\right]  } , \beta(s,a) \spannorm{ T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \right\} + \frac{5}{\ntot} \\
         &\qquad = b(s,a, \Vhpe^{\pistar})  
    \end{align*}
    and
    \begin{align}
        \sqrt{\Var_{\Phat_{sa}} \left[\Vhpe^{\pistar}\right] } \leq \sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\frac{2 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{n(s,a)}} + \frac{4}{\ntot} \label{eq:concentration_for_pessimism_Thpe_pistar_variance}
    \end{align}
    and
    \begin{align}
         \left|(\Phat_{sa} - P_{sa}) \Vhpe^{\pistar} \right| & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)}}+\spannorm{\Vhpe^{\pistar}}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ 3n(s,a)} + \frac{3}{\ntot} \label{eq:concentration_for_pessimism_Thpe_pistar_bernstein}
    \end{align}
    where $\alpha = 8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$ and $\beta(s,a) = \alpha/(n(s,a)-1)$.
\end{lem}
\begin{proof}
    The first statement is analogous to Lemma \ref{lem:concentration_for_pessimism_Thpe} but uses the construction of \autoref{item:LOO_constructions_4} of Lemma \ref{lem:LOO_constructions} in place of \autoref{item:LOO_constructions_2}. Thus combining \autoref{item:LOO_constructions_4} of Lemma \ref{lem:LOO_constructions} with Lemma \ref{lem:concentration_helper_lemma}, taking a union bound and performing the same simplifications, we obtain that with probability at least $1 - \delta$,
    for all $s \in \S, a \in \A$, if $n(s,a) \geq 1 + 8\ln \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, then
    \begin{align*}
         \left|\left(\Phat_{sa}  - P_{sa}\right) T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) \right| & \leq b(s,a, \Vhpe^{\pistar}) .
    \end{align*}

    Now we establish the second two properties. We will show that they both hold with probability $1-\delta$, after which we are done since we can then use a union bound to combine with the above. Fixing some $s \in \S$ and $a \in \A$, if $n(s,a) < 1+8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$ then we have nothing to check. Otherwise, we can immediately combine \autoref{item:LOO_constructions_3} of Lemma \ref{lem:LOO_constructions} (which gives $|U| \leq \frac{\ntot}{1-\gamma} \leq S\frac{\ntot}{1-\gamma}$) with Lemma \ref{lem:concentration_helper_lemma} (since our condition on $n(s,a)$ implies $n(s,a) \geq 2$) to conclude that with probability at least $1 - 6 \delta'$, we have both
    \begin{align}
        \left|(\Phat_{sa} - P_{sa}) \Vhpe^{\pistar} \right| & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right] \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{n(s,a)}}+\spannorm{\Vhpe^{\pistar}}\frac{\log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{ 3n(s,a)} \nonumber\\
         &\qquad \qquad + \frac{1}{\ntot} \left(2 + \sqrt{\frac{2 \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{n(s,a)}} + 2\frac{ \log \left(S\frac{\ntot}{(1-\gamma)\delta'} \right)}{3n(s,a)} \right) \label{eq:concentration_for_pessimism_Thpe_pistar_1}
    \end{align}
    and
    \begin{align}
        \sqrt{\frac{n(s,a)}{n(s,a)-1}}\sqrt{\Var_{\Phat_{sa}} \left[\Vhpe^{\pistar}\right]} &\leq \sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\frac{2 \log \left( \frac{S\ntot}{(1-\gamma)\delta'}\right)}{n(s,a)-1}} \\
        & \qquad \qquad + \frac{1}{\ntot}\left(2\sqrt{\frac{2 \log \left( \frac{S\ntot}{(1-\gamma)\delta'}\right)}{n(s,a)-1}}  + 3\right).\label{eq:concentration_for_pessimism_Thpe_pistar_2}
    \end{align}
    Taking a union bound over all $s, a \in \S, \A$ and setting $\delta' = \frac{\delta}{6SA}$, we have that with probability at least $1 - \delta$, for all $s,a$ such that $n(s,a) \geq 1 + 8\ln \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, both
    \begin{align*}
        \left|(\Phat_{sa} - P_{sa}) \Vhpe^{\pistar} \right| & \leq \sqrt{\frac{2 \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)}}+\spannorm{\Vhpe^{\pistar}}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ 3n(s,a)} + \frac{3}{\ntot}
    \end{align*}
    and
    \begin{align*}
        \sqrt{\Var_{\Phat_{sa}} \left[\Vhpe^{\pistar}\right]} &\leq \sqrt{\frac{n(s,a)-1}{n(s,a)}}\sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\frac{2 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{n(s,a)}} \\
        & \qquad \qquad + \frac{1}{\ntot}\left(2\sqrt{\frac{2 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{n(s,a)}}  + 3\right) \\
        & \leq \sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\frac{2 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{n(s,a)}} + \frac{4}{\ntot}
    \end{align*}
    where for the first bound we simplified~\eqref{eq:concentration_for_pessimism_Thpe_pistar_1} using the condition on $n(s,a)$ and the fact that $2 + \sqrt{\frac{2}{8}} + \frac{2}{3}\frac{1}{8} < 3$, and for the second bound we simplified~\eqref{eq:concentration_for_pessimism_Thpe_pistar_2} also using the condition on $n(s,a)$ and then the fact that $2 \sqrt{\frac{2}{8}} + 3 = 4$.
\end{proof}



\subsection{Pessimism}
In this subsection we establish the following essential pessimism property, making use of the previous concentration results and our construction of $\Thpe$.

\begin{lem}
    \label{lem:pessimism}
    Under the event in Lemma \ref{lem:concentration_for_pessimism_Thpe}, we have that
    \begin{align*}
        Q^{\pihat} \geq \Qhat.
    \end{align*}
\end{lem}
\begin{proof}
    We will show that $\T^{\pihat}(\Qhat) \geq \Qhat$ (where $\T^{\pihat}(Q) := r + PM^{\pihat} Q$ is the Bellman evaluation operator for $\pihat$), which by a standard argument implies that $Q^{\pihat} \geq \Qhat$, since we can then easily derive (by monotonicity of $\T^{\pihat}$) that $(\T^{\pihat})^{(k)}(\Qhat) \geq \Qhat$ for any integer $k \geq 0$, and thus
    \begin{align*}
        Q^{\pihat} = \lim_{k\to\infty}(\T^{\pihat})^{(k)}(\Qhat) \geq \Qhat.
    \end{align*}
    Fixing arbitrary $s \in \S, a \in \A$, we will now verify that $\T^{\pihat}(\Qhat)(s,a) \geq \Qhat(s,a)$. From Lemma \ref{lem:opt_guarantees} we have that $\Thpe(\Qhat)(s,a) \geq \Qhat(s,a)$.
    We consider two cases based upon the value of $\Thpe(\Qhat)(s,a)$, which by~\eqref{eq:defn_of_Thpe} is either 1) equal to $r(s,a) + \gamma \Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, M\Qhat) - \gamma b(s,a,M\Qhat)$ or 2) equal to $r(s,a) + \gamma \min_{s'} (M\Qhat)(s')$. In the simpler case 2, we thus have that
    \begin{align*}
        \Thpe(\Qhat)(s,a) = r(s,a) + \gamma \min_{s'} (M\Qhat)(s') \leq r(s,a) + \gamma P_{sa} M \Qhat = r(s,a) + \gamma P_{sa} M^{\pihat} \Qhat = \T^{\pihat}(\Qhat)(s,a)
    \end{align*}
    using the facts that $\min_{s'} V(s') \leq P_{sa} V$ for any $V \in \R^{\S}$ (since $P_{sa}$ is a probability distribution) and that $M \Qhat = M^{\pihat} \Qhat$ since $\pihat$ is greedy with respect to $\Qhat$. We therefore have that $\Qhat(s,a) \leq \Thpe(\Qhat)(s,a) \leq \T^{\pihat}(\Qhat)(s,a)$ in case 2, as desired. Now we consider case 1. Note that since we are in case 1, we must have that $\beta(s,a) \leq 1$, or equivalently that $n(s,a) \geq \alpha + 1$ (because if we had $\beta(s,a) > 1$, then we would have $T_{\beta(s,a)}(\Phat_{sa}, M\Qhat) = \min_{s'} (M\Qhat)(s')$, and $b(s,a, M\Qhat)>0$, so the term $T_{\beta(s,a)}(\Phat_{sa}, M\Qhat) - b(s,a, M\Qhat)$ could not have achieved the maximum in the definition~\eqref{eq:defn_of_Thpe} of $\Thpe$). Then we have that
    \begin{align*}
        \Qhat(s,a) &\leq \Thpe(\Qhat)(s,a) \\
        & \leq \Thpe(\Qhpe^\star)(s,a) = r(s,a) + \gamma \Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, M\Qhpe^\star) - \gamma b(s,a,M\Qhpe^\star) \\
        & \leq r(s,a) + \gamma P_{sa} T_{\beta(s,a)}(\Phat_{sa}, M\Qhpe^\star) + \gamma \left|(\Phat_{sa} - P_{sa}) T_{\beta(s,a)}(\Phat_{sa}, M\Qhpe^\star)\right| - \gamma b(s,a,M\Qhpe^\star) \\
        & \leq r(s,a) + \gamma P_{sa} T_{\beta(s,a)}(\Phat_{sa}, M\Qhpe^\star) + \gamma b(s,a,M\Qhpe^\star) - \frac{1}{2\ntot} - \gamma b(s,a,M\Qhpe^\star) \\
        & \leq r(s,a) + \gamma P_{sa} M\Qhpe^\star -\frac{1}{2\ntot} \\
        & \leq r(s,a) + \gamma P_{sa} M\Qhat \\
        & = r(s,a) + \gamma P_{sa} M^{\pihat}\Qhat = \T^{\pihat}(\Qhat)(s,a)
    \end{align*}
    where the first inequality is due to $\Thpe(\Qhat) \geq \Qhat$ from Lemma \ref{lem:opt_guarantees}, the second inequality is due to monotonicity of $\Thpe$ (Lemma \ref{lem:pessimistic_Bellman_operator_properties}) and the fact that $\Qhat \leq \Qhpe^\star$ (Lemma \ref{lem:opt_guarantees}), the third inequality is by triangle inequality, the fourth inequality is from Lemma \ref{lem:concentration_for_pessimism_Thpe}, the fifth inequality is from the trivial fact that elementwise $T_{\beta(s,a)}(\Phat_{sa}, M\Qhpe^\star) \leq M \Qhpe^\star$, the sixth inequality follows from $\Qhpe^\star \leq \Qhat + \frac{1}{2\ntot}\one$ due to Lemma \ref{lem:opt_guarantees} (since by monotonicity of $M$, $M\Qhpe^\star \leq M(\Qhat + \frac{1}{2\ntot}\one) = M \Qhat + \frac{1}{2\ntot}\one$), and the final equality is from the definition of $\pihat$ (from Algorithm \ref{alg:LCBVI}) since it is greedy with respect to $\Qhat$. Combining the two cases we have shown that $\T^{\pihat}(\Qhat) \geq \Qhat$ as desired.
    Combining the two cases we have shown that $\T^{\pihat}(\Qhat) \geq \Qhat$ as desired.
\end{proof}

