\subsection{Policy hitting radius lemmas}
\label{sec:pol_hit_rad_lemmas}

In this subsection we establish some key properties regarding the relationship between $\Dow$ and certain discounted policy occupancy measures which will appear in later analysis steps. We also establish some facts about $\Dow$ of general interest and compare it to the mixing time.

Recall that $\eta_{s} := \inf\{t \geq 0 : S_t = s\}$ is the first hitting time of state $s$.
We define an additional useful quantity: for any $s^\star \in \S$, let
\begin{align*}
    \Dow(P, \pi, s^\star) := \sup_{s_0} \E_{s_0}^\pi \eta_{s^\star}.
\end{align*}
This is the maximum expected hitting time of state $s^\star$ in the Markov chain $P_\pi$ (which can be infinite). Then we have
\begin{align*}
    \Dow(P, \pi) := \inf_{s^\star} \Dow(P, \pi, s^\star) = \inf_{s^\star} \sup_{s_0} \E_{s_0}^\pi \eta_{s^\star}.
\end{align*}
$\Dow(P, \pi)$ is finite if and only if $P_\pi$ is unichain:
\begin{lem}
    \label{lem:Dow_finite_unichain}
    Fix a policy $\pi$ and an MDP transition kernel $P$. Then the Markov chain $P_\pi$ is unichain if and only if $\Dow(P, \pi)$ is finite.
\end{lem}
\begin{proof}
    First, suppose that $\Dow(P, \pi)$ is finite. Then there exists some $s^\star$ such that for all $s_0 \in \S$, $\E^\pi_{s_0} \eta_{s^\star} < \infty$. Therefore $s^\star$ is reachable from any state, so all recurrent classes must contain $s^\star$, but since the irreducible closed recurrent classes (along with the transient states) form a partition of $\S$, this implies that there can only be one closed irreducible recurrent class, that is that $P_\pi$ is unichain.

    Next, suppose that $P_\pi$ is unichain. Let $\tilde{s}^\star$ be some state in the single closed irreducible recurrent class of $P_\pi$. Now we argue that $\E_{s_0}^\pi[\eta_{\tilde{s}^\star}] < \infty$ for any $s_0 \in \S$. First, it is a standard fact (in finite Markov chains) that letting $C$ be the recurrent class, we have $M := \max_{s_0 \in C} \E_{s_0}^\pi[\eta_{\tilde{s}^\star}] < \infty$ (e.g. \cite{kemeny_finite_1976}, where $\E_{s_0}^\pi[\eta_{\tilde{s}^\star}]$ is referred to as the mean first passage time). Now letting $s_0$ be any fixed transient state, since there exists a unique irreducible recurrent class $C$, letting $\eta_C = \inf\{t \geq 0 : S_t \in C\}$ be its first hitting time, it is also a standard fact (for finite Markov chains) that $\E_{s_0}^\pi \eta_C < \infty$ (replacing $C$ with a single absorbing state, the new chain becomes an absorbing chain, and the absorption time formulas in \cite{kemeny_finite_1976} imply $\E_{s_0}^\pi \eta_C < \infty$). Then a calculation using the strong Markov property (where $\mathcal{F}_{\eta_C}$ is the stopped sigma-algebra associated with the stopping time $\eta_C$) implies that
    \begin{align*}
        \E^\pi_{s_0}[\eta_{\tilde{s}^\star}] = \E^\pi_{s_0} \E^\pi_{s_0}\left[\eta_{\tilde{s}^\star} \mid \mathcal{F}_{\eta_C}\right] = \E^\pi_{s_0} \left[\E^\pi_{S_{\eta_C}}\left[\eta_{\tilde{s}^\star} \right] + \eta_{C} \right] \leq \E^\pi_{s_0} \left[M + \eta_{C} \right] < \infty.
    \end{align*}
    Since there are only a finite number of such transient states $s_0$, the maximum of $\E^\pi_{s_0}[\eta_{\tilde{s}^\star}]$ over all such states is finite. Hence $\Dow(P, \pi) \leq \max_{s_0 \in \S} \E_{s_0}^\pi[\eta_{\tilde{s}^\star}] < \infty$.
\end{proof}


Define $d^\pi_{\gamma,s_0} \in \R^\S$ as
\begin{align*}
    d^\pi_{\gamma,s_0}(s) = \sum_{t=0}^\infty \gamma^t e_{s_0}^\top P_\pi^t e_s.
\end{align*}
We often drop the dependence on $\gamma, \pi$ and simply write $d_{s_0}$. We also define $d^\star(s) = \frac{1}{1-\gamma}\mu^\star(s)$.

\begin{lem}
\label{lem:occupancy_l1_diff_coupling_bound}
    Let $s^\star \in \S$ satisfy $\Dow(P, \pi) = \Dow(P, \pi, s^\star)$. Then
    \begin{align*}
        \sup_{s_0} \sum_{s \in \S} \left| d_{s_0}(s) - d_{s^\star}(s)\right| \leq 2 \Dow(P, \pi)
    \end{align*}
    and
    \begin{align*}
        \sup_{s_0, s_1} \sum_{s \in \S} \left| d_{s_0}(s) - d_{s_1}(s)\right| \leq 4 \Dow(P, \pi).
    \end{align*}
\end{lem}
\begin{proof}
We use a coupling argument, and these calculations are somewhat inspired by those in \cite[Lemma B.13]{cheikhi_statistical_2023}.
    Starting with the first statement, fix some $s_0 \in \S$. Let $S^\star_0, S^\star_1, \dots,$ be the stochastic process with distribution given by the Markov chain $P_\pi$ with starting state $s^\star$, and let $S_0, S_1, \dots,$ be the stochastic process with distribution given by the Markov chain $P_\pi$ but with starting state $s_0$. Let $\eta_{s^\star} = \inf \{t : S_t = s^\star\}$ be the first hitting time of the state $s^\star$ by the process $(S_t)_{t=0}^\infty$. Now define the process $S'_0, S'_1, \dots$ identically to $(S_t)_{t=0}^\infty$ but to follow $(S^\star_t)_{t=0}^\infty$ once it reaches $s^\star$, that is $S'_{\eta_{s^\star}} = S^\star_0, S'_{\eta_{s^\star}+1} = S^\star_1,$ and so on. 
    It is a standard fact due to the Markov property that $(S'_t)_{t=0}^\infty$ has the same distribution as $(S_t)_{t=0}^\infty$. Now add an absorbing terminal state $\term$ (which we do not consider as an element of $\S$) and for all $t \geq 1$ let $Z_t \sim \text{Bernoulli}(\gamma)$ (independently), and define the processes $(\St'_{t})_{t=0}^\infty$ and $(\St^\star_{t})_{t=0}^\infty$ by $\St'_{0} = S'_0$, $\St^\star_0 = S^\star_0$, and for all $t \geq 0$,
    \begin{align*}
        \St^\star_{t+1} &= \begin{cases}
            \term & \text{$\exists k \in \{1, \dots, t+1\}$ such that $Z_k = 1$} \\
            S^\star_{t+1} & \text{otherwise} 
    \end{cases},\\
    \St'_{t+1} &= \begin{cases}
            \term & \text{$\exists k \in \{1, \dots, t+1\}$ such that $Z_k = 1$} \\
            S'_{t+1} & \text{otherwise} 
    \end{cases}.
    \end{align*}
    Intuitively speaking, $(\St'_{t})_{t=0}^\infty$ and $(\St^\star_{t})_{t=0}^\infty$ will reach the absorbing state $\term$ at the same time, and the probability of reaching it on any given timestep is $\gamma$ if it has not yet been reached. It is a standard fact that $d^\pi_{\gamma,s_0}(s) = \E \sum_{t=0}^\infty \ind(\St'_t = s)$ and that $d^\pi_{\gamma,s^\star}(s) = \E \sum_{t=0}^\infty \ind(\St^\star_t = s)$. 
    Hence using the above coupling we can bound $d^\pi_{\gamma,s_0}(s) - d^\pi_{\gamma,s^\star}(s)$. Specifically we have
    \begin{align}
        \sum_{s \in \S} \left|d^\pi_{\gamma,s_0}(s) - d^\pi_{\gamma,s^\star}(s) \right| &= \sum_{s \in \S} \left|\E \sum_{t=0}^\infty\left( \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right)\right| \nonumber\\
        & \leq \sum_{s \in \S} \E\left| \sum_{t=0}^\infty\left( \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right)\right| \nonumber\\
        &= \E \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{\term}-1} \left( \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right)\right| \label{eq:dow_coupling_1}
    \end{align}
    where in the final equality we let $\eta_{\term} = \inf \{t \geq 1 : Z_t = 1\}$ be the first hitting time of the terminal state.
    Now we consider two cases. On the event that $\eta_{\term} \leq \eta_{s^\star}$, we have
    \begin{align*}
         \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{\term}-1} \left( \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right)\right| & \leq \sum_{s \in \S} \sum_{t=0}^{\eta_{\term}-1}\left|  \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right| \\
        &=    \sum_{t=0}^{\eta_{\term}-1} 2 \ind(\St'_t \neq \St^\star_t) \\
        &= 2 \eta_{\term} \leq 2 \eta_{s^\star}.
    \end{align*}
    On the event that $\eta_{s^\star} < \eta_{\term}$, we have
    \begin{align*}
         &\sum_{s \in \S} \left| \sum_{t=0}^{\eta_{\term}-1} \left( \ind(\St'_t = s)  - \ind(\St^\star_t = s) \right)\right| \\
         &= \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{\term}-1} \left( \ind(S'_t = s)  - \ind(S^\star_t = s) \right)\right| \\
         &= \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{s^\star}-1}  \ind(S'_t = s) + \sum_{t=\eta_{s^\star}}^{\eta_{\term}-1}  \ind(S'_t = s)  - \sum_{t=0}^{\eta_{\term} - \eta_{s^\star}-1}\ind(S^\star_t = s) - \sum_{t=\eta_{\term} - \eta_{s^\star}}^{\eta_{\term}  -1}\ind(S^\star_t = s) \right| \\
         &= \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{s^\star}-1}  \ind(S'_t = s)  - \sum_{t=\eta_{\term} - \eta_{s^\star}}^{\eta_{\term} - 1}\ind(S^\star_t = s) \right| \\
         &= \sum_{s \in \S} \left| \sum_{t=0}^{\eta_{s^\star}-1} \left(  \ind(S'_t = s)  - \ind(S^\star_{t + \eta_{\term} - \eta_{s^\star}} = s) \right) \right| \\
         & \leq \sum_{s \in \S}  \sum_{t=0}^{\eta_{s^\star}-1} \left|  \ind(S'_t = s)  - \ind(S^\star_{t + \eta_{\term} - \eta_{s^\star}} = s) \right| \\
         & = 2 \sum_{t=0}^{\eta_{s^\star}-1} \ind(S'_t \neq S^\star_{t + \eta_{\term} - \eta_{s^\star}}) \leq 2 \eta_{s^\star}
    \end{align*}
    using the fact that $S'_{\eta_{s^\star}} = S^\star_0, S'_{\eta_{s^\star}+1} = S^\star_1, \dots$ to cancel terms.
    Combining the bounds for the two cases with~\eqref{eq:dow_coupling_1}, we have that
    \begin{align*}
        \sum_{s \in \S} \left|d^\pi_{\gamma,s_0}(s) - d^\pi_{\gamma,s^\star}(s) \right| 
        &\leq  \E 2 \eta_{s^\star} \leq 2 \Dow(P, \pi)
    \end{align*}
    as desired. 

    The second statement of the lemma follows immediately from the first, since by triangle inequality
    \begin{align*}
        \sup_{s_0, s_1} \sum_{s \in \S} \left| d_{s_0}(s) - d_{s_1}(s)\right| = \sup_{s_0, s_1} \onenorm{d_{s_0} - d_{s_1}} \leq \sup_{s_0, s_1} \onenorm{d_{s_0} - d_{s^\star}} + \onenorm{d_{s^\star} - d_{s_1}} \leq 4 \Dow(P, \pi).
    \end{align*}
\end{proof}

\begin{lem}
\label{lem:occupancy_l1_diff_coupling_bound_stationary}
    Let $\pi$ be a policy such that $P_\pi$ is unichain, and let $\mu^\pi \in \R^\S$ denote its stationary distribution. Then
    \begin{align*}
            \sum_{s \in \S} \left|d^\pi_{\gamma, s_0}(s) - \frac{1}{1-\gamma}\mu^\pi(s)\right| \leq 4\Dow(P, \pi).
    \end{align*}
\end{lem}
\begin{proof}
    Since $\mu^\pi$ is a stationary distribution, we have for any $s \in \S$ that
    \begin{align*}
        \sum_{s' \in \S} \mu^\pi(s') d^\pi_{\gamma, s'}(s) = (\mu^\pi)^\top (I - \gamma P_\pi)^{-1} e_s = (\mu^\pi)^\top \sum_{t=0}^\infty \gamma^t P_\pi^t e_s = \sum_{t=0}^\infty \gamma^t (\mu^\pi)^\top e_s = \frac{1}{1-\gamma}\mu^\pi(s)
    \end{align*}
    (since $(\mu^\pi)^\top P_\pi = (\mu^\pi)^\top$). Then we can calculate by Jensen's inequality that for any fixed $s \in \S$,
    \begin{align*}
        \left| d^\pi_{\gamma, s_0}(s) - \frac{1}{1-\gamma}\mu^\pi(s) \right| &= \left| d^\pi_{\gamma, s_0}(s) - \sum_{s' \in \S} \mu^\pi(s') d^\pi_{\gamma, s'}(s) \right| \\
        &= \left| \sum_{s' \in \S} \mu^\pi(s') \left( d^\pi_{\gamma, s_0}(s) - d^\pi_{\gamma, s'}(s) \right) \right| \\
        & \leq \sum_{s' \in \S} \mu^\pi(s') \left|  d^\pi_{\gamma, s_0}(s) - d^\pi_{\gamma, s'}(s)  \right| .
    \end{align*}
    Therefore
    \begin{align*}
        \sum_{s \in \S} \left|d^\pi_{\gamma, s_0}(s) - \frac{1}{1-\gamma}\mu^\pi(s)\right| &\leq \sum_{s \in \S}\sum_{s' \in \S} \mu^\pi(s') \left|  d^\pi_{\gamma, s_0}(s) - d^\pi_{\gamma, s'}(s)  \right| = \sum_{s' \in \S} \mu^\pi(s') \sum_{s \in \S} \left|  d^\pi_{\gamma, s_0}(s) - d^\pi_{\gamma, s'}(s)  \right| \\
        & \leq \sum_{s' \in \S} \mu^\pi(s') 4 \Dow(P, \pi) = 4 \Dow(P, \pi)
    \end{align*}
    where in the second inequality step we used Lemma \ref{lem:occupancy_l1_diff_coupling_bound}.
\end{proof}

\begin{lem}
\label{lem:dow_span_bound}
    For any policy $\pi$, $\spannorm{h^\pi} \leq 4\Dow(P, \pi)$.
\end{lem}
\begin{proof}
    Note that by Lemma \ref{lem:Dow_finite_unichain}, if $P_\pi$ is not unichain then $\Dow(P, \pi) = \infty$ and so the desired bound holds trivially (note $\spannorm{h^\pi}$ is always finite). So we can now focus on the case that $P_\pi$ is unichain. This implies $\rho^\pi$ is a state-independent constant. In this case it is a standard fact (e.g. \cite[Corollary 8.2.4]{puterman_markov_1994}) that for any $s,s' \in \S$,
    \begin{align*}
        h^\pi(s) - h^\pi(s') = \lim_{\gamma \to 1^-} V_\gamma^\pi(s) - V_\gamma^\pi(s').
    \end{align*}
    Therefore
    \begin{align*}
        \spannorm{h^\pi} &= \max_{s,s'\in \S}h^\pi(s) - h^\pi(s') \\
        &= \max_{s,s'\in \S} \lim_{\gamma \to 1^-} V_\gamma^\pi(s) - V_\gamma^\pi(s') \\
        &= \max_{s,s'\in \S} \lim_{\gamma \to 1^-} e_s^\top (I - \gamma P_\pi)^{-1} r_\pi - e_{s'}^\top (I - \gamma P_\pi)^{-1} r_\pi \\
        &= \max_{s,s'\in \S} \lim_{\gamma \to 1^-} (d^\pi_{\gamma, s} - d^\pi_{\gamma, s'}) r_\pi \\
        &\leq \max_{s,s'\in \S} \lim_{\gamma \to 1^-} \onenorm{d^\pi_{\gamma, s} - d^\pi_{\gamma, s'}} \infnorm{r_\pi} \\
        &\leq \max_{s,s'\in \S} \lim_{\gamma \to 1^-} 4 \Dow(P, \pi) \\
        &= 4 \Dow(P, \pi)
    \end{align*}
    where the inequality steps are by Holder's inequality and Lemma \ref{lem:occupancy_l1_diff_coupling_bound}.
\end{proof}

\subsubsection{Relationship between policy hitting radius and uniform mixing time}
\label{sec:tmix_dow_reln}
Here we argue that there is generally no relationship between the policy hitting radius and the mixing time. First, if $P_\pi$ is a unichain and periodic Markov chain, then the mixing time will be infinite/undefined whereas $\Dow(P, \pi) < \infty$ by Lemma \ref{lem:Dow_finite_unichain}.

Now we show an example where the mixing time can be arbitrarily smaller than the policy hitting radius. Suppose that $P$, $\pi$ are defined so that $P_\pi$ is the random walk on the complete graph on $L$ nodes, where $L$ is any positive integer. Then $\mu^\pi(s) = 1/L$ for all $s \in \S$, and after just one step from any starting state we have that $S_1$ has distribution $\mu^\pi$ so $\tmixsingle(\pi)=1$. However, for any fixed starting state $s_0$ and any state $s \neq s_0$, we have that $\eta_{s} \sim \text{Geom}(1/L)$, so $\E^\pi_{s_0} \eta_s = L$, and hence $\Dow(P, \pi) = L$. 


\subsection{Error analysis}

Now we can continue with analyzing the relationship between $\Qhpe^\star$ and $\rho^{\pistar}$, for a comparator policy $\pistar$. Having established pessimism (Lemma \ref{lem:pessimism}), which implies an upper bound on $\Qhpe^\star$, we now seek to lower-bound this quantity.
Since (by Lemma \ref{lem:pessimistic_Bellman_operator_properties}) $ \Qhpe^\star \geq \Qhpe^{\pistar}$, it suffices to lower-bound $\Qhpe^{\pistar}$ in terms of $V^{\pistar}$, which is then related to $\rho^{\pistar}$. 

\begin{lem}
\label{lem:truncated_variance_bound}
For any probability distribution $\mu \in \Delta^{\S}$, any $V \in \R^\S$, and any $\beta \in [0,1]$, we have that
    \begin{align*}
        \Var_{\mu} \left[ T_{\beta}(\mu, V) \right] \leq \Var_{\mu} \left[ V \right].
    \end{align*}
\end{lem}
\begin{proof}
    We prove this by showing the more general statement that for any random variable $X$ and any scalar $a$,
    \[
    \Var \left[ \min(X,a)\right] \leq \Var \left[ X\right].
    \]
    Let $T = \min(X,a)$ and $\Delta = X - T$. Then
    \begin{align*}
        \Var \left[ X\right] &= \Var \left[ T\right] + \Var \left[ \Delta\right] + 2 \text{Cov}(T, \Delta).
    \end{align*}
    Thus to show $ \Var \left[ X\right] \geq \Var \left[ T\right]$ it suffices to show that $\text{Cov}(T, \Delta) \geq 0$. Now we compute
    \begin{align*}
        \text{Cov}(T, \Delta) &= \E \left[ \Delta (T - \E T)\right] \\
        &= \E \left[ \Delta (T - \E T)\ind\{X \geq a\}\right]+ \E \left[ \Delta (T - \E T)\ind\{X < a\}\right].
    \end{align*}
    On the event $\{X < a\}$ we have $\Delta = 0$, so $\E \left[ \Delta (T - \E T)\ind\{X < a\}\right] = 0$. On the event $\{X \geq a\}$, $(T - \E T) \geq 0$ since $T=a$ and $\E T \leq a$, and $\Delta \geq 0$, so $\E \left[ \Delta (T - \E T)\ind\{X \geq a\}\right] \geq 0$. Therefore $\text{Cov}(T, \Delta) \geq 0$ as desired.
\end{proof}

\begin{lem}
    \label{lem:Qhpe_pistar_almost_sim_lemma}
    Fix any deterministic policy $\pistar$.
    Under the event in Lemma \ref{lem:concentration_for_pessimism_Thpe_pistar},
    \begin{align*}
        V^{\pistar} - \Vhpe^{\pistar} \leq (I - \gamma P_{\pistar})^{-1} \gamma \bt_{\pistar}
    \end{align*}
    where
    \begin{align*}
        \bt_{\pistar}(s) = 2\sqrt{\beta(s,\pistar(s))  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}} + \frac{12}{\ntot} .
    \end{align*}
    We also have that
    \begin{align}
        \Vhpe^{\pistar} - \gamma P_{\pistar} \Vhpe^{\pistar} + \gamma \bt_{\pistar} \geq r_{\pistar}. \label{eq:Vhpe_pistar_lb_sim_lem}
    \end{align}
\end{lem}
\begin{proof}
    Fix $s \in \S, a \in \A$. First we handle the case that $\beta(s,a) \leq 1$. This implies that $n(s,a) \geq 1 + \alpha = 1 + 8 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$.
    By the definition~\eqref{eq:defn_of_Thpe_pi} of $\Thpe^{\pistar}$ we have that
    \begin{align}
        \Qhpe^{\pistar}(s,a) \geq r(s,a) + \gamma \Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) - \gamma b(s,a,\Vhpe^{\pistar}). \label{eq:Qhpe_pistar_lb_1}
    \end{align}
    By the definition of $T_{\beta(s,a)} (\Phat_{sa}, \Vhpe^{\pistar})$ we have that (elementwise)
    \begin{align}
        \Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) &= \sum_{s'} \Phat_{sa}(s') T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})(s') \nonumber\\
        &= \sum_{s':\Vhpe^{\pistar}(s') \leq Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})(s') \nonumber\\
        & \qquad \qquad+ \sum_{s':\Vhpe^{\pistar}(s') > Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})(s') \nonumber\\
        &= \sum_{s':\Vhpe^{\pistar}(s') \leq Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') \Vhpe^{\pistar}(s') \nonumber\\
        & \qquad \qquad+ \sum_{s':\Vhpe^{\pistar}(s') > Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) \nonumber\\
        &\geq \sum_{s':\Vhpe^{\pistar}(s') \leq Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') \Vhpe^{\pistar}(s') \nonumber\\
        & \qquad \qquad+ \sum_{s':\Vhpe^{\pistar}(s') > Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') \left(\Vhpe^{\pistar}(s') - \spannorm{\Vhpe^{\pistar}} \right) \nonumber\\
        & > \Phat_{sa} \Vhpe^{\pistar} - \beta(s,a) \spannorm{\Vhpe^{\pistar}} \label{eq:Vhpe_pistar_inner_prod_lb}
    \end{align}
    where in the final inequality we used that $\sum_{s':\Vhpe^{\pistar}(s') > Q_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar})} \Phat_{sa}(s') < \beta(s,a)$. Using~\eqref{eq:concentration_for_pessimism_Thpe_pistar_bernstein} from Lemma \ref{lem:concentration_for_pessimism_Thpe_pistar} to relate $\Phat_{sa} \Vhpe^{\pistar}$ to $P_{sa} \Vhpe^{\pistar}$, we can further bound
    \begin{align}
        \Phat_{sa} T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) & \geq P_{sa} \Vhpe^{\pistar} - \left|(\Phat_{sa} - P_{sa}) \Vhpe^{\pistar} \right| - \beta(s,a) \spannorm{\Vhpe^{\pistar}} \nonumber \\
        & \geq P_{sa} \Vhpe^{\pistar} - \sqrt{\frac{2 \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right] \log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{n(s,a)}}-\spannorm{\Vhpe^{\pistar}}\frac{\log \left(\frac{6S^2A\ntot}{(1-\gamma)\delta} \right)}{ 3n(s,a)} \nonumber \\
        &\qquad - \frac{3}{\ntot} - \beta(s,a) \spannorm{\Vhpe^{\pistar}} \nonumber \\
        & \geq P_{sa} \Vhpe^{\pistar} - \sqrt{ \beta(s,a) \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right]} - 2 \beta(s,a) \spannorm{\Vhpe^{\pistar}} - \frac{3}{\ntot}.
        \label{eq:Vhpe_pistar_inner_prod_lb_2}
    \end{align}    

    To finish lower-bounding~\eqref{eq:Qhpe_pistar_lb_1} we must also lower-bound $b(s,a,\Vhpe^{\pistar})$.
    It is immediate to see that $\spannorm{T_{\beta(s,a)} (\Phat_{sa}, \Vhpe^{\pistar})} \leq \spannorm{\Vhpe^{\pistar}}$, and also by Lemma \ref{lem:truncated_variance_bound} (since we are in the $\beta(s,a) \leq 1$ case) we have that $\Var_{\Phat_{sa}} \left[T_{\beta(s,a)}(\Phat_{sa}, \Vhpe^{\pistar}) \right] \leq \Var_{\Phat_{sa}} \left[\Vhpe^{\pistar}\right]$. These two facts yield that
    \begin{align}
        b(s,a,\Vhpe^{\pistar}) &= \max \left \{ \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[ T_{\beta(s,a)}( \Phat_{sa}, \Vhpe^{\pistar}) \right]} ,  \beta(s,a) \spannorm{T_{\beta(s,a)}( \Phat_{sa}, \Vhpe^{\pistar})} \right \} + \frac{5}{\ntot} \nonumber \\
        & \leq \max \left \{ \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[ \Vhpe^{\pistar} \right]} ,  \beta(s,a) \spannorm{\Vhpe^{\pistar}} \right \} + \frac{5}{\ntot} \nonumber \\
        & \leq  \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[ \Vhpe^{\pistar} \right]} + \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{5}{\ntot}. \label{eq:Vhpe_pistar_b_bd_1}
    \end{align}
    Furthermore, using the bound~\eqref{eq:concentration_for_pessimism_Thpe_pistar_variance} from Lemma \ref{lem:concentration_for_pessimism_Thpe_pistar}, we can further bound~\eqref{eq:Vhpe_pistar_b_bd_1} as
    \begin{align}
        &b(s,a,\Vhpe^{\pistar}) \nonumber\\
        & \leq  \sqrt{\beta(s,a)  \Var_{\Phat_{sa}} \left[ \Vhpe^{\pistar} \right]} + \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{5}{\ntot} \nonumber\\
        & \leq \sqrt{\beta(s,a)} \left( \sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\frac{2 \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{n(s,a)}} + \frac{4}{\ntot} \right) + \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{5}{\ntot} \nonumber \\
        & \leq  \sqrt{\beta(s,a)} \left( \sqrt{\Var_{P_{sa}} \left[\Vhpe^{\pistar}\right]} + \spannorm{\Vhpe^{\pistar}} \sqrt{\beta(s,a)} + \frac{4}{\ntot} \right) + \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{5}{\ntot} \nonumber \\
        & \leq \sqrt{\beta(s,a)  \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right]} + 2 \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{9}{\ntot} \label{eq:Vhpe_pistar_b_bd_2}
    \end{align}
    (using the definition of $\beta(s,a)$ and the fact that we are in the $\beta(s,a) \leq 1$ case).

    Combining~\eqref{eq:Vhpe_pistar_b_bd_2} and~\eqref{eq:Vhpe_pistar_inner_prod_lb_2} with~\eqref{eq:Qhpe_pistar_lb_1} we obtain that
    \begin{align*}
        \Qhpe^{\pistar}(s,a) &\geq r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - 2 \gamma \sqrt{ \beta(s,a) \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right]} - 4 \gamma \beta(s,a) \spannorm{\Vhpe^{\pistar}} - \frac{12 \gamma}{\ntot}  \\
        &= r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - \gamma \bt(s,a)
    \end{align*}
    where we define $\bt(s,a) = \sqrt{ \beta(s,a) \Var_{P_{sa}} \left[ \Vhpe^{\pistar} \right]} + 4  \beta(s,a) \spannorm{\Vhpe^{\pistar}} + \frac{12 }{\ntot} $.

    Now for the simpler case that $\beta(s,a) > 1$, we have that
    \begin{align*}
        \Qhpe^{\pistar}(s,a) &= r(s,a) + \gamma \min_{s'} \Vhpe^{\pistar}(s') \\
        &\geq  r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - \gamma \spannorm{\Vhpe^{\pistar}} \\
        &\geq  r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - \gamma \beta(s,a) \spannorm{\Vhpe^{\pistar}} \\
        & \geq  r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - \gamma \bt(s,a).
    \end{align*}

    Combining the two cases of $\beta(s,a)$, we have for all $s, a$ that $\Qhpe^{\pistar}(s,a)\geq  r(s,a) + \gamma P_{sa} \Vhpe^{\pistar} - \gamma \bt(s,a)$.
    Therefore by monotonicity of $M^{\pistar}$,
    \begin{align*}
        \Vhpe^{\pistar} = M^{\pistar} \Qhpe^{\pistar} \geq M^{\pistar} \left(r + \gamma P \Vhpe^{\pistar} - \gamma \bt \right) = r_{\pistar} + \gamma P_{\pistar} \Vhpe^{\pistar} - \gamma \bt_{\pistar}.
    \end{align*}
    We also have
    $\Vhpe^{\pistar} - \gamma P_{\pistar} \Vhpe^{\pistar} + \gamma \bt_{\pistar} \geq r_{\pistar}$, which will be needed later.
    By the Bellman equation for $\pistar$ we also have that $V^{\pistar} = r_{\pistar} + \gamma P_{\pistar} V^{\pistar}$. Combining these, rearranging, and using the monotonicity of multiplication by $(I-\gamma P_{\pistar})^{-1}$ (since all its entries are nonnegative), we obtain
    \begin{align*}
        & V^{\pistar} - \Vhpe^{\pistar}  \leq r_{\pistar} + \gamma P_{\pistar} V^{\pistar} - r_{\pistar} + \gamma \bt_{\pistar} - \gamma P_{\pistar} \Vhpe^{\pistar} = \gamma \bt_{\pistar} + \gamma P_{\pistar} (V^{\pistar} - \Vhpe^{\pistar}) \\
        \implies & (I-\gamma P_{\pistar}) (V^{\pistar} - \Vhpe^{\pistar}) \leq \gamma \bt_{\pistar} \\
        \implies & V^{\pistar} - \Vhpe^{\pistar}  \leq (I-\gamma P_{\pistar})^{-1} \gamma \bt_{\pistar}
    \end{align*}
    as desired.
\end{proof}

\begin{lem}
\label{lem:error_analysis_empirical_span}
    Fix a deterministic unichain policy $\pistar$.
    Suppose that for all $s \in \S$, $n(s, \pistar(s)) \geq m \mu^{\pistar}(s) + 4 + 4 \Dow(P, \pistar)$, $\frac{1}{1-\gamma} \geq m$, and $\frac{1}{1-\gamma} \geq 2$. Then under the event in Lemma \ref{lem:concentration_for_pessimism_Thpe_pistar}, we have that
    %\begin{align*}
    %    \infnorm{V^{\pistar} - \Vhpe^{\pistar}} \leq \frac{1}{1-\gamma}\sqrt{\frac{2048 S \spannorm{\Vhpe^{\pistar}} \log \left( \frac{6S^2An}{(1-\gamma)\delta}\right)}{m}} +  \frac{640 S \spannorm{\Vhpe^{\pistar}}  \log \left( \frac{6S^2An}{(1-\gamma)\delta}\right)}{(1-\gamma)m} + \frac{12}{(1-\gamma)n}.
    %\end{align*}
    \begin{align*}
        &\max_{s_0 \in \S} \left( V^{\pistar}(s_0) - \Vhpe^{\pistar}(s_0) \right) \\
        &\leq  \frac{1}{1-\gamma}\sqrt{\frac{2048 S \spannorm{\Vhpe^{\pistar}} \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}} +  \frac{640 S \spannorm{\Vhpe^{\pistar}}  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{(1-\gamma)m} + \frac{12}{(1-\gamma)\ntot}.
    \end{align*}
\end{lem}
\begin{proof}
    First we note that, using Lemma \ref{lem:Qhpe_pistar_almost_sim_lemma}, we have
    \begin{align*}
        \max_{s_0 \in \S} \left( V^{\pistar}(s_0) - \Vhpe^{\pistar}(s_0) \right) \leq \max_{s_0 \in \S} e_{s_0}^\top (I - \gamma P_{\pistar})^{-1} \gamma \bt_{\pistar} = \max_{s_0 \in \S} \left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle.
    \end{align*}
    We will now fix some arbitrary $s_0 \in \S$ and try to bound $\left \langle d^{\pistar}_{\gamma,s_0}, \bt_{\pistar}\right\rangle$.
    By the assumptions in the lemma statement we have that for all $s \in \S$,
    \begin{align*}
        n(s, \pistar(s)) &\geq m \mu^{\pistar}(s) + 4 \Dow(P, \pistar) = (1-\gamma)m \frac{1}{1-\gamma}\mu^{\pistar}(s) + 4 \Dow(P, \pistar) \\
        & \geq (1-\gamma)m d^{\pistar}_{\gamma,s_0}(s) - (1-\gamma)m \left| d^{\pistar}_{\gamma,s_0}(s) - \frac{1}{1-\gamma}\mu^{\pistar}(s)\right| + 4 \Dow(P, \pistar) \\
        & \geq (1-\gamma)m d^{\pistar}_{\gamma,s_0}(s) - (1-\gamma)m 4 \Dow(P, \pistar) + 4 \Dow(P, \pistar) \\
        & \geq (1-\gamma)m d^{\pistar}_{\gamma,s_0}(s)
    \end{align*}
    where the third inequality is a consequence of Lemma \ref{lem:occupancy_l1_diff_coupling_bound_stationary}. For convenience we will let $C := (1-\gamma)m$, and so we have shown that $n(s, \pistar(s)) \geq C d^{\pistar}_{\gamma,s_0}(s)$ for all $s \in \S$. Also for convenience abbreviate $\ell = \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$. Using the fact that $n(s, \pistar(s)) \geq 4$ which implies $\frac{1}{n(s, \pistar(s))-1} \leq \frac{4/3}{n(s, \pistar(s))}\leq \frac{2}{n(s, \pistar(s))}$, we can simplify $\bt_{\pistar}$ as
    \begin{align*}
        \bt_{\pistar}(s) &= 2\sqrt{\beta(s,\pistar(s))  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}} + \frac{12}{n} \\
        &= 2\sqrt{\frac{8 \ell}{n(s, \pistar(s))-1}  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\frac{8 \ell}{n(s, \pistar(s))-1} \spannorm{\Vhpe^{\pistar}} + \frac{12}{\ntot} \\
        & \leq 2\sqrt{\frac{16 \ell}{n(s, \pistar(s))}  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\frac{16 \ell}{n(s, \pistar(s))} \spannorm{\Vhpe^{\pistar}} + \frac{12}{\ntot}.
    \end{align*}
    Using this and the fact that $n(s, \pistar(s)) \geq C d^{\pistar}_{\gamma,s_0}(s)$ for all $s \in \S$, we have
    \begin{align}
        \left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle &\leq \sum_{s \in \S} d^{\pistar}_{\gamma,s_0}(s) \left( 2\sqrt{\frac{16 \ell}{n(s, \pistar(s))}  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\frac{16 \ell}{n(s, \pistar(s))} \spannorm{\Vhpe^{\pistar}} + \frac{12}{\ntot} \right)\nonumber\\
        & \leq \sum_{s \in \S} d^{\pistar}_{\gamma,s_0}(s) \left( 2\sqrt{\frac{16 \ell}{C d^{\pistar}_{\gamma,s_0}(s)}  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} + 4\frac{16 \ell}{C d^{\pistar}_{\gamma,s_0}(s)} \spannorm{\Vhpe^{\pistar}} + \frac{12}{\ntot} \right) \nonumber \\
        &= \sum_{s \in \S} 2\sqrt{d^{\pistar}_{\gamma,s_0}(s)  \frac{16 \ell}{C}  \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} +  S4\frac{16 \ell}{C} \spannorm{\Vhpe^{\pistar}} + \sum_{s \in \S} d^{\pistar}_{\gamma,s_0}(s) \frac{12}{\ntot} \nonumber\\
        & \leq   \sqrt{\frac{64 S \ell}{C}} \sqrt{ \sum_{s \in \S}d^{\pistar}_{\gamma,s_0}(s) \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} +  \frac{64 S \ell}{C} \spannorm{\Vhpe^{\pistar}} +  \frac{12}{(1-\gamma) \ntot} \label{eq:error_analysis_empirical_span_1}
    \end{align}
    where in the final inequality we used Cauchy-Schwarz to bound the first term.

    Now we focus on bounding the quantity $\sum_{s \in \S}d^{\pistar}_{\gamma,s_0}(s) \Var_{P_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]$.
    Let $c = \min_{s \in \S} \Vhpe^{\pistar}(s)$ and $\Vc = \Vhpe^{\pistar} - c\one$. Then
    \begin{align}
        \Vc \circ \Vc - \gamma^2 P_{\pistar} \Vc \circ P_{\pistar} \Vc &= (\Vc - \gamma P_{\pistar} \Vc) \circ (\Vc + \gamma P_{\pistar} \Vc) \nonumber \\
        & \leq (\Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one) \circ (\Vc + \gamma P_{\pistar} \Vc) \nonumber\\
        & \leq 2 \infnorm{\Vc} (\Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one) \label{eq:error_analysis_empirical_span_var_term_bd}
    \end{align}
    where for the first inequality we used that $\Vc + \gamma P_{\pistar} \Vc \geq \zero$ and that $\bt_{\pistar} + (1-\gamma)c \one \geq \zero$, and for the second inequality we used that $\Vc + \gamma P_{\pistar} \Vc \leq 2 \infnorm{\Vc} \one$ and that $\Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one \geq \zero$, which follows from the fact that
    \begin{align*}
        \Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one = \Vhpe^{\pistar} - \gamma P_{\pistar} \Vhpe^{\pistar} + \gamma \bt_{\pistar} \geq r_{\pistar} \geq \zero
    \end{align*}
    using~\eqref{eq:Vhpe_pistar_lb_sim_lem} in the inequality step.
    Thus
    \begin{align}
        \left\langle d^{\pistar}_{\gamma,s_0}, \Var_{P_{\pistar}} \left[ \Vhpe^{\pistar} \right]  \right\rangle &= \left\langle d^{\pistar}_{\gamma,s_0}, \Var_{P_{\pistar}} \left[ \Vc \right]  \right\rangle \nonumber\\
        &= \left\langle d^{\pistar}_{\gamma,s_0}, P_{\pistar} (\Vc)^{\circ 2} - (P_{\pistar} \Vc)^{\circ 2}  \right\rangle \nonumber\\
        &= \left\langle d^{\pistar}_{\gamma,s_0}, P_{\pistar} (\Vc)^{\circ 2} - \frac{1}{\gamma^2} (\Vc)^{\circ 2} + \frac{1}{\gamma^2 } \left((\Vc)^{\circ 2}  - \gamma^2(P_{\pistar} \Vc)^{\circ 2}  \right)\right \rangle \nonumber\\
        & \stackrel{(i)}{\leq} \left\langle d^{\pistar}_{\gamma,s_0}, P_{\pistar} (\Vc)^{\circ 2} - \frac{1}{\gamma^2} (\Vc)^{\circ 2} + \frac{1}{\gamma^2 } 2 \infnorm{\Vc} (\Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one) \right \rangle \nonumber\\
        & \stackrel{(ii)}{\leq}\left\langle d^{\pistar}_{\gamma,s_0},  \frac{1}{\gamma^2 } 2 \infnorm{\Vc} (\Vc - \gamma P_{\pistar} \Vc + \gamma \bt_{\pistar} + (1-\gamma)c \one) \right \rangle \nonumber\\
        &= \frac{2 \infnorm{\Vc}}{\gamma^2} e_{s_0}^\top (I - \gamma P_{\pistar})^{-1} \left((I - \gamma P_{\pistar}) \Vc + \gamma \bt_{\pistar} + (1-\gamma )c\one \right) \nonumber \\
        &= \frac{2 \infnorm{\Vc}}{\gamma^2} e_{s_0}^\top (I - \gamma P_{\pistar})^{-1} \left((I - \gamma P_{\pistar}) \Vhpe^\star + \gamma \bt_{\pistar}  \right) \nonumber \\
        &= \frac{2 \infnorm{\Vc}}{\gamma^2}  e_{s_0}^\top \Vhpe^\star + \frac{4 \infnorm{\Vc}}{\gamma^2} \langle d^{\pistar}_{\gamma,s_0}, \gamma \bt_{\pistar} \rangle \nonumber\\
        &\leq \frac{2 \infnorm{\Vc}}{\gamma^2}\frac{1}{1-\gamma}   + \frac{4 \infnorm{\Vc}}{\gamma} \langle d^{\pistar}_{\gamma,s_0},  \bt_{\pistar} \rangle. \label{eq:error_analysis_empirical_span_2}
    \end{align}
    In $(i)$ we use~\eqref{eq:error_analysis_empirical_span_var_term_bd} and in $(ii)$ we use that
    \begin{align*}
        \left\langle d^{\pistar}_{\gamma,s_0}, P_{\pistar} (\Vc)^{\circ 2} - \frac{1}{\gamma^2} (\Vc)^{\circ 2} \right \rangle & \leq \left\langle d^{\pistar}_{\gamma,s_0}, P_{\pistar} (\Vc)^{\circ 2} - \frac{1}{\gamma} (\Vc)^{\circ 2} \right \rangle \\
        &=  \frac{1}{\gamma} e_{s_0}^\top(I - \gamma P_{\pistar})^{-1} (\gamma P_{\pistar} - I) (\Vc)^{\circ 2} \leq  0.
    \end{align*}

    Combining the bound~\eqref{eq:error_analysis_empirical_span_2} with~\eqref{eq:error_analysis_empirical_span_1} (and noting that $\infnorm{\Vc} = \spannorm{\Vhpe^{\pistar}}$), we obtain that
    \begin{align*}
        \left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle 
        & \leq   \sqrt{\frac{64 S \ell}{C}} \sqrt{ \frac{2 \spannorm{\Vhpe^{\pistar}}}{\gamma^2}\frac{1}{1-\gamma}   + \frac{4 \spannorm{\Vhpe^{\pistar}}}{\gamma} \left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle} \\
        & \qquad \qquad+  \frac{64 S \ell}{C} \spannorm{\Vhpe^{\pistar}} +  \frac{12}{(1-\gamma) \ntot} \\
        & \leq \sqrt{\frac{512 \spannorm{\Vhpe^{\pistar}} S \ell}{C}} \left(\sqrt{\frac{1}{1-\gamma}} + \sqrt{\left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle} \right) \\
        & \qquad \qquad+  \frac{64 S \ell}{C} \spannorm{\Vhpe^{\pistar}} +  \frac{12}{(1-\gamma) \ntot}
    \end{align*}
    where we simplified by using that $\sqrt{a + b} \leq \sqrt{a} + \sqrt{b}$ and that $\frac{1}{\gamma} \leq 2$ (since $\frac{1}{1-\gamma} \geq 2$ implies that $\gamma \geq \frac{1}{2}$). The above is a quadratic inequality in $x := \sqrt{\left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle}$ of the form
    \begin{align*}
        x^2 \leq x\sqrt{8y} + \sqrt{\frac{8y}{1-\gamma}} + y + \frac{12}{(1-\gamma)\ntot}
    \end{align*}
    where $y = \frac{64 S \spannorm{\Vhpe^{\pistar}} \ell}{C}$. From the quadratic formula we obtain that
    \begin{align*}
        x \leq \frac{\sqrt{8y} + \sqrt{8y + 4\left(\sqrt{\frac{8y}{1-\gamma}} + y + \frac{12}{(1-\gamma)\ntot} \right)}}{2}
    \end{align*}
    and then squaring both sides we obtain that
    \begin{align*}
         \left \langle d^{\pistar}_{\gamma,s_0} , \bt_{\pistar}\right\rangle = x^2 &\leq \frac{\left( \sqrt{8y} + \sqrt{8y + 4\left(\sqrt{\frac{8y}{1-\gamma}} + y + \frac{12}{(1-\gamma)\ntot} \right)} \right)^2}{4} \\
        &\leq \frac{1}{2}\left(8y + 8y + 4\left(\sqrt{\frac{8y}{1-\gamma}} + y + \frac{12}{(1-\gamma)\ntot} \right) \right) \\
        &= 10y + \sqrt{\frac{32 y}{1-\gamma}} + \frac{12}{(1-\gamma)\ntot} \\
        &= 10 \frac{64 S \spannorm{\Vhpe^{\pistar}}  \ell}{C} + \sqrt{32\frac{64 S \spannorm{\Vhpe^{\pistar}} \ell}{C(1-\gamma)}} + \frac{12}{(1-\gamma)\ntot}
    \end{align*}
    using that $(a + b)^2 \leq 2a^2 + 2b^2$. Recalling the definitions of $C = (1-\gamma)m$ and $\ell = \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, and also since the above bound held for arbitrary $s_0$, we have thus shown that
    \begin{align*}
        &\max_{s_0 \in \S} \left( V^{\pistar}(s_0) - \Vhpe^{\pistar}(s_0) \right) \\
        &\leq  \frac{1}{1-\gamma}\sqrt{\frac{2048 S \spannorm{\Vhpe^{\pistar}} \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}} +  \frac{640 S \spannorm{\Vhpe^{\pistar}}  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{(1-\gamma)m} + \frac{12}{(1-\gamma)\ntot}.
    \end{align*}
\end{proof}

\subsection{Controlling the empirical span}
While Lemma \ref{lem:error_analysis_empirical_span} is approaching the desired result, it involves the empirical span term $\spannorm{\Vhpe^{\pistar}}$ which we would like to bound in terms of $\spannorm{V^{\pistar}}$. Such a bound is the objective of this subsection, and makes crucial use of our assumption of data even for states which are transient under $P_{\pistar}$.


\begin{lem}
\label{lem:dow_stability}
    Fix a deterministic unichain policy $\pistar$.
    Suppose that $n(s, \pistar(s)) \geq 72(\Dow(P, \pistar))^2 \log \left(\frac{2S}{\delta} \right)$ for all $s \in \S$. Then with probability at least $1 - \delta$,
    \begin{align*}
        \Dow(\Phat, \pistar) \leq 24 \Dow(P, \pistar).
    \end{align*}
\end{lem}
\begin{proof}
    The proof of this lemma is inspired by that of \citet[Lemma 4]{zurek_plug-approach_2024}. For any MDP $\mathcal{M}$ and $s \in \S$ we let $E^\pi_{s_0, \mathcal{M}}$ denote the expectation with respect to the Markov chain induced by $\pi$ in the MDP $\mathcal{M}$ from starting state $s_0$, and similarly we let $\P^\pi_{s_0, \mathcal{M}}(E) = 
    \E^\pi_{s_0, \mathcal{M}} [\ind(E)]$ denote the associated probability measure. Let $s^\star \in \S$ satisfy $\Dow(P, \pistar) = \Dow(P, \pi, s^\star)$. 
    Let $\Mhat$ be the MDP $(\Phat, r)$. Then
    \begin{align}
        \Dow(\Phat, \pistar) \leq \Dow(\Phat, \pistar, s^\star) = \max_{s_0 \in \S} \E_{s_0, \Mhat}^\pi [\eta_{s^\star}]. \label{eq:dow_stability_1}
    \end{align}
    Supposing that $k \in \N$ satisfies $\max_{s_0 \in \S} \P_{s_0, \Mhat} (\eta_{s^\star} \geq k) \leq \frac{1}{2}$, then we have for any $s_0'$ that
    \begin{align}
        \E_{s_0', \Mhat}^\pi [\eta_{s^\star}] &= \sum_{t=0}^\infty  \P_{s_0', \Mhat}(\eta_{s^\star} >  t) \nonumber \\
        &= \sum_{i=0}^\infty \sum_{t=0}^{k-1}  \P_{s_0', \Mhat}(\eta_{s^\star} > ik +t) \nonumber \\
        &\leq \sum_{i=0}^\infty \sum_{t=0}^{k-1}  \P_{s_0', \Mhat}(\eta_{s^\star} > ik) \nonumber \\
        &= k \sum_{i=0}^\infty  \P_{s_0', \Mhat}(\eta_{s^\star} > ik) \nonumber \\
        & \leq k \sum_{i=0}^\infty  2^{-i} = 2k \label{eq:dow_stability_2}
    \end{align}
    where the final inequality step used that
    \begin{align*}
        \P_{s_0', \Mhat}(\eta_{s^\star} > ik) \leq \left(\max_{s_0 \in \S} \P_{s_0, \Mhat} (\eta_{s^\star} > k) \right)^i \leq 2^{-i}
    \end{align*}
    which follows from the following standard arguments: for any integer $i \geq 1$ (since this formula obviously holds for $i = 0$), we have
    \begin{align*}
         &\P_{s_0', \Mhat}(\eta_{s^\star} > ik) \\
         & \leq \P_{s_0', \Mhat}(\eta_{s^\star} \geq ik)\\
         &= \P_{s_0', \Mhat} \left(\text{$\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$ and $\eta_{s^\star} \not \in \{(i-1)k, \dots, ik - 1\}$} \right) \\
         &\stackrel{(i)}{=} \E_{s_0', \Mhat} \P_{s_0', \Mhat} \left(\text{$\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$ and $\eta_{s^\star} \not \in \{(i-1)k, \dots, ik - 1\}$} \mid \mathcal{F}_{(i-1)k}\right) \\
         &\stackrel{(ii)}{=} \E_{s_0', \Mhat}\left[ \ind \left(\text{$\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$} \right)\P_{s_0', \Mhat} \left(\text{$\eta_{s^\star} \not \in \{(i-1)k, \dots, ik - 1\}$} \mid \mathcal{F}_{(i-1)k}\right)\right] \\
         &\stackrel{(iii)}{=} \E_{s_0', \Mhat}\left[ \ind \left(\text{$\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$} \right)\P_{S_k, \Mhat} \left(\text{$\eta_{s^\star} \not \in \{0, \dots, k-1\}$} \right)\right] \\
         &\stackrel{(iv)}{\leq} \frac{1}{2}\E_{s_0', \Mhat}\left[ \ind \left(\text{$\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$} \right) \right] \\
         &= \frac{1}{2}\P_{s_0', \Mhat}(\eta_{s^\star} \geq  (i-1)k)
    \end{align*}
    where $\mathcal{F}_{(i-1)k}$ is the sigma-algebra generated by $S_0, \dots, S_{(i-1)k}$, step $(i)$ is the tower property, step $(ii)$ is because the event $\eta_{s^\star} \not \in \{0, \dots, (i-1)k - 1\}$ is $\mathcal{F}_{(i-1)k}$-measurable, step $(iii)$ is the Markov property (e.g., \cite[Theorem 5.2.3]{durrett_probability_2019}), and step $(iv)$ is because
    $\P_{S_k, \Mhat} \left(\text{$\eta_{s^\star} \not \in \{0, \dots, k-1\}$} \right) = \P_{S_k, \Mhat}(\eta_{s^\star} \geq k) \leq \frac{1}{2}$ (this last inequality holding almost surely, due to the assumption that $\max_{s_0 \in \S} \P_{s_0, \Mhat} (\eta_{s^\star} \geq k) \leq \frac{1}{2}$).
    Since these arguments held for arbitrary $i$, we can repeat them to obtain the desired bound.

    Now we try to find such a $k$.
    Define the reward function $\raux$ by $\raux(s,a ) = \ind(s \neq s^\star)$ and also let $P'$ be the same transition matrix as $P$ except with state $s^\star$ made to be absorbing for all actions. Then, for some $\gammap$ to be chosen later, letting $V^{\pistar}_{\gammap, \Maux}$ be the discounted value function for policy $\pistar$ in MDP $\Maux = (P', \raux)$, and letting $\E^{\pistar}_{s_0, \Maux}, \E^{\pistar}_{s_0, \Mor}$ denote expectations with respect to the MDPs $\Maux$ and $\Mor$ respectively, we have that
    \begin{align*}
        V^{\pistar}_{\gammap, \Maux}(s_0) &= \E^{\pistar}_{s_0, \Maux} \sum_{t = 0}^\infty \gammap^t \ind(S_t \neq s^\star)\\
        &= \E^{\pistar}_{s_0, \Mor} \sum_{t = 0}^\infty \gammap^t \ind(\eta_{s^\star} > t) \\
        & \leq \E^{\pistar}_{s_0, \Mor} \sum_{t = 0}^\infty \ind(\eta_{s^\star} > t) \\
        &= \E^{\pistar}_{s_0, \Mor} [\eta_{s^\star}] \leq \Dow(P, \pistar, s^\star).
    \end{align*}
    This implies $\spannorm{V^{\pistar}_{\gammap, \Maux}} \leq \Dow(P, \pistar, s^\star)$, which will be needed shortly.

    Let $\Pt$ similarly be the same transition matrix as $\Phat$ except $s^\star$ is absorbing for all actions. Let $\Mt $ be the MDP $(\Pt, \raux)$. Then for any $k \in \N$ we have
    \begin{align*}
        V^{\pistar}_{\gammap, \Mt}(s_0) &= \E^{\pistar}_{s_0, \Mt} \sum_{t = 0}^\infty \gammap^t \ind(S_t \neq s^\star)\\
        &= \E^{\pistar}_{s_0, \Mhat} \sum_{t = 0}^\infty \gammap^t \ind(\eta_{s^\star} > t) \\
        &\geq \E^{\pistar}_{s_0, \Mhat} \sum_{t = 0}^{k-1} \gammap^t \ind(\eta_{s^\star} > t) \\
        &\geq \E^{\pistar}_{s_0, \Mhat} \sum_{t = 0}^{k-1} \gammap^{k-1} \ind(\eta_{s^\star} > k-1) \\
        &= k \gammap^{k-1} \P_{s_0, \Mhat} (\eta_{s^\star} > k-1).
    \end{align*}
    Rearranging this implies that
    \begin{align}
        \P_{s_0, \Mhat} (\eta_{s^\star} > k-1) \leq \frac{ V^{\pistar}_{\gammap, \Mt}(s_0)}{k \gammap^{k-1}} \leq \frac{ 3V^{\pistar}_{\gammap, \Mt}(s_0)}{k } \label{eq:dow_stability_3}
    \end{align}
    where for the second inequality we set $\gammap = 1 - \frac{1}{k}$ and used the fact that $(1-\frac{1}{k})^{k-1} \geq 1/e \geq 1/3$ for all integers $k > 1$. 

    Now we bound $V^{\pistar}_{\gammap, \Mt}(s_0)$ using concentration inequalities.
    For concreteness in the following application of Hoeffding we set $k = 12 \Dow(P, \pistar)$ so $\gamma = 1 - 1/(12 \Dow(P, \pistar))$.
    By Hoeffding's inequality, we have for any $s \neq s^\star$ that with probability at least $1 - \delta'$
    \begin{align*}
        \left| e_s^\top (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gammap, \Maux}\right| \leq \sqrt{\frac{\spannorm{V^{\pistar}_{\gammap, \Maux}}^2 \log \left(\frac{2}{\delta'} \right)}{2 n(s,\pistar(s))}} \leq \sqrt{\frac{(\Dow(P, \pistar, s^\star))^2 \log \left(\frac{2}{\delta'} \right)}{2 n(s,\pistar(s))}}
    \end{align*}
    and trivially we have $\left| e_{s^\star}^\top (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gamma, \Maux}\right| = 0$. Therefore by a union bound over all $s \in \S$ and setting $\delta' = \frac{\delta}{S}$, we have with probability at least $1 - \delta$ that
    \begin{align*}
        \infnorm{ (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gammap, \Maux}} \leq \min_{s \in \S} \sqrt{\frac{(\Dow(P, \pistar, s^\star))^2 \log \left(\frac{2S}{\delta} \right)}{2 n(s,\pistar(s))}} \leq \frac{1}{12}
    \end{align*}
    where the second inequality uses the condition that $n(s, \pistar(s)) \geq \frac{12^2}{2}(\Dow(P, \pistar, s^\star))^2 \log \left(\frac{2S}{\delta} \right) = 72(\Dow(P, \pistar))^2 \log \left(\frac{2S}{\delta} \right)$ for all $s \in \S$.

    Following standard arguments for the difference between two value functions with different transition matrices we have
    \begin{align*}
        V^{\pistar}_{\gammap, \Mt} - V^{\pistar}_{\gammap, \Maux} &= (I - \gammap \Pt_{\pistar})^{-1} \raux_{\pistar} - (I - \gammap P'_{\pistar})^{-1} \raux_{\pistar} \\
        &= (I - \gammap \Pt_{\pistar})^{-1} (I - \gammap P'_{\pistar}) (I - \gammap P'_{\pistar})^{-1} \raux_{\pistar} - (I - \gammap \Pt_{\pistar})^{-1} (I - \gammap \Pt_{\pistar}) (I - \gammap P'_{\pistar})^{-1} \raux_{\pistar} \\
        &= \gammap (I - \gammap \Pt_{\pistar})^{-1} (\Pt_{\pistar} - P'_{\pistar}) (I - \gammap P'_{\pistar})^{-1} \raux_{\pistar} \\
        &= \gammap (I - \gammap \Pt_{\pistar})^{-1} (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gammap, \Maux}.
    \end{align*}
    Hence
    \begin{align*}
        \infnorm{V^{\pistar}_{\gammap, \Mt} - V^{\pistar}_{\gammap, \Maux}} &= \infnorm{\gammap (I - \gammap \Pt_{\pistar})^{-1} (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gammap, \Maux}} \\
        & \leq \infinfnorm{\gammap (I - \gammap \Pt_{\pistar})^{-1}} \infnorm{ (\Pt_{\pistar} - P'_{\pistar}) V^{\pistar}_{\gammap, \Maux}} \\
        & \leq \frac{\gammap}{1-\gammap} \frac{1}{12} \\
        & \leq \frac{k}{12} = \Dow(P, \pistar, s^\star).
    \end{align*}
    Combining this with~\eqref{eq:dow_stability_3}, we have that
    \begin{align*}
        \max_{s_0 \in \S} \P_{s_0, \Mhat} (\eta_{s^\star} \geq k) &= 
        \max_{s_0 \in \S} \P_{s_0, \Mhat} (\eta_{s^\star} > k-1) \\
        &\leq \frac{3 \infnorm{V^{\pistar}_{\gammap, \Mt}}}{k} \leq \frac{3 \infnorm{V^{\pistar}_{\gammap, \Maux}}}{k} + \frac{3 \infnorm{V^{\pistar}_{\gammap, \Mt} - V^{\pistar}_{\gammap, \Maux}}}{k} \\
        &\leq \frac{3 \Dow(P, \pistar) + 3 \Dow(P, \pistar)}{12 \Dow(P, \pistar)} = \frac{1}{2}.
    \end{align*}

    Using $k = 12 \Dow(P, \pistar)$ in~\eqref{eq:dow_stability_2} and combining with~\eqref{eq:dow_stability_1}, we conclude that
    \begin{align*}
        \Dow(\Phat, \pistar) \leq  \max_{s_0 \in \S} \E_{s_0, \Mhat}^\pi [\eta_{s^\star}] \leq 2k = 24\Dow(P, \pistar)
    \end{align*}
    as desired.
\end{proof}

\begin{lem}
\label{lem:empirical_span_bound}
    Fix a deterministic unichain policy $\pistar$.
    Suppose that $n(s, \pistar(s))\geq 1 + \alpha \left(576\Dow(P, \pistar)\right)^2$ for all $s \in \S$, where $\alpha = 8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$. Then with probability at least $1 - 2\delta$,
    \begin{align*}
        \spannorm{\Vhpe^{\pistar}} \leq 3\spannorm{V^{\pistar}} + 2.
    \end{align*}
\end{lem}
\begin{proof}
    By the definition~\eqref{eq:defn_of_Thpe_pi} of $\Thpe^{\pistar}$, we have for any $s \in \S$ that
    \begin{align*}
        \Vhpe^{\pistar}(s) &= e_s^\top M^{\pistar} \Qhpe^{\pistar} \\
        &= e_s^\top M^{\pistar} \Thpe^{\pistar} \left(\Qhpe^{\pistar} \right) \\
        &= r(s, \pistar(s)) + \gamma \max \Big\{  \Phat_{s\pistar(s)} T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, M^{\pistar} \Qhpe^{\pistar}) - b(s,\pistar(s), M^{\pistar} \Qhpe^{\pistar}), \\
        &\qquad\qquad\qquad\qquad\qquad\qquad\min_{s'}(M^{\pistar} \Qhpe^{\pistar})(s') \Big \} \\
        &= r_{\pistar}(s) + \gamma \max \Big\{  \Phat_{s\pistar(s)} T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) - b(s,\pistar(s), \Vhpe^{\pistar}), \min_{s'}(\Vhpe^{\pistar})(s') \Big \} \\
        &= r_{\pistar}(s) + \gamma  \Phat_{s\pistar(s)} \Vhpe^{\pistar} + \gamma \max \Big\{  \Phat_{s\pistar(s)} \left(T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) - \Vhpe^{\pistar} \right) - b(s,\pistar(s), \Vhpe^{\pistar}),\\
        & \qquad\qquad\qquad\qquad\qquad\qquad \min_{s'}(\Vhpe^{\pistar})(s') - \Phat_{s\pistar(s)} \Vhpe^{\pistar} \Big \} \\
        &= r_{\pistar}(s) + \gamma  \Phat_{s\pistar(s)} \Vhpe^{\pistar} - \gamma \btp(s)
    \end{align*}
    where we have defined $\btp \in \R^\S$ as
    \begin{align*}
        \btp(s) = -\max \Big\{  \Phat_{s\pistar(s)} \left(T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) - \Vhpe^{\pistar} \right) - b(s,\pistar(s), \Vhpe^{\pistar}), \min_{s'}(\Vhpe^{\pistar})(s') - \Phat_{s\pistar(s)} \Vhpe^{\pistar} \Big \}.
    \end{align*}
    Note that both terms within the $\max$ in the definition of $\btp(s)$ are $\leq 0$, so $\btp \geq 0$, and also we can bound
    \begin{align}
        \btp(s) &\leq - \left(\Phat_{s\pistar(s)} \left(T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) - \Vhpe^{\pistar} \right) - b(s,\pistar(s), \Vhpe^{\pistar}) \right) \nonumber\\
        &= \Phat_{s\pistar(s)} \left(\Vhpe^{\pistar} - T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar})  \right) + b(s,\pistar(s), \Vhpe^{\pistar}) \nonumber\\
        &\stackrel{(i)}{\leq } \beta(s, \pistar(s)) \spannorm{\Vhpe^{\pistar}} + b(s,\pistar(s), \Vhpe^{\pistar}) \nonumber\\
        &\stackrel{(ii)}{\leq }  \sqrt{\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}^2 } + 2\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}  + \frac{5}{\ntot} \label{eq:btp_bound}
    \end{align}
    where $(i)$ is due to the fact that $\Phat_{s\pistar(s)}  T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) \geq \Phat_{s\pistar(s)} \Vhpe^{\pistar} - \beta(s, \pistar(s)) \spannorm{\Vhpe^{\pistar}}$, which holds by an argument identical to that of~\eqref{eq:Vhpe_pistar_inner_prod_lb}, and $(ii)$ holds since
    \begin{align*}
        b(s,\pistar(s),\Vhpe^{\pistar}) &=  \max \Big \{ \sqrt{\beta(s,\pistar(s))  \Var_{\Phat_{s\pistar(s)}} \left[ T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar}) \right]} , \\
        & \qquad\beta(s,\pistar(s)) \spannorm{T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar})} \Big \} + \frac{5}{\ntot} \\
        & \leq \max \Big \{ \sqrt{\beta(s,\pistar(s))  \Var_{\Phat_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right]} , \beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}} \Big \} + \frac{5}{\ntot} \\
        & \leq \max \Big \{ \sqrt{\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}^2 } , \beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}} \Big \} + \frac{5}{\ntot} \\
        & \leq  \sqrt{\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}^2 } + \beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}  + \frac{5}{\ntot}
    \end{align*}
    where we used Lemma \ref{lem:truncated_variance_bound} and the fact that $\spannorm{T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar})} \leq \spannorm{\Vhpe^{\pistar}}$ in the first inequality, 
    then that $\Var_{\Phat_{s\pistar(s)}} \left[ \Vhpe^{\pistar} \right] \leq \spannorm{\Vhpe^{\pistar}}^2$, and then bounded the $\max$ by the sum. 
    (While Lemma \ref{lem:truncated_variance_bound} is stated for $\beta(s, \pistar(s)) \leq 1$, if $\beta(s, \pistar(s)) > 1$ then $T_{\beta(s,\pistar(s))}( \Phat_{s\pistar(s)}, \Vhpe^{\pistar})$ is a constant vector so the bound is still true.)

    Now since $\btp$ satisfies $\Vhpe^{\pistar} = r_{\pistar} - \gamma\btp + \gamma \Phat_{\pistar} \Vhpe^{\pistar}$, we can rearrange to obtain that $\Vhpe^{\pistar} = (I - \gamma \Phat_{\pistar})^{-1} (r_{\pistar} - \gamma \btp)$. Likewise by the standard Bellman equation we have that $V^{\pistar} = r_{\pistar} + \gamma P_{\pistar} V^{\pistar}$ so $V^{\pistar} = (I - \gamma P_{\pistar})^{-1}r_{\pistar}$.
    Then we can calculate that
    \begin{align}
        V^{\pistar} - \Vhpe^{\pistar} &= (I - \gamma P_{\pistar})^{-1} r_{\pistar} - (I - \gamma \Phat_{\pistar})^{-1} (r_{\pistar}- \gamma\btp) \nonumber\\
    &= (I - \gamma \Phat_{\pistar})^{-1} (I - \gamma \Phat_{\pistar}) (I - \gamma P_{\pistar})^{-1} r_{\pistar} \nonumber\\
    & \qquad \qquad - (I - \gamma \Phat_{\pistar})^{-1} (I - \gamma P_{\pistar}) (I - \gamma P_{\pistar})^{-1} (r_{\pistar}- \gamma\btp) \nonumber\\
    &= \gamma (I - \gamma \Phat_{\pistar})^{-1} (P_{\pistar} - \Phat_{\pistar}) (I - \gamma P_{\pistar})^{-1} r_{\pistar} + (I - \gamma \Phat_{\pistar})^{-1}\gamma \btp \nonumber\\
    &= \gamma (I - \gamma \Phat_{\pistar})^{-1} (P_{\pistar} - \Phat_{\pistar}) V^{\pistar} + (I - \gamma \Phat_{\pistar})^{-1} \gamma \btp. \label{eq:empirical_span_bound_sim_lem}
    \end{align}

Now we can bound
    \begin{align}
        \spannorm{\Vhpe^{\pistar}} &= \max_{s,s'} (e_s - e_{s'})^\top \Vhpe^{\pistar} \nonumber\\
        &= \max_{s,s'} (e_s - e_{s'})^\top \left(V^{\pistar} + \Vhpe^{\pistar} - V^{\pistar} \right) \nonumber \\
        & \leq \max_{s,s'} (e_s - e_{s'})^\top \left(V^{\pistar}  \right) + \max_{s,s'} (e_s - e_{s'})^\top \left( \Vhpe^{\pistar} - V^{\pistar} \right) \nonumber \\
        &= \spannorm{V^{\pistar}} + \max_{s,s'} (e_s - e_{s'})^\top \left( \Vhpe^{\pistar} - V^{\pistar} \right). \label{eq:emp_sp_bd_1}
    \end{align}

    Fixing arbitrary $s, s' \in \S$ and letting $\xi = e_s - e_{s'}$, and using~\eqref{eq:empirical_span_bound_sim_lem}, we have that
    \begin{align}
        \xi^\top \left(\Vhpe^{\pistar} - V^{\pistar} \right) &= \xi^\top \left( \gamma (I - \gamma \Phat_{\pistar})^{-1} (\Phat_{\pistar} - P_{\pistar}) V^{\pistar} - (I - \gamma \Phat_{\pistar})^{-1} \gamma \btp\right) \nonumber \\
        & \leq \gamma \onenorm{\xi^\top (I - \gamma \Phat_{\pistar})^{-1}} \infnorm{(\Phat_{\pistar} - P_{\pistar}) V^{\pistar}} + \gamma \onenorm{\xi^\top (I - \gamma \Phat_{\pistar})^{-1}} \infnorm{\btp} .\label{eq:emp_sp_bd_2}
    \end{align}
    Next we bound all the terms in~\eqref{eq:emp_sp_bd_2}.
    First, $\onenorm{\xi^\top (I - \gamma \Phat_{\pistar})^{-1}} \leq 4 \Dow(\Phat, \pistar)$ by Lemma \ref{lem:occupancy_l1_diff_coupling_bound}, and furthermore by Lemma \ref{lem:dow_stability}, since its conditions are satisfied under the conditions of the present lemma (since $\alpha \geq \log(\frac{2S}{\delta})$), we have with probability at least $1 - \delta$ that $\Dow(\Phat, \pistar) \leq 24 \Dow(P, \pistar)$. Hence $\onenorm{\xi^\top (I - \gamma \Phat_{\pistar})^{-1}} \leq 96 \Dow(P, \pistar)$. Next, for any $s\in \S$, by Hoeffding's inequality, with probability at least $1 - \delta'$ we have
    \begin{align*}
        \left|e_s^\top (\Phat_{\pistar} - P_{\pistar}) V^{\pistar} \right| & \leq \sqrt{\frac{\spannorm{V^{\pistar}}^2 \log \left( \frac{2}{\delta'}\right)}{2n(s,\pistar(s))}}
    \end{align*}
    and so by a union bound over all $s \in \S$ and setting $\delta' = \frac{\delta}{S}$, we have that with additional failure probability at most $\delta$ that 
    \begin{align*}
        \infnorm{(\Phat_{\pistar} - P_{\pistar}) V^{\pistar}} \leq \spannorm{V^{\pistar}} \sqrt{\max_{s \in \S}\frac{\log(\frac{2S}{\delta})}{2 n(s, \pistar(s))}}.
    \end{align*}
    Finally, using the bound~\eqref{eq:btp_bound}, we have
    \begin{align*}
        \infnorm{\btp} &\leq \max_{s \in \S} \sqrt{\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}^2 } + 2\beta(s,\pistar(s)) \spannorm{\Vhpe^{\pistar}}  + \frac{5}{\ntot} \\
        & \leq \max_{s \in \S} 3\sqrt{\beta(s,\pistar(s)) } \spannorm{\Vhpe^{\pistar}}  + \frac{5}{\ntot}
    \end{align*}
    because our condition on $n(s, \pistar(s))$ guarantees that $\beta(s, \pistar(s)) \leq 1$ so $\beta(s, \pistar(s)) \leq \sqrt{\beta(s, \pistar(s))}$.

    Combining these three bounds with~\eqref{eq:emp_sp_bd_2}, using that $\gamma \leq 1$, and taking the maximum over all $s, s'$, we have that
    \begin{align*}
        &\max_{s,s'} (e_s - e_{s'})^\top \left( \Vhpe^{\pistar} - V^{\pistar} \right) \\
        &\leq 96 \Dow(P, \pistar) \left(\spannorm{V^{\pistar}} \sqrt{\max_{s \in \S}\frac{\log(\frac{2S}{\delta})}{2 n(s, \pistar(s))}} + 3\sqrt{\max_{s\in \S}\beta(s,\pistar(s)) } \spannorm{\Vhpe^{\pistar}}  + \frac{5}{\ntot} \right)
    \end{align*}
    Combining this with~\eqref{eq:emp_sp_bd_1} and rearranging, we have that
    \begin{align}
        &\spannorm{\Vhpe^{\pistar}}  \left(1 - 3 \cdot 96 \Dow(P, \pistar)\sqrt{\max_{s\in \S}\beta(s,\pistar(s)) } \right) \nonumber\\
        & \qquad \leq \spannorm{V^{\pistar}} \left(1 + 96 \Dow(P, \pistar)\sqrt{\max_{s \in \S}\frac{\log(\frac{2S}{\delta})}{2 n(s, \pistar(s))}} \right) + 96 \Dow(P, \pistar) \frac{5}{\ntot}. \label{eq:emp_sp_bd_3}
    \end{align}
    Noticing that $576 = 3 \cdot 2 \cdot 96$, our condition on $n(s, \pistar(s))$ in the lemma statement is chosen exactly so that
    \begin{align*}
        \left(1 - 3 \cdot 96 \Dow(P, \pistar)\sqrt{\max_{s\in \S}\beta(s,\pistar(s)) } \right) &=  \left(1 - 3 \cdot 96 \Dow(P, \pistar)\sqrt{\max_{s\in \S}\frac{\alpha}{n(s,\pistar(s))-1} } \right)\\
        &\geq 1 - \frac{1}{2} = \frac{1}{2}.
    \end{align*}
    Also since for all $s \in \S$ $\beta(s, \pistar(s)) = \frac{\alpha}{n(s, \pistar(s)) - 1}\geq \frac{\log(\frac{2S}{\delta})}{2 n(s, \pistar(s))}$ (since $\alpha \geq 8\log(\frac{2S}{\delta})$ and $n(s, \pistar(s)) \geq 4$ so $n(s, \pistar(s)) -1 \geq \frac{1}{2} n(s, \pistar(s))$), we can also simply bound
    \begin{align*}
        \left(1 + 96 \Dow(P, \pistar)\sqrt{\max_{s \in \S}\frac{\log(\frac{2S}{\delta})}{2 n(s, \pistar(s))}} \right) \leq 1 + \frac{1}{2}.
    \end{align*}
    We can also bound $96 \Dow(P, \pistar) \frac{5}{\ntot} \leq 1$ (by lower-bounding $\ntot$ by $n(s_0, \pistar(s_0))$ for one arbitrary $s_0 \in \S$). Combining all these bounds with~\eqref{eq:emp_sp_bd_3}, we obtain
    \begin{align*}
        \frac{1}{2}\spannorm{\Vhpe^{\pistar}} \leq \frac{3}{2}\spannorm{V^{\pistar}} + 1
    \end{align*}
    which implies
    \begin{align*}
        \spannorm{\Vhpe^{\pistar}} \leq 3\spannorm{V^{\pistar}} + 2
    \end{align*}
    as desired.
\end{proof}

\subsection{Average-reward-to-discounted reduction}
Now we can combine our previous results and relate the discounted MDP quantities to $\rho^{\pistar}$ and $h^{\pistar}$.

\begin{lem}
\label{lem:amdp_dmdp_red}
    There exist some absolute constants $C_1, C_2$ such that the following holds:\
    Fix a deterministic unichain policy $\pistar$.
    Suppose that $n(s, \pistar(s))\geq m \mu^{\pistar}(s) + 4 + \alpha \left(576\Dow(P, \pistar)\right)^2$ for all $s \in \S$, where $\alpha = 8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)$, and that $\frac{1}{1-\gamma} \geq m$ and $\frac{1}{1-\gamma} \geq 2$. Then with probability at least $1 - 5\delta$, we have that
    \begin{align*}
        \rho^{\pihat} &\geq \rho^{\pistar} -  \sqrt{\frac{C_1 S \left(\spannorm{h^{\pistar}} +1\right)\alpha}{m}}\one -  \frac{C_2 S \left(\spannorm{h^{\pistar}} +1\right)  \alpha}{m}\one.
    \end{align*}
\end{lem}
\begin{proof}
    By Lemma \ref{lem:error_analysis_empirical_span} (the conditions of which are met here as $\alpha(s, \pistar(s)) \left(576\Dow(P, \pistar)\right)^2 \geq 4 \Dow(P, \pistar)$), we have under the event of Lemma \ref{lem:concentration_for_pessimism_Thpe_pistar}, which holds with probability at least $1 - 2\delta$, that
    \begin{align*}
        &\max_{s_0 \in \S} \left( V^{\pistar}(s_0) - \Vhpe^{\pistar}(s_0) \right) \\
        &\leq \frac{1}{1-\gamma}\sqrt{\frac{2048 S \spannorm{\Vhpe^{\pistar}} \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}} +  \frac{640 S \spannorm{\Vhpe^{\pistar}}  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{(1-\gamma)m} + \frac{12}{(1-\gamma)\ntot}.
    \end{align*}
    Combining this with the conclusion of Lemma \ref{lem:empirical_span_bound} which implies $\spannorm{\Vhpe^{\pistar}} \leq 3\left(\spannorm{V^{\pistar}} +1\right)$ and adds additional failure probability at most $2\delta$ by the union bound, we have that
    \begin{align}
        \max_{s_0 \in \S} \left( V^{\pistar}(s_0) - \Vhpe^{\pistar}(s_0) \right)
        &\leq \frac{1}{1-\gamma}\sqrt{\frac{6144 S \left(\spannorm{V^{\pistar}} +1\right)\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}} \nonumber \\
        & \qquad +  \frac{1920 S \left(\spannorm{V^{\pistar}} +1\right)  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{(1-\gamma)m} + \frac{12}{(1-\gamma)\ntot}. \label{eq:dmdp_red_1}
    \end{align}
    For convenience abbreviate the right-hand-side of~\eqref{eq:dmdp_red_1} as $\varepsilon$. Then since $Q^{\pihat} \geq \Qhat$ by Lemma \ref{lem:pessimism} (which holds under the event of Lemma \ref{lem:concentration_for_pessimism_Thpe}, adding additional failure probability at most $\delta$) and $\Qhat \geq \Qhpe^\star - \frac{1}{2\ntot}\one$ by Lemma \ref{lem:opt_guarantees}, we have that
    \begin{align}
        V^{\pihat} = M^{\pihat} Q^{\pihat} \geq M^{\pihat}\Qhat = M\Qhat\geq M\left( \Qhpe^\star - \frac{1}{2\ntot}\one \right) = M \Qhpe^{\star} - \frac{1}{2\ntot}\one = \Vhpe^\star - \frac{1}{2\ntot}\one. \label{eq:dmdp_red_2}
    \end{align}
    Furthermore we have
    \begin{align}
        \Vhpe^\star \stackrel{(i)}{\geq} \Vhpe^{\pistar} \stackrel{(ii)}{\geq} V^{\pistar} - \varepsilon \one \stackrel{(iii)}{\geq} \frac{1}{1-\gamma}\rho^{\pistar} - \spannorm{V^{\pistar}}\one - \varepsilon \one \label{eq:dmdp_red_3}
    \end{align}
    where $(i)$ is due to Lemma \ref{lem:pessimistic_Bellman_operator_properties} which gives $\Qhpe^\star \geq \Qhpe^{\pistar}$, which implies $\Vhpe^\star = M\Qhpe^\star \geq M^{\pistar} \Qhpe^\star \geq M^{\pistar}\Qhpe^{\pistar}$ using monotonicity of $M^{\pistar}$. $(ii)$ is due to~\eqref{eq:dmdp_red_1}, and $(iii)$ uses $\infnorm{V^{\pistar} - \frac{1}{1-\gamma}\rho^{\pistar}} \leq \spannorm{V^{\pistar}}$ due to \citet[Lemma 6]{zurek_span-agnostic_2025}.
    Also by \citet[Lemma 6]{zurek_span-agnostic_2025}, we have the elementwise inequality $\rho^{\pihat} \geq (1-\gamma)\left(\min_{s \in \S} V^{\pihat}(s)\right) \one$. Thus
    \begin{align*}
        \rho^{\pihat} &\geq (1-\gamma)\min_{s \in \S} V^{\pihat}(s)\one \\
        &\stackrel{(i)}{\geq} (1-\gamma)\min_{s \in \S} \Vhpe^\star(s)\one  - \frac{1-\gamma}{2\ntot}\one \\
        & \stackrel{(ii)}{\geq} \min_{s \in \S} \rho^{\pistar}(s) \one-(1-\gamma)\spannorm{V^{\pistar}}\one - (1-\gamma)\varepsilon \one  - \frac{1-\gamma}{2\ntot}\one \\
        & \stackrel{(iii)}{\geq} \rho^{\pistar} -(1-\gamma)\spannorm{V^{\pistar}}\one- \frac{1-\gamma}{2\ntot}\one -  \sqrt{\frac{6144 S \left(\spannorm{V^{\pistar}} +1\right)\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}} \one\nonumber \\
        & \qquad -  \frac{1920 S \left(\spannorm{V^{\pistar}} +1\right)  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m} \one- \frac{12}{\ntot} \one\\
        & \stackrel{(iv)}{\geq} \rho^{\pistar} -  \sqrt{\frac{6144 S \left(\spannorm{V^{\pistar}} +1\right)\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}}\one -  \frac{1933 S \left(\spannorm{V^{\pistar}} +1\right)  \log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right)}{m}  \one
    \end{align*}
    where $(i)$ uses~\eqref{eq:dmdp_red_2}, $(ii)$ uses~\eqref{eq:dmdp_red_3}, $(iii)$ uses the fact that $\rho^{\pistar}$ is assumed to be state-independent and the definition of $\varepsilon$ (and canceling/simplifying), and $(iv)$ uses that $\frac{1}{1-\gamma} \geq m$ (so $(1-\gamma ) \leq \frac{1}{m}$), that $1 - \gamma \leq 1$, and $\ntot \geq m$.

    Furthermore, using \citet[Lemma 26]{zurek_span-agnostic_2025} we have (since $\rho^{\pistar}$ is constant) that $\spannorm{V^{\pistar}} \leq 2\spannorm{h^{\pistar}}$. Combining this with the above bound and letting $C_1 = 2 \cdot 6144 / 8, C_2 = 2 \cdot 1933/8$, we obtain the desired bound.
\end{proof}

\subsection{Completing the proof}
Here we complete the proof of the main Theorem \ref{thm:main_theorem} by checking conditions and simplifying previous results. The following result is actually more general than Theorem \ref{thm:main_theorem} because it allows an arbitrary unichain deterministic comparator policy $\pistar$, rather than requiring $\pistar$ to be gain-optimal. Theorem \ref{thm:main_theorem} follows immediately from the below theorem by adding this additional requirement that $\rho^{\pistar} = \rho^\star$.
\begin{thm}
\label{thm:main_thm_arbitrary_comp}
    There exist absolute constants $C_1', C_2'$ such that the following holds:
    Fix $\delta > 0$. Let $\gamma = 1-\frac{1}{\ntot}$ and $\alpha = 8\log \big( \frac{6S^2A\ntot}{(1-\gamma)\delta}\big)$. Let $\pistar $ be a deterministic policy which is unichain with stationary distribution $\mu^{\pistar}$. Suppose there exists some $m \in \N$ such that
    \begin{align*}
        n(s, \pistar(s)) \geq m \mu^{\pistar}(s) + \alpha \left(C_2'\Dow(P, \pistar)\right)^2 +4.
    \end{align*}
    Then letting $\pihat$ be the policy returned by Algorithm \ref{alg:LCBVI} with inputs $\dataset$, $r$, $\gamma = 1 - \frac{1}{\ntot}$, and $\delta$,  we have with probability at least $1  - 5\delta$ that
    \begin{align*}
        \rho^{\pihat} \geq \rho^{\pistar} - \sqrt{\frac{C_1' S \left(\spannorm{h^{\pistar}} + 1\right)\alpha }{m}}.
    \end{align*}
\end{thm}
\begin{proof}
    Note that the condition on $n$ implies that $\ntot \geq 4$, so setting $\frac{1}{1-\gamma} = \ntot$ has $\frac{1}{1-\gamma} \geq 2$. Also we have
    \begin{align*}
        \ntot \geq \sum_{s \in \S} n(s, \pistar(s)) \geq \sum_{s \in \S} m \mu^{\pistar}(s) = m
    \end{align*}
    using the assumption on $n(s, \pistar(s))$ for all $s$, so setting $\frac{1}{1-\gamma} = \ntot$ also ensures $\frac{1}{1-\gamma} \geq m$. Therefore we can apply Lemma \ref{lem:amdp_dmdp_red} to obtain that
    if $n(s, \pistar(s))\geq m \mu^{\pistar}(s) + 4 + \alpha \left(576\Dow(P, \pistar)\right)^2$ for all $s \in \S$, then with probability at least $1 - 5\delta$, we have
    \begin{align*}
        \rho^{\pihat} &\geq \rho^{\pistar} -  \sqrt{\frac{C_1 S \left(\spannorm{h^{\pistar}} +1\right)\alpha}{m}}\one -  \frac{C_2 S \left(\spannorm{h^{\pistar}} +1\right)  \alpha}{m}\one
    \end{align*}
    where $\alpha = 8\log \left( \frac{6S^2A\ntot}{(1-\gamma)\delta}\right) = 8\log \left( \frac{6S^2A\ntot^2}{\delta}\right)$. Thus we can set $C_2' = 576$. To choose $C_1'$, note that since trivially $\rho^{\pistar} \leq \one$ and $\rho^{\pihat} \geq \zero$, if the term $\frac{C_2 S \left(\spannorm{h^{\pistar}} +1\right)  \alpha}{m} \geq 1$ then the bound
    \begin{align*}
        \rho^{\pihat} &\geq \rho^{\pistar} -  \sqrt{ \frac{C_2 S \left(\spannorm{h^{\pistar}} +1\right)  \alpha}{m}}\one
    \end{align*}
    holds vacuously, and otherwise if it is $\leq 1$ then we have
    \begin{align*}
        \rho^{\pihat} &\geq \rho^{\pistar} -  \sqrt{\frac{C_1 S \left(\spannorm{h^{\pistar}} +1\right)\alpha}{m}}\one -  \sqrt{\frac{C_2 S \left(\spannorm{h^{\pistar}} +1\right)  \alpha}{m}\one}
    \end{align*}
    since $\sqrt{x} \geq x$ for $x \in [0,1]$. Since $\sqrt{a} + \sqrt{b} \leq \sqrt{2(a+b)}$, we can take $C_1' = 2(C_1 + C_2)$.
\end{proof}

\section{Proof of Theorem \ref{thm:transient_lb}}
\label{sec:proof_transient_lb}

Let $T \geq 4$ and $m \in \mathbb{N}$ be arbitrary. 

\paragraph{Step 1: MDP construction}

Define $p = \frac{1}{3(m+T)}$, $A = \left\lceil \frac{16}{pT} \right\rceil$, and $q = \frac{1}{AT}$.
The set of states is $\S=\{0,1\}$, and the set of actions is $\A=\{0,1,\dots,A-1\}$.
The reward function $r : \S \times \A \to [0,1]$ is defined by $r(0,a)=1$ and $r(1,a)=0$ for all $a\in\A$.
We define an index set $\Theta = \Big\{(i,b)\,\Big|\, i\in\{0,1\}, b\in\{0,1,\dots,A-1\}\Big\}$. 
For each $\theta = (i,b) \in \Theta$, we define the transition matrix $P_\theta$ as follows:
\begin{center}
\begin{tabular}{ c | c | c }
$s$ & $a$ & $P_\theta(s' |s,a)$ \\ 
 \hline
0 & $i$ & $\ind(s'=0)$ \\  
0 & $1-i$ & $\left(1-p\right)\ind(s'=0) + p\ind(s'=1)$\\
0 & $\geq 2$ & $\ind(s'=1)$ \\
1 & $b$ & $\frac{1}{T}\ind(s'=0) + \left( 1 - \frac{1}{T} \right) \ind(s'=1)$\\
1 & $\neq b$ & $q\ind(s'=0) + \left(1-q\right)\ind(s'=1)$
\end{tabular}
\end{center}
\begin{figure}[H]
    \centering
