    [ -> , >=stealth, shorten >=2pt , line width=0.5pt, node distance =2cm, scale=1.1, transform shape]

    \node [circle, draw, minimum width=1.3cm] (s0) at (-3 , 0) {0};
    \node [circle, draw, minimum width=1.3cm] (s1) at (3 , 0) {1};
