    \path (s0) edge[-,red] [bend left] node [above] {} (dot0) ;
    \path (dot0) edge[dashed,red] [bend left] node [below right,text=black] {$1-\frac{1}{p}$} (s0);
    \path (dot0) edge[dashed,red] [bend right=10] node [above,text=black] {$\frac{1}{p}$} (s1);

    \path (s1) edge[-,blue] [bend left] node [above] {} (dot1) ;
    \path (dot1) edge[dashed,blue] [bend left] node [right,text=black] {$1-\frac{1}{T}$} (s1);
    \path (dot1) edge[dashed,blue] [bend right] node [above,text=black] {$\frac{1}{T}$} (s0);

    \path (s1) edge[-,red] [bend left] node [above] {} (dot2) ;
    \path (dot2) edge[dashed,red] [bend left] node [left,text=black] {$1-q$} (s1);
