Observe that the decision-maker needs to decide between two actions in states $1,\dots,S'$. Both actions give an immediate reward of $1$, but one action has a slightly higher probability of transiting to the bad state 0. At state 0, which has a reward of 0, the agent will likely be trapped for a long time before returning to one of states $1,\dots,S'$.
See Figure \ref{fig:recurrent_lb} for a diagram of the MDP $(P_\theta,r)$ for $\theta=(0,\dots,0)$.
We now state some easily verifiable facts about the MDP $(P_\theta, r)$:
\begin{itemize}
\item The MDP has $S$ states, is unichain, and has diameter $\frac{1}{q}+\frac{1}{1/2} = D+2= T$.
\item There is a unique gain-optimal policy $\pistar_\theta$. It takes action 0 in state 0 and action $\theta_s$ in state $s$ for $s\geq 1$.
\item $\mu^{\pistar_\theta}_\theta(0) = \frac{p}{p+q} = \frac{1-\varepsilon}{2-\varepsilon}$. By symmetry, it follows that $\mu^{\pistar_\theta}_\theta(s) = \frac{1}{S'}\left(1-\mu_\theta^{\pistar_\theta}\right) = \frac{1/S'}{2-\varepsilon}$ for $s\geq 1$.
\item The optimal gain is $\rho^*_\theta = 1 - \mu_\theta^{\pistar_\theta}(0) = \frac{1}{2-\varepsilon}$.
\end{itemize}

Note that actions $2,\dots,S'$ for states $s\geq 1$ are always suboptimal, and only exist to keep the diameter bounded by $T$.
Furthermore, actions $1,\dots,S'$ in state 0 simply keep the action space independent of the state, consistent with our upper bounds.
As such, whenever we consider some policy $\pi$, we will assume that it may only take actions 0 and 1 in states $s\geq 1$ and action 0 in state 0.

\paragraph{Step 2: dataset construction}

We define $n : \mathcal{S} \times \mathcal{A} \to \mathbb{N}$ by $n(0,0) = m$ and 
\[
n(s,a) = \frac{2m}{S'}
\]
for all $s\geq 1$ and $a\in\{0,1\}$.
For all other $(s,a)$ we set $n(s,a) = 0$.
Observe that this choice of $n$ satisfies $n(s,\pistar_\theta(s)) = \frac{m}{S'} + \frac{m}{S'} \geq m\mu_\theta^{\pistar_\theta}(s) + k$ for all $s\in\S$.

\paragraph{Step 3: reduction to estimation}

Given a stationary policy $\pi$ and some $\theta\in\Theta$, let $L_\theta^\pi(s)$ be the proportion of incorrect actions $\pi$ takes in state $s$. 
To be precise, we define $L_\theta^\pi(s) = \pi(1-\theta_s|s)$.
We also set $L_\theta^\pi = \sum_{s=1}^{S'} L_\theta^\pi(s)$.
By Lemma \ref{lem:gain}, we can upper bound the gain of a policy $\pi$ in terms of $L^\pi_\theta$:
\[
    \rho_\theta^\pi \leq \frac{1+\varepsilon^2}{2-\varepsilon(1-L_\theta^\pi/S')}
.\]
Subsequently, for any stationary policy $\pi$,
\begin{equation} \label{eq:optimality_gap}
\rho_\theta^* - \rho_\theta^{\pi} \geq \frac{1}{2-\varepsilon} - \frac{1+\varepsilon^2}{2-\varepsilon(1-L_\theta^\pi/S')} \geq  \frac{\varepsilon L_\theta^\pi/S'  - 2\varepsilon^2}{4}
.
\end{equation}

Now, suppose the underlying MDP is $(P_\theta,r)$.
Let $\mathscr{A}$ be an algorithm that maps the dataset to a stationary policy $\hat{\pi}=\mathscr{A}(\mathcal{D})$,
and consider the estimator $\hat{\theta}^\mathscr{A}$ whose $s$th coordinate is $\hat{\pi}(1|s)$.
By the definition of $L_\theta^{\hat{\pi}}$, we have $L_\theta^{\hat{\pi}} = \left\| \hat{\theta}^\mathscr{A} - \theta \right\|_1$.
Our next step is to show that no estimator can achieve low $\ell_1$ error uniformly over $\Theta$ with high probability, a result which will lower bound $L_\theta^{\hat{\pi}}$ and consequently also the sub-optimality of $\hat{\pi}$ for some $\theta$.

\paragraph{Step 4: Fano's method}

We will achieve such a lower bound with Fano's method.
First, by the Gilbert-Varshamov Lemma (Lemma \ref{lem:gilbert_varshamov}), there exists some subset $\Theta'\subset\Theta$ such that $|\Theta'| \geq 2^{S'/8}$ and $\|\theta - \theta'\|_1 \geq S'/8$ for any $\theta\neq\theta'\in \Theta'$.
Since $\max_{\theta,\theta'\in\Theta'} \text{KL}(\P_{\theta,n} \,\|\, \P_{\theta',n}) \leq (S'/16 - 1)\log2$ by Lemma \ref{lem:maxkl}, Local Fano's (Lemma \ref{lem:fano}) gives us that for any estimator $\hat{\theta}$,

\[
\max_\theta \E_{\theta,n}\left[ \left\| \hat{\theta} - \theta \right\|_1 \right] \geq \frac{S'}{16} \left( 1 - \frac{(S'/16 - 1)\log2+ \log2}{\log\left(2^{S'/8}\right)} \right) \geq \frac{S'}{32}
,\]
which implies that
\[
\max_{\theta\in\Theta} \P_{\theta,n}\left( \left\| \hat{\theta} - \theta \right\|_1 > \frac{S'}{64} \right) \geq \frac{1}{64}
.\]
Since the above holds for estimator of the dataset, it of course holds for $\hat{\theta}^\mathscr{A}$, where $\mathscr{A}$ is any algorithm that maps the dataset to a stationary policy.
Therefore,
\begin{equation} \label{eq:lb_error}
\max_\theta \P_{\theta,n}\left( L^{\mathscr{A}(\mathcal{D})}_\theta > \frac{S'}{64} \right) \geq \frac{1}{64}
.
\end{equation}
Now, by Equation \ref{eq:optimality_gap}, in the event that $L_\theta^{\mathscr{A}(\mathcal{D})} > \frac{S'}{64}$,
\[
\rho_\theta^* - \rho_\theta^{\mathscr{A}(\mathcal{D})} > \frac{\varepsilon/64 - 2\varepsilon^2}{4} \geq \frac{\varepsilon}{512}
= 2^{-17} \sqrt{\frac{TS}{m}}
,\]
with the second inequality holding by $\varepsilon \leq \frac{1}{256}$.
Thus, plugging back into Equation \ref{eq:lb_error} yields
\[
\max_\theta \P_{\theta,n}\left( \rho_\theta^* - \rho_\theta^{\mathscr{A}(\mathcal{D})} > c_3 \sqrt{\frac{TS}{m}}\right) \geq \frac{1}{64}
,\]
with $c_3 = 2^{-17}$.
\qed

\subsection{Auxiliary lemmas}

\begin{lem} \label{lem:gain}
Let $\pi$ be a stationary policy on MDP $M_\theta$. Then
\[
\rho_\theta^\pi \leq \frac{1+\varepsilon^2}{2-\varepsilon(1-L_\theta^\pi/S')}
.\]
\end{lem}
\begin{proof}
A routine computation (see Lemma \ref{lem:recurrent_lb_gain_computation}) yields
\[
\rho_\theta^\pi = \frac{\frac{q}{S'}\sum_{s=1}^{S'}\frac{1}{\kappa_s}}{1+\frac{q}{S'}\sum_{s=1}^{S'}\frac{1}{\kappa_s}}
,\]
where $\kappa_s = L_\theta^\pi(s) q + (1-L_\theta^\pi(s))p = \frac{1 - \varepsilon(1-L_\theta^\pi(s))}{D}$ is the probability of transiting from state $s$ to state 0 under $\pi$.
Since $\frac{x}{1+x}$ is monotonically increasing for $x>-1$, to achieve the desired upper bound for $\rho_\theta^\pi$ it suffices to find an acceptable upper bound for $\lambda :=\frac{q}{S'}\sum_{s=1}^{S'}\frac{1}{\kappa_s} = \frac{1}{S'}\sum_{s=1}^{S'} \frac{1}{1-\varepsilon(1-L_\theta^\pi(s))}$.

Defining $f(x) = \frac{1}{1-x}$ and $\lambda_s = \varepsilon(1-L_\theta^\pi(s))$, we have that 
\[
\lambda = \sum_{s=1}^{S'} \frac{1}{S'} f(\lambda_s)
.\]
We would like to get a bound that looks like $\lambda \leq f\left( \frac{1}{S'} \sum_{s=1}^{S'} \lambda_s \right)$.
This goal suggests applying Jensen's inequality, but since $f$ is convex for $x < 1$ it gives us an inequality in the wrong direction.
It turns out, however, that because $f$ is nearly linear in the sufficiently small interval of interest, we can obtain an inequality in the right direction with some error term of lower order.

Since $\lambda_s \in [0,\varepsilon]$ for all $s\in\{1,\dots,S'\}$, Lemma \ref{lem:reverse_jensen} give us
\begin{align*}
\lambda 
&\leq f\left( \sum_{s=1}^{S'} \frac{\lambda_s}{S'} \right) + f(0) + f(\varepsilon) - 2f\left(\frac{\varepsilon}{2}\right) \\
&= \frac{1}{1 - \varepsilon(1 - L_\theta^\pi/S')} + 1 + \frac{1}{1-\varepsilon} - \frac{2}{1-\varepsilon/2} \\
&\leq \frac{1}{1 - \varepsilon(1 - L_\theta^\pi/S')} + \varepsilon^2,
\end{align*}
where the last inequality holds for $\varepsilon < \frac{1}{3}$.
Consequently,
\[
\rho_\theta^\pi \leq \frac{\lambda}{1 + \lambda} \leq \frac{\frac{1}{1 - \varepsilon(1 - L_\theta^\pi/S')} + \varepsilon^2}{1 + \frac{1}{1 - \varepsilon(1 - L_\theta^\pi/S')} + \varepsilon^2} \leq \frac{1 + \varepsilon^2}{2- \varepsilon(1 - L_\theta^\pi / S')}
.\]
\end{proof}


\begin{lem}[Gilbert-Varshamov Lemma {\citep[Lemma 4.7]{massart_concentration_2007}}] \label{lem:gilbert_varshamov}
Let $d \geq 8$.
There exists $\Omega_d \subset \{0,1\}^d$ such that $|\Omega_d| \geq 2^{d/8}$ and $\|\omega - \omega' \|_1 \geq d / 8$ for all $\omega \neq \omega' \in \Omega_d$.
%\gzcomment{cite Massart Concentration Inequalities and Model Selection Lemma 4.7}
%\mzcomment{\cite[Lemma 4.7]{massart_concentration_2007}}
\end{lem}

\begin{lem} \label{lem:maxkl}
For any $\theta, \theta' \in \Theta$, we have
\[
\textnormal{KL}(\P_{\theta,n} \,\|\, \P_{\theta',n}) \leq \left( \frac{S'}{16} - 1\right) \log 2
.\]
\end{lem}
\begin{proof}
Let $\theta,\theta' \in \Theta$.
By the construction of $\P_{\theta,n}$ and $\P_{\theta',n}$, we can decompose
\[
\text{KL}(\P_{\theta,n} \,\|\, \P_{\theta',n})
= 
\sum_{s=0}^{S'} \sum_{a\in\{0,1\}} n(s,a) \text{KL}(P_\theta(\cdot\,|\,s,a)\,\|\, P_{\theta'}(\cdot\,|\,s,a))
.\]
Recalling our choice of $n$, we can further simplify
\[
\text{KL}(\P_{\theta,n} \,\|\, \P_{\theta',n})
=
\sum_{s=1}^{S'} \frac{2m}{S'} \left( \text{KL}(P_\theta(\cdot\,|\,s,0)\,\|\, P_{\theta'}(\cdot\,|\,s,0)) + \text{KL}(1_\theta(\cdot\,|\,s,1)\,\|\, P_{\theta'}(\cdot\,|\,s,1))\right)
,\]
where we remove the $s=0$ term from the sum because the data coming from state 0 has the same distribution for all possible MDPs.
Observing that
\[
\frac{2(p-q)^2}{p(1-p)}
=
\frac{2(\varepsilon/D)^2}{\left(\frac{1-\varepsilon}{D}\right) \left(\frac{D-1+\varepsilon}{D}\right)}
\leq
\frac{2\varepsilon^2}{\left(\frac{1}{2}\right)\left(\frac{D}{2}\right)} = \frac{8\varepsilon^2}{D}
,\]
we can apply Lemma \ref{lem:bernoulli_kl} to further simplify
\begin{align*}
\text{KL}(\P_{\theta,n} \,\|\, \P_{\theta',n})
& = \sum_{s=1}^{S'} \frac{2m}{S'}  \left( \text{KL}(P_\theta(\cdot\,|\,s,0)\,\|\, P_{\theta'}(\cdot\,|\,s,0)) + \text{KL}(1_\theta(\cdot\,|\,s,1)\,\|\, P_{\theta'}(\cdot\,|\,s,1))\right) \\
&\leq 2m  \left(\text{KL}\left(\text{Ber}(p) \,\|\, \text{Ber}(q)\right) + \text{KL}\left(\text{Ber}(q) \,\|\, \text{Ber}(p)\right) \right) \\
&\leq 2m  \frac{8\varepsilon^2}{D}  \\
&= 2m \frac{8 \cdot 2^{-16} \frac{TS}{m}}{T-2} \\
&\leq 2^{-10} S' \\
&\leq \left( \frac{S'}{16} - 1\right) \log 2.
\end{align*}
The final inequality holds due to the assumption that $S \geq 33 \implies S'\geq 32$.
\end{proof}




\begin{lem}[Local Fano's inequality {\cite[Proposition 15.12, Equation 15.34]{wainwright_high-dimensional_2019}}] 
\label{lem:fano}
Let $\mathcal{P}$ be a class of distributions with parameter space $\Theta$, and let $\{\P_1,\dots,\P_N\}\subset \mathcal{P}$.
Letting $\theta(\P) \in\Theta$ denote the parameters of $\P$,
define $\delta = \min_{j\neq k} \| \theta(\P_j) - \theta(\P_k) \|_1$.
For any estimator $\hat{\theta}$, we have
\[
\sup_{\P\in\mathcal{P}} \underset{\mathcal{D}\sim\P}{\mathbb{E}}\left[ \left\| \hat{\theta}(\mathcal{D}) - \theta(\P) \right\|_1 \right]
\geq
\frac{\delta}{2} \left( 1 - \frac{\max_{j,k} \textnormal{KL}(\P_j \,\|\, \P_k) + \log 2}{\log N} \right)
.\]
%\gzcomment{cite Wainwright high dimensional statistics Proposition 15.12 + Equation 15.34} \mzcomment{\cite[Proposition 15.12, Equation 15.34]{wainwright_high-dimensional_2019}}
\end{lem}

\begin{lem} \label{lem:bernoulli_kl}
For any $p,q\in\left(0,\frac{1}{2}\right]$ satisfying $p<q$, we have
\[
\textnormal{KL}\left(\textnormal{Ber}(p) \,\|\, \textnormal{Ber}(q)\right)
\leq
\textnormal{KL}\left(\textnormal{Ber}(q) \,\|\, \textnormal{Ber}(p)\right)
\leq
\frac{(p-q)^2}{p(1-p)}
,\]
which implies that
\[
\textnormal{KL}\left(\textnormal{Ber}(p) \,\|\, \textnormal{Ber}(q)\right)
+
\textnormal{KL}\left(\textnormal{Ber}(q) \,\|\, \textnormal{Ber}(p)\right)
\leq
\frac{2(p-q)^2}{p(1-p)}
.\]
\end{lem}
\begin{proof}
By Lemma 10 in \cite{li_settling_2023}, we have
\[
\text{KL}\left(\text{Ber}(p') \,\|\, \text{Ber}(q')\right)
\leq \text{KL}\left(\text{Ber}(q') \,\|\, \text{Ber}(p')\right)
\leq \frac{\left( p'-q' \right)^2}{p'(1-p')}
\]
for any $p',q'\in \left[\frac{1}{2},1\right)$ satisfying $p' > q'$.
The desired result follows immediately by taking $p'=1-p$ and  $q'=1-q$, along with the observation that $\text{KL}\left(\text{Ber}(1-p) \,\|\, \text{Ber}(1-q)\right) = \text{KL}\left(\text{Ber}(p) \,\|\, \text{Ber}(q)\right)$.
\end{proof}

