%\mzcomment{\cite{simic_global_2008}}
\begin{lem}[Theorem 1 in \cite{simic_global_2008}] \label{lem:reverse_jensen}
Let $I = [a,b]$ be a closed interval with $a,b\in\mathbb{R}, a<b$.
For some $n\in \mathbb{Z}^+$, let $x_1,\dots,x_n \in I$, and let $p_1,\dots,p_n>0$ satisfy $\sum_{i=1}^n p_i = 1$.
If $f:[a,b]\to\mathbb{R}$ is convex, then
\[
\sum_{i=1}^n p_i f(x_i) \leq f\left( \sum_{i=1}^n p_i x_i \right) + f(a) + f(b) - 2f\left( \frac{a+b}{2} \right)
.\]
\end{lem}

\begin{lem} \label{lem:recurrent_lb_gain_computation}
Suppose the underlying MDP is $(P_\theta, r)$.
Let $\pi$ be a stationary policy such that for each $s\neq 0$, if the current state is $s$ then the probability of transiting to state 0 after taking action according to $\pi$ is $\kappa_s$.
Then
\[
\rho_\theta^\pi = \frac{\frac{q}{S'}\sum_{s=1}^{S'} \frac{1}{\kappa_s}}{1 + \frac{q}{S'}\sum_{s=1}^{S'} \frac{1}{\kappa_s}}
.\] 	
\end{lem}
\begin{proof}
We first solve for $\mu_\theta^\pi(0)$ by considering the balance equations for the MDP  $(P_\theta, r)$.
For each $s\neq 0$, we have
\[
\mu_\theta^\pi(s) = \frac{q}{S'} \mu_\theta^\pi(0) + (1-\kappa_s) \mu_\theta^\pi(s)
.\] 
Rearranging gives us
\[
\mu_\theta^\pi(s) = \frac{q}{S'}\mu_\theta^\pi(0) \frac{1}{\kappa_s}
.\] 
Since $\sum_{s=0}^{S'} \mu_\theta^\pi(s) = 1$, we have
\[
\mu_\theta^\pi(0) 
= 1 - \sum_{s=1}^{S'} \mu_\theta^\pi(s)
= 1 - \mu_\theta^\pi(0)\frac{q}{S'}\sum_{s=1}^{S'} \frac{1}{\kappa_s}
.\] 
We then solve for $\mu_\theta^\pi(0)$ to obtain
\[
\mu_\theta^\pi(0) = \frac{1}{1 + \frac{q}{S'}\sum_{s=1}^{S'} \frac{1}{\kappa_s}}
.\]
Since the reward is 0 in state 0 and 1 in all other states, we conclude that
\[
\rho^\pi_\theta = 1 - \mu_\theta^\pi(0) = \frac{\frac{q}{S'}\sum_{s=1}^{S'} \frac{1}{\kappa_s}}{1 + \frac{q}{S'} \sum_{s=1}^{S'} \frac{1}{\kappa_s}}
.\]
\end{proof}


\section{Deferred proofs and auxiliary lemmas}
\label{sec:deferred_proofs}

\subsection{Proof of Lemma \ref{lem:tope_monotonicity}}
\label{sec:tope_monotonicity_proof}
\begin{proof}[Proof of Lemma \ref{lem:tope_monotonicity}]
    Letting $V, V' \in \R^\S$ satisfy $V \geq V'$ elementwise, we seek to show that
    \begin{align*}
        \Tope(V) \geq \Tope(V').
    \end{align*}
    Since this is an elementwise bound, we can fix arbitrary $s \in \S, a \in \A$ and show that $ \Tope(V)(s,a) \geq \Tope(V')(s,a)$. From here on, since $s, a$ are fixed, we abbreviate $\beta(s,a) \in \R$ as $\beta$ for notational convenience.

    Consider the simpler function $\Mopm : \R^{\S} \to \R$ (which depends on our fixed $s, a$) defined as
    \begin{align*}
        \Mopm(V'') :=  \Phat_{sa} T_{\beta}( \Phat_{sa}, V'') -  \max \left \{ \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T_{\beta}( \Phat_{sa}, V'') \right]} ,  \beta \spannorm{T_{\beta}( \Phat_{sa}, V'')} \right \}
    \end{align*}
    for any $V'' \in \R^{\S}$.
    Note that
    \begin{align*}
        \Tope(V'')(s,a) &= r(s,a) +\gamma\max \left\{  \Phat_{sa} T_{\beta}( \Phat_{sa}, V'') - b(s,a, V''), \min_{s'}(V'')(s') \right \}\\ 
        &= r(s,a) + \gamma \max \left\{\Mopm(V'') - \frac{5}{\ntot}, \min_{s'}(V'')(s') \right\}.
    \end{align*}
    Therefore, if we could show that
    \begin{align}
        \Mopm(V) \geq \Mopm(V'), \label{eq:mopm_monotonicity_key}
    \end{align}
    then since clearly $V \geq V'$ implies $\min_{s'}(V)(s') \geq \min_{s'}(V')(s')$, we could immediately conclude that
    \begin{align*}
        \Tope(V)(s,a)
        &= r(s,a) + \gamma \max \left\{\Mopm(V) - \frac{5}{\ntot}, \min_{s'}(V)(s') \right\} \\
        &\geq r(s,a) + \gamma \max \left\{\Mopm(V') - \frac{5}{\ntot}, \min_{s'}(V')(s') \right\} \\
        &= \Tope(V')(s,a)
    \end{align*}
    as desired.

    Thus we now focus on showing~\eqref{eq:mopm_monotonicity_key}. 
    First we can quickly handle the case that $\beta > 1$, since in this case for any $V'' \in \R^\S$ we have $T_{\beta}( \Phat_{sa}, V'') = \left(\min_{s '} V''(s')\right) \one$, and then
    \begin{align*}
        \Mopm(V) &= \Phat_{sa} T_{\beta}( \Phat_{sa}, V) -  \max \left \{ \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T_{\beta}( \Phat_{sa}, V) \right]} ,  \beta \spannorm{T_{\beta}( \Phat_{sa}, V)} \right \} \\
        &= \left(\min_{s '} V(s')\right)  \Phat_{sa} \one - 0 = \min_{s '} V(s') \\
        &\geq \min_{s '} V'(s') = \left(\min_{s '} V'(s')\right)  \Phat_{sa} \one - 0 \\
        &= \Phat_{sa} T_{\beta}( \Phat_{sa}, V') -  \max \left \{ \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T_{\beta}( \Phat_{sa}, V') \right]} ,  \beta \spannorm{T_{\beta}( \Phat_{sa}, V')} \right \} \\
        &= \Mopm(V'),
    \end{align*}
    confirming~\eqref{eq:mopm_monotonicity_key}. Now we can focus on the case that $\beta \leq 1$.

    The fact that $\beta \leq 1$ means that the following expression for $T_\beta$ holds: for any $s' \in \S$ and $V'' \in \R^\S$, we have
    \begin{align*}
        T_\beta(\Phat_{sa}, V'')(s') = \min \left\{ V''(s') , Q_\beta(\Phat_{sa}, V'')\right\}
    \end{align*}
    where $Q_\beta(\Phat_{sa}, V'') = \sup \{V''(x) : x \in \S, \sum_{x' \in \S : V(x') \geq V(x)} \Phat_{sa}(x') \geq \beta \}$ is the $1 - \beta$ quantile of $V''$ with respect to $\Phat_{sa}$ 
    (in words, we choose the largest $V''(x)$ such that $\Phat_{sa}$ places probability at least $\beta$ on states $x'$ with $V''(x') \geq V''(x)$). We will make use of the function $Q_\beta$ shortly.
    We also make the useful definitions
    \begin{align*}
        \Mopsp(V) &:=  \Phat_{sa} T_{\beta}( \Phat_{sa}, V) -   \beta \spannorm{T_{\beta}( \Phat_{sa}, V)}  \\
        \Mopvar(V) &:=  \Phat_{sa} T_{\beta}( \Phat_{sa}, V) -   \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T_{\beta}( \Phat_{sa}, V) \right]} 
    \end{align*}
    so that we can decompose $\Mopm$ as $\Mopm(V) = \min \left\{\Mopsp(V), \Mopvar(V) \right\}$.
    To show~\eqref{eq:mopm_monotonicity_key}, it suffices to show that this holds when $V$ and $V'$ differ in only one coordinate, since then we could decompose $V = V' + \sum_{s' \in \S} e_{s'} e_{s'}^\top (V - V')$ and apply the inequalities $\Mopm\left(V' + \sum_{{s'} = 1}^{k-1} e_{s'} e_{s'}^\top (V - V') \right) \leq \Mopm\left(V' + \sum_{{s'} = 1}^{k} e_{s'} e_{s'}^\top (V - V') \right)$ for each $k = 1, \dots, S$.
    Therefore we fix one state $x \in \S$ and try to show $\Mopm(V)$ is montonically non-decreasing as $V(x)$ increases (with the other entries of $V$ held constant). We will show this by using Lemma \ref{lem:analysis_fact_monotonic}, which says that if a univariate function is continuous and at all but a finite number of points has a non-negative right derivative, then it must be non-decreasing.

First we justify that $\Mopm$ is continuous. Since we have decomposed $\Mopm$ as the composition of many continuous functions, it suffices to check that $Q_\beta(\Phat_{sa}, V)$ is a continuous function of $V(x)$. This follows immediately from Lemma \ref{lem:quantile_continuity}, which shows $1$-Lipschitzness. (We remark that the $1-\beta$ quantile is well-known to be discontinuous in $\beta$, a fact which is irrelevant here since $\beta$ is fixed and we instead vary $V(x)$.)

We will now compute the right derivative at all values of $V(x)$ such that $V(x)$ is not equal to $V(s')$ for some other $s' \in \S$ with $s' \neq x$ (which is a finite set). 
We define some new notation for this purpose. With respect to this fixed value of $V(x)$, let $\S_{>} = \{s' \in \S : V(s') > V(x)\}$ and $\S_{<} = \{s' \in \S : V(s') < V(x)\}$. Define a neighborhood of $V(x)$, the open interval $U := (\max_{s' \in \S_{<}} V(s'),   \min_{s' \in \S_{>}} V(s'))$. Let $V' \in \R^\S$ have $V'(s')=V(s')$ for all $s'\neq x$, and we vary $V'(x)$ within the neighborhood $U$ of $V(x)$ in order to compute the (full/two-sided) derivatives $\frac{d \Mopsp(V')}{d V'(x)}\Big|_{V'(x) = V(x)}$ and $\frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)}$. Once we have computed these two derivatives, we will be able to compute the right derivative of $\Mopm(V')$, since if both $\Mopsp(V')$ and $\Mopvar(V')$ are differentiable at a point $V(x)$, then by Lemma \ref{lem:analysis_fact_min} the right derivative of $\Mopm(V')$ satisfies
\begin{align}
    \frac{d \Mopm(V')}{d V'(x)}\Big|_{V'(x) = V(x)^+} &= \frac{d }{d V'(x)}\Big|_{V'(x) = V(x)^+} \left( \min\left\{  \Mopsp(V'), \Mopvar(V') \right \}\right) \nonumber \\
    &= \begin{cases}
        \frac{d \Mopsp(V')}{d V'(x)}\Big|_{V'(x) = V(x)} & \Mopsp(V) < \Mopvar(V) \\
        \frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)} & \Mopsp(V) > \Mopvar(V) \\
        \min \left \{ \frac{d \Mopsp(V')}{d V'(x)}\Big|_{V'(x) = V(x)}, \frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)}\right \} & \Mopsp(V) = \Mopvar(V)
    \end{cases}. \label{eq:right_derivative_cases_Mop}
\end{align}

To compute the derivatives of $\Mopsp(V')$ and $\Mopvar(V')$, we also analyze the functions $Q_\beta(\Phat_{sa}, V')$ and $T_\beta(\Phat_{sa}, V')$ on the set $U$ (all considered as functions of $V'(x)$). For any set $\S' \subseteq \S$, let $\Phat_{sa}(\S') = \sum_{s' \in \S'}\Phat_{sa}(s')$. We define three possible cases depending on the (fixed) state $x$:
\begin{gather}
    \beta \leq \Phat_{sa}(\S_{>})  \label{eq:deriv_case_1}\\
    \Phat_{sa}(\S_{>}) < \beta \leq \Phat_{sa}(\S_{>}) + \Phat_{sa}(x) \label{eq:deriv_case_2}\\
    \Phat_{sa}(\S_{>}) + \Phat_{sa}(x) < \beta .\label{eq:deriv_case_3}
\end{gather}
\begin{enumerate}
    \item In case~\eqref{eq:deriv_case_1}, we have $Q_\beta(\Phat_{sa}, V') = Q_\beta(\Phat_{sa}, V)$ on the entire interval $U$ and also that for any $V'(x)\in U$, $Q_\beta(\Phat_{sa}, V) > V'(x)$ (since the $(1-\beta)$-percentile is achieved at some state $s' \in \S_{>}$), so $T_\beta(\Phat_{sa}, V')(x) = V'(x)$ and $T_\beta(\Phat_{sa}, V')(s') = T_\beta(\Phat_{sa}, V)(s')$ for all $s' \neq x$. Therefore
    \begin{align*}
        \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} &= \begin{cases}
            1 & s' = x \\
            0 & \text{otherwise}
        \end{cases}
    \end{align*}
    and
    \begin{align*}
        \frac{d \Mopsp(V')}{dV'(x)}\bigg|_{V'(x)=V(x)} 
        &=\frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta \spannorm{T_\beta(\Phat_{sa}, V')} \right) \\
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta Q_\beta(\Phat_{sa}, V') + \beta \min_{s'}V'(s') \right) \\
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta Q_\beta(\Phat_{sa}, V) + \beta \min_{s'}V'(s') \right) \\
        &= \Phat_{sa}(x) + \beta \begin{cases}
            1 & \S_{<} = \emptyset \\
            0 & \text{otherwise}
        \end{cases} \\
        & \geq \Phat_{sa}(x) \geq 0.
    \end{align*}

     \item In case~\eqref{eq:deriv_case_2}, we have $Q_\beta(\Phat_{sa}, V') = V'(x)$ on the entire interval $U$. Thus $T_\beta(\Phat_{sa}, V') (s') = V'(x)$ if $s' \in \S_{>} \cup \{x\}$, and $T_\beta(\Phat_{sa}, V') (s') = V'(s') = V(s')$ for $s' \in S_{<}$. Thus
     \begin{align*}
        \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} &= \begin{cases}
            1 & s' \in \S_{>} \cup \{x\} \\
            0 & \text{otherwise}
        \end{cases}
    \end{align*}
    and
    \begin{align*}
        \frac{d \Mopsp(V')}{dV'(x)}\bigg|_{V'(x)=V(x)} 
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta \spannorm{T_\beta(\Phat_{sa}, V')} \right) \\
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta Q_\beta(\Phat_{sa}, V') + \beta \min_{s'}V'(s') \right) \\
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta V'(x) + \beta \min_{s'}V'(s') \right) \\
        &= \Phat_{sa}(\S_{>} \cup \{x\}) -\beta + \beta \begin{cases}
            1 & \S_{<} = \emptyset \\
            0 & \text{otherwise}
        \end{cases} \\
        & \geq \Phat_{sa}(\S_{>} \cup \{x\}) -\beta \geq 0.
    \end{align*}
    \item In case~\eqref{eq:deriv_case_3}, we have $Q_\beta(\Phat_{sa}, V') = Q_\beta(\Phat_{sa}, V)$ and also that $T_\beta(\Phat_{sa}, V')(x) = Q_\beta(\Phat_{sa}, V) < V'(x)$ (since $V'(x) < Q_\beta(\Phat_{sa}, V)$ in this case), so $T_\beta(\Phat_{sa}, V') = T_\beta(\Phat_{sa}, V)$ on the interval $U$. Also $\min_{s'} V'(s') < V'(x)$ on $U$, so $\min_{s'} V'(s') = \min_{s'} V(s')$ on $U$. Thus
    \begin{align*}
        \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} &= 0
    \end{align*}
    for all $s' \in \S$, and
    \begin{align*}
        \frac{d \Mopsp(V')}{dV'(x)}\bigg|_{V'(x)=V(x)} 
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V') - \beta Q_\beta(\Phat_{sa}, V') + \beta \min_{s'}V'(s') \right) \\
        &= \frac{d }{dV'(x)}\bigg|_{V'(x)=V(x)} \left( \Phat_{sa} T_\beta(\Phat_{sa}, V) -  \beta Q_\beta(\Phat_{sa}, V) + \beta \min_{s'}V(s') \right) \\
        &= 0.
    \end{align*}
\end{enumerate}
Next we calculate $ \frac{d \Mopvar(V')}{dV'(x)}\bigg|_{V'(x)=V(x)}$. First, letting $T \in \R^{\S}$, if $\Var_{\Phat_{sa}} \left[ T \right] \neq 0$ then (recalling $\Phat_{sa}$ is a row vector so $\Phat_{sa}^\top$ is a column vector)
\begin{align}
    \nabla_T \sqrt{\Var_{\Phat_{sa}} \left[ T \right]} &= \frac{1}{2} \frac{1}{ \sqrt{\Var_{\Phat_{sa}} \left[ T \right]}} \nabla_T \left( \Phat T^{\circ 2} - (\Phat T)^{\circ 2} \right) \nonumber\\
    &= \frac{1}{ \sqrt{\Var_{\Phat_{sa}} \left[ T \right]}} \left(  \Phat_{sa}^\top \circ T -  (\Phat_{sa} T) \Phat_{sa}^\top \right) \nonumber \\
    &= \frac{1}{ \sqrt{\Var_{\Phat_{sa}} \left[ T \right]}} \Phat_{sa}^\top \circ \left(  T -  (\Phat_{sa} T) \one  \right) \nonumber \\
    &\leq \frac{\spannorm{T}}{ \sqrt{\Var_{\Phat_{sa}} \left[ T \right]}} \Phat_{sa}^\top \label{eq:var_deriv_bound}
\end{align}
where the final inequality is elementwise and uses the fact that for any $s'$, $T(s') - \Phat_{sa} T \leq \max_{s''} T(s'') - \min_{s''} T(s'') = \spannorm{T}$. Now we will combine this calculation with the chain rule to lower bound $\frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)}$. Note that in light of~\eqref{eq:right_derivative_cases_Mop}, we only need to bound $\frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)}$ when $\Mopsp(V) > \Mopvar(V)$ or equivalently when our fixed value of $V(x)$ satisfies
\begin{align}
    \sqrt{\Var_{\Phat_{sa}} \left[ T_\beta(\Phat_{sa}, V) \right]} > \sqrt{\beta}\spannorm{T_\beta(\Phat_{sa}, V)}. \label{eq:condition_for_Mopvar}
\end{align}
Since we have already excluded the finite set of values of $V(x)$ where $V(x)$ is equal to $V(s')$ for some other state $s' \neq x$, the only way for $\Var_{\Phat_{sa}} \left[ T_\beta(\Phat_{sa}, V) \right] = 0$ is if $\Phat_{sa}(x) = 1$, but in that case we have $\spannorm{T_\beta(\Phat_{sa}, V)} = 0$ which contradicts~\eqref{eq:condition_for_Mopvar}. Therefore we can calculate that if $V(x)$ satisfies~\eqref{eq:condition_for_Mopvar}, we have
\begin{align*}
    \frac{d \Mopvar(V')}{d V'(x)}\Big|_{V'(x) = V(x)} &= \frac{d }{d V'(x)}\Big|_{V'(x) = V(x)} \left( \Phat_{sa} T_{\beta}( \Phat_{sa}, V) -   \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T_{\beta}( \Phat_{sa}, V) \right]} \right) \\
    &= \sum_{s' \in \S}\left( \frac{\partial }{\partial T(s')}\Big|_{T(s') = T_\beta(\Phat_{sa}, V)(s')}  \left(\Phat_{sa} T -   \sqrt{\beta  \Var_{\Phat_{sa}} \left[ T \right]} \right) \right) \cdot  \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} \\
    & = \sum_{s' \in \S}\left(   \Phat_{sa}(s') -   \sqrt{\beta} \frac{\partial \sqrt{  \Var_{\Phat_{sa}} \left[ T \right]}}{\partial T(s')}\Big|_{T(s') = T_\beta(\Phat_{sa}, V)(s')}  \right) \cdot  \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} \\
    & \geq  \sum_{s' \in \S}\left(   \Phat_{sa}(s') -   \sqrt{\beta} \frac{\spannorm{T_\beta(\Phat_{sa}, V)}}{\sqrt{\Var_{\Phat_{sa}}\left[ T_\beta(\Phat_{sa}, V)\right]  }} \Phat_{sa}(s') \right) \cdot  \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} \\
    & > \sum_{s' \in \S}\left(   \Phat_{sa}(s') -   \Phat_{sa}(s') \right) \cdot  \frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} \\
    &= 0
\end{align*}
where the first inequality step is using the fact that $\frac{d T_\beta(\Phat_{sa}, V' )(s')}{d V'(x)}\bigg|_{V'(x)=V(x)} \geq 0$ for all $s'$ (verified above in all three cases) and inequality~\eqref{eq:var_deriv_bound}, and the second inequality step uses~\eqref{eq:condition_for_Mopvar}.
\end{proof}

\subsection{Auxiliary lemmas}

\begin{lem} \label{lem:analysis_fact_monotonic}
If $f:\R\to\R$ is a continuous function that has a nonnegative right derivative for all but finitely many points, then $f$ is monotonically non-decreasing.
\end{lem}

\begin{proof}
We make the following claim:
for $a,b\in\R$ with $a<b$, if $f:[a,b]\to\R$ is continuous on $[a,b]$ and has a nonnegative right derivative on $(a,b)$, then $f$ is monotonically non-decreasing on $[a,b]$.

We first prove the lemma assuming that the claim holds.
Let $f:\R\to\R$ be a continuous function that has a nonnegative right derivative for all but finitely many points.
Let $x,y\in\R$ satisfy $x<y$, and denote by $a_1,\dots,a_{n-1}$ the points in $(x,y)$ where $f$ either is not right-differentiable or has negative right derivative.
Also denote $a_0 = x$ and $a_n = y$.
By the claim, $f$ is monotonically increasing on $[a_{i-1},a_i]$ for each $i=1,\dots,n$.
Hence $f(x)=f(a_0)\leq f(a_1) \leq \dots \leq f(a_n) = f(y)$.
Since $x$ and $y$ were arbitrary, we conclude that $f$ is monotonically increasing.

It remains to prove the claim.
Let $a,b\in\R$ with $a<b$, and let $f:[a,b]\to\R$ be continuous on $[a,b]$ with a nonnegative right derivative on $(a,b)$.
Suppose towards a contradiction that there exist $x,y\in[a,b]$ such that $x<y$ and $f(x) > f(y)$.
Since $f$ is continuous, we can assume that $x>a$ (if $x=a$ we have $x+\delta < y$ and $f(x+\delta) > f(y)$ for sufficiently small $\delta>0$).

Now, set $r:=\frac{f(y)-f(x)}{y-x}<0$ and
\[
z:= \inf\left\{ t\in(x,y] \,\Big|\, \frac{f(t)-f(x)}{t-x} < \frac{r}{2} \right\}
.\]

Consider the case where $z=x$.
$f$ has a nonnegative right derivative at $x$, so there exists $w\in (x,y]$ such that $\frac{f(t)-f(x)}{t-x} > \frac{r}{2}$ for all $t\in (x,w]$.
However, this implies a contradiction:
\[
z = \inf\left\{ t\in(x,y] \,\Big|\, \frac{f(t)-f(x)}{t-x} < \frac{r}{2} \right\} \geq w > x = z
.\]

We next consider the case where $z > x$.
Note that by continuity of $f$, the function $g(t):=\frac{f(t)-f(x)}{t-x}$ is continuous on $(x,y]$.
It follows that $g(z) = \frac{f(z)-f(x)}{z-x} = \frac{r}{2}$.
Indeed, if we had $g(z) > \frac{r}{2}$, then by continuity of $g$ there would exist $\delta>0$ such that $g(t) > \frac{r}{2}$ for $t\in[z,z+\delta]$, which would imply that $z \geq z+\delta$.
And by a similar argument, $g(z) < \frac{r}{2}$ would imply $z \leq z-\delta$.

At $z$ the right-derivative is nonnegative, so there exists $w\in(z,y]$ such that $\frac{f(t)-f(z)}{t-z} > \frac{r}{2}$ for all $t\in(z,w]$.
Consequently, for all $t\in(z,w]$, we have
\[
\frac{f(t)-f(x)}{t-x}
= \frac{1}{t-x}(f(t) - f(z) + f(z) - f(x))
> \frac{1}{t-x}\left(\frac{r}{2}(t-z) + (z-x) \right)
= \frac{r}{2}
,\]
which implies the following contradiction:
\[
z = \inf\left\{ t\in(x,y] \,\Big|\, \frac{f(t)-f(x)}{t-x} < \frac{r}{2} \right\} \geq w > z
.\]

\end{proof}

\begin{lem} \label{lem:analysis_fact_min}
Let $f,g:\R\to\R$ be differentiable at some $x\in\R$, and suppose $f(x) = g(x)$.
Then $\phi:\R\to\R$ defined by $\phi(t) = \min\{f(t),g(t)\}$ is right-differentiable at $x$, and its right derivative satisfies $\phi'_+(x) = \min\{f'(x), g'(x)\}$.
\end{lem}

\begin{proof}
We first consider the case where $f'(x) < g'(x)$.
Since $\lim_{h\to0} \frac{f(x+h)-f(x)}{h} < \lim_{h\to 0} \frac{g(x+h) - g(x)}{h}$, there exists some $\delta > 0$ such that $\frac{f(x+h)-f(x)}{h} < \frac{g(x+h) - g(x)}{h}$ for all $h\in(0,\delta)$.
Subsequently, since $f(x) = g(x)$, we have $f(x+h) < g(x+h)$ for all $h \in (0,\delta)$.
It follows that $\phi(x+h) = f(x+h)$ for all $h\in(0,\delta)$, and thus
\[
\lim_{h\to 0^+} \frac{\phi(x+h) - \phi(x)}{h}
=
\lim_{h\to 0^+} \frac{f(x+h) - f(x)}{h}
=
f'(x)
=
\min \{f'(x), g'(x)\}
.\]

Next, the case where $f'(x) > g'(x)$ is identical to the previous case except we swap the roles of $f$ and $g$.

Finally, we consider the case where $f'(x) = g'(x)$.
Here we can even show that $\phi$ is differentiable at $x$.
Let $\{h_n\}_{n\in\N}$ be a sequence such that $h_n\to 0$.
To show that $\frac{\phi(x+h_n) - \phi(x)}{h_n} \to f'(x)$, fix $\varepsilon > 0$.
Since $\frac{f(x+h_n) - f(x)}{h_n}\to f'(x)$ and $\frac{g(x+h_n) - g(x)}{h_n} \to g'(x)$, there exist $N_1, N_2\in\N$ such that
\[
n \geq N_1 \implies \left| \frac{f(x+h_n) - f(x)}{h_n} - f'(x) \right| \leq \varepsilon
\]
and
\[
n \geq N_2 \implies \left| \frac{g(x+h_n) - g(x)}{h_n} - g'(x) \right| \leq \varepsilon
.\]
Taking $N = \max\{N_1,N_2\}$, we have for all $n\geq \N$,
\begin{align*}
&\left| \frac{\phi(x+h_n) - \phi(x)}{h_n} - f'(x)\right| \\
&\qquad\leq \max \left\{ \left| \frac{f(x+h_n) - f(x)}{h_n} - f'(x) \right| , \left| \frac{g(x+h_n) - g(x)}{h_n} - g'(x) \right| \right\} \\
&\qquad\leq \max\{\varepsilon, \varepsilon\} = \varepsilon,
\end{align*}
where the first inequality holds due to $f(x)=g(x), f'(x)=g'(x)$, and the fact that for each $n$, either $\phi(x+h_n)=f(x+h_n)$ or $\phi(x+h_n) = g(x+h_n)$.
Thus, we have that $\frac{\phi(x+h_n) - \phi(x)}{h_n} \to f'(x)$.
Since the sequence $\{h_n\}_{n\in\N}$ was arbitrary, we conclude that
\[
\phi'(x) = \lim_{h\to 0} \frac{\phi(x+h) - \phi(x)}{h} = f'(x) = \min\{ f'(x), g'(x) \}
.\]
\end{proof}

\begin{lem}
\label{lem:quantile_continuity}
    For any probability distribution $\mu \in \R^\S$ and any $\beta \in [0,1]$, the largest-$(1-\beta)$-quantile function
    \begin{align*}
        Q_\beta(\mu, V'') = \sup \{V''(x) : x \in \S, \sum_{x' \in \S : V(x') \geq V(x)} \mu(x') \geq \beta \}
    \end{align*}
    satisfies
    \begin{align*}
        \left|Q_\beta(\mu, V) - Q_\beta(\mu, V')\right| \leq \infnorm{V - V'}
    \end{align*}
    for any $V , V' \in\R^\S$.
\end{lem}
\begin{proof}
    First, we note that the definition of $Q_\beta$ can be written equivalently as
    \begin{align*}
        Q_\beta(\mu, V'') = \sup \left\{\min_{s' \in \S'} V''(s') : \S' \subseteq \S \text{ and } \sum_{s' \in \S'} \mu(s') \geq \beta \right\}.
    \end{align*}

    Without loss of generality we can assume that $Q_\beta(\mu, V) \geq Q_\beta(\mu, V')$, so it suffices to lower-bound $Q_\beta(\mu, V')$.
    By the definition of $Q_\beta(\mu, V)$ (and the fact that $\S$ is finite so the supremum within its definition is attained exactly), there exists some set $\S' \subseteq \S$ such that
    \begin{align*}
        Q_\beta(\mu, V) = \min_{s' \in \S'} V(s')
    \end{align*}
    and $\sum_{s' \in \S'} \mu(s') \geq \beta$.
    Therefore since
    \begin{align*}
        V'(s') \geq V(s') - \infnorm{V - V'} \geq Q_\beta(\mu, V) - \infnorm{V - V'}
    \end{align*}
    for all $s' \in \S'$, we have that
    \begin{align*}
        Q_\beta(\mu, V'') \geq Q_\beta(\mu, V) - \infnorm{V - V'}
    \end{align*}
    as desired.
\end{proof}

