			\\			
			\hline
			\cite{kar2013consensus,das2015distributed,Silm2020A,khan2010connectivity,chen2018internet} &	single &  local-$(A,C_i)$ &  $3m \times 1$   & $1$ & -
			\\			
			\hline 
			\cite{he2020secure} &	double & global-$(A,C)$ &  $m \times L$    & $L$ & $\checkmark$
			\\
			\hline 
			\cite{battilotti2021stability,olfati2007distributed} &	double & global-$(A,C)$ &  $m \times L$    & $L$ & -
			\\
