\subsection{Overview}
Firstly, we can easily obtain ULMs by applying various MU methods on a TRM. Given a ULM, \Cref{fig:framework} demonstrates the workflow to implement the proposed MRA framework, which consists of two alternative learning steps to obtain the RCM $\Tilde{\mathcal{M}}(\Theta_R)$.

\noindent\textbf{(1) Denosing Knowledge Distillation}: The ULM $\mathcal{M}(\Theta_U)$ serves as a noisy labeler on the prediction dataset $\mathcal{D}_{p}$ with some augmentation strategy, and the inferred pseudo labels with the augmented images are used to train STM $\Tilde{\mathcal{M}}(\Theta_S)$.

\noindent\textbf{(2) Confident Membership Recall}: Both ULM $\mathcal{M}(\Theta_U)$ and STM $\Tilde{\mathcal{M}}(\Theta_S)$ are to generate the prediction on $\mathcal{D}_{p}$, and the top-\textit{K} data samples with the highest probability of joint prediction, that is, the most confidently agreed pseudo labels for each class are selected to train STM $\Tilde{\mathcal{M}}(\Theta_S)$ and ULM $\mathcal{M}(\Theta_U)$ (optional for the open source case).

\subsection{Model Training and Unlearning}\label{sec:train_unlearn}
Given the training dataset $\mathcal{D}_{tr}=\mathcal{D}_f\cup\mathcal{D}_r$, we use $\mathcal{D}_{tr}$ to train the model $\mathcal{M}$, which results in the TRM $\mathcal{M}(\Theta_T)$ with the parameters $\Theta_T$. Then, we apply various SOTA MU methods on TRM $\mathcal{M}(\Theta_T)$, which leads to ULMs $\mathcal{M}(\Theta_U)$.

% \noindent\emph{\textbf{- Retrain ({RT}})} is the exact MU method by retraining model parameters from scratch over the remaining dataset $\mathcal{D}_{r}$.

% \noindent\emph{\textbf{- Fine Tuning ({FT})}} trains model $\mathcal{M}_t$ on $\mathcal{D}_{r}$ using a few training epochs. The rationale of FT initiates catastrophic forgetting ~\cite{Goodfellow2013AnEI}.

% \noindent\emph{\textbf{- Gradient Ascent ({GA}})} reverses the model training on $\mathcal{D}_{f}$ by moving $\Theta_t$ towards the direction of increasing loss.

% \noindent\emph{\textbf{- Fisher Forgetting ({FF})}} adopts additive Gaussian noise on $\Theta_t$. The noise has zero mean and covariance determined by the fourth root of the Fisher information matrix on $\mathcal{D}_{r}$.

% \noindent\emph{\textbf{- Influence Unlearning ({IU})}} leverages the influence function approach to characterize the change in $\Theta_t$ if a training point is removed from the training loss.

% \noindent\emph{\textbf{-Weight Prune ({WP})}} applies binary mask $\mathbf{m}$ over model parameters $\Theta_t$, where $\mathbf{m}$ is determined by one-shot magnitude pruning (OMP) ~\cite{Chen2021OnlyTO} on $\mathcal{D}_{f}$. 

\subsection{Implementation of MRA Framework}\label{sec:mra_scheme}
We implement the MRA framework with the following two alternative learning steps to obtain RCM $\Tilde{\mathcal{M}}(\Theta_R)$.


\subsubsection{(1) Denoising Knowledge Distillation}
A sophisticated MU method should only unlearn the influence of forgetting dataset $\mathcal{D}_f$ but retain the classification capability that is learned from the remaining dataset $\mathcal{D}_r$. As a result, the ULM $\mathcal{M}(\Theta_U)$ can serve as a noisy labeler to distill knowledge to the STM $\Tilde{\mathcal{M}}(\Theta_S)$ given the set of prediction images $\mathcal{X}_{p}$.
$\mathcal{M}(\Theta_U)$ is prone to mislabeling on $\mathcal{X}_{p}$ if it contains forgotten instances in $\mathcal{D}_f$. 
To avoid the input of original images that have been forgotten, we create augmented images by mixup \cite{zhang2018mixup} which is an effective regularization technique to deal with label noise \cite{carratino2022mixup}. Given an image $x_1\in\mathcal{X}_{p}$, we randomly sample another image $x_2$ from $\mathcal{X}_{p}$, and mix them as follows:
\begin{equation}
    \Tilde{x}=\beta_x \cdot x_1 + (1-\beta_x) \cdot  x_2  
    \label{eq:mixup_img}
\end{equation}
where $\beta_x \sim Beta(\alpha_x, \alpha_x)$ ($\alpha_x=0.2$ in this paper). Then, we take $\Tilde{x}$ as input to retrieve the soft pseudo label from ULM $\mathcal{M}(\Theta_U)$ and STM $\Tilde{\mathcal{M}}(\Theta_S)$:
\begin{gather}
    \Tilde{\mathbf{y}}_U=\mathcal{M}(\Tilde{x};\Theta_U),\quad
    \Tilde{\mathbf{y}}_S=\Tilde{\mathcal{M}}(\Tilde{x};\Theta_S)
    \label{eq:y_S}
\end{gather}
Then, we can obtain the mixed soft pseudo label:
\begin{equation}
    \Tilde{\mathbf{y}}_{US}=\beta_y \cdot \Tilde{\mathbf{y}}_U + (1-\beta_y) \cdot \Tilde{\mathbf{y}}_S  
    \label{eq:mixup_label}
\end{equation}
where $\beta_y=1$ is applied in the first warmup epoch (i.e. completely accept the knowledge from the teacher model) and $\beta_y \sim Beta(\alpha_y, \alpha_y)$ ($\alpha_y=0.75$ in this paper) for label denoising after the warmup stage. 
Following \Cref{eq:mixup_img,eq:y_S,eq:mixup_label}, we can obtain $\Tilde{\mathcal{Y}}_S=\{\Tilde{\mathbf{y}}_S\}$ and $\Tilde{\mathcal{Y}}_{US}=\{\Tilde{\mathbf{y}}_{US}\}$ over the augmented set $\Tilde{x}\in\Tilde{\mathcal{X}}_{p}$.
As a result, the parameters of STM $\Tilde{\mathcal{M}}(\Theta_S)$ can be updated by decreasing the mini-batch gradient in terms of minimizing cross-entropy (CE) loss.
\begin{equation}
   \Theta_S = \arg\min_{\Theta_S}{\text{CE}(\Tilde{\mathcal{Y}}_S,\Tilde{\mathcal{Y}}_{US})}
    \label{eq:theta_US}
\end{equation}

\subsubsection{(2) Confident Membership Recall}
After the above step, STM $\Tilde{\mathcal{M}}(\Theta_S)$ has been trained on the augmented dataset based on $\mathcal{X}_{p}$ with pseudo labels from the noisy labeler $\mathcal{M}(\Theta_U)$. Inspired by the LNL methods \cite{ALGAN2021106771}, we design a balanced class membership recall strategy based on the highest confidence agreements between $\mathcal{M}(\Theta_U)$ and $\Tilde{\mathcal{M}}(\Theta_S)$. More specifically, we first input $\mathcal{X}_{p}$ into both ULM $\mathcal{M}(\Theta_U)$ and STM $\Tilde{\mathcal{M}}(\Theta_S)$ to predict soft labels (that is, probability over each class):
\begin{gather}
	\mathbf{Y}_{p}^U=\mathcal{M}(\mathcal{X}_{p};\Theta_U),\quad
    \mathbf{Y}_{p}^S=\Tilde{\mathcal{M}}(\mathcal{X}_{p};\Theta_S)
	\label{eq:Y_p}
\end{gather}
where $\mathbf{Y}_{p}^U, \mathbf{Y}_{p}^U \in \mathbb{R}^{N \times C}$, $N=|\mathcal{X}_{p}|$ denotes the number of samples in $\mathcal{X}_{p}$ and $C$ denotes the number of classes. For each instance $x_i\in\mathcal{X}_{p}$, we apply Laplace smoothing on its soft label $\mathbf{y}_i^U=\mathbf{Y}_{p}^U[i,:]$ to avoid zero probability:
\begin{equation}
	\Tilde{\mathbf{y}}_i^U = \frac{\mathbf{y}_i^U + \gamma_l\cdot\mathbf{1}}{1+C\cdot\gamma_l}
    \label{eq:lap_smooth}
\end{equation}
As a result, we obtain the smoothed probability matrices $\Tilde{\mathbf{Y}}_{p}^U$ over $\mathcal{X}_{p}$. $\Tilde{\mathbf{Y}}_{p}^S$ can be obtained in the same way. Then, we have the joint probability $\Tilde{\mathbf{y}}_i$ on $x_i$:
\begin{equation}
\Tilde{\mathbf{y}}_i=\Tilde{\mathbf{y}}_i^U\odot\Tilde{\mathbf{y}}_i^S \quad
	 \text{for}~\Tilde{\mathbf{y}}_i^U \in \Tilde{\mathbf{Y}}_{p}^U, \Tilde{\mathbf{y}}_i^S \in \Tilde{\mathbf{Y}}_{p}^S
     \label{eq:joint_probs}
\end{equation}
For all $x_i\in\mathcal{X}_{p}$, we have $\Tilde{\mathbf{Y}}_{p} = \Tilde{\mathbf{Y}}_{p}^U \odot \Tilde{\mathbf{Y}}_{p}^S$ in the matrix form, where $\odot$ is the element-wise product. 
Given a class $c$, we have the joint probabilities $\mathbf{y}_c=\Tilde{\mathbf{Y}}_{p}[:,c]$ of all instances. A higher joint probability $y_i \in \mathbf{y}_c$ implies greater confidence in the teacher and student models that the instance $x_i$ should have the membership of the class $c$. 
Consequently, we apply a balanced strategy to select top-$K$ instances with the maximum joint probability for each class.
\begin{gather}\label{eq:D_conf}
    \mathcal{D}_{CF}=\{\mathcal{X}_{CF}, \mathcal{Y}_{CF}\}=\{(x_i, \Tilde{\mathbf{y}}_c)|y_i \in \text{top-}K(\mathbf{y}_c)\\
    \text{for}~ c \in \{1,\cdots,C\}\nonumber
\end{gather}
where $K=\lceil\tau\cdot N/C\rceil$, and $\Tilde{\mathbf{y}}_c = (1-\gamma_s)\cdot\mathbf{y}_c + \frac{\gamma_s}{K}\cdot\mathbf{1}$ denotes the smoothing of the label versus the hard label $c$ ($\mathbf{y}_c$ stands for the one-hot encoding of $c$) which can effectively mitigate label noise \cite{lukasik2020does}. Then, the STM $\Tilde{\mathcal{M}}(\Theta_S)$ is updated on $\mathcal{D}_{CF}$ to learn the confident memberships.
\begin{gather}
	\mathcal{Y}_S=\Tilde{\mathcal{M}}(\mathcal{X}_{CF};\Theta_S)\\
	\Theta_S = \arg\min_{\Theta_S}{\text{CE}(\mathcal{Y}_S, \mathcal{Y}_{CF})}
	\label{eq:theta_S}
\end{gather}
In the \textbf{open-source case}, the parameters of ULM $\mathcal{M}(\Theta_U)$ are also accessible, so we will construct $\mathcal{D}_{CF}$ to refine $\Theta_U$ by \Cref{eq:Y_p,eq:lap_smooth,eq:joint_probs,eq:D_conf} with the above updated STM $\Tilde{\mathcal{M}}(\Theta_S)$.
\begin{gather}
	\mathcal{Y}_U=\mathcal{M}(\mathcal{X}_{CF};\Theta_U)\\
	\Theta_U = \arg\min_{\Theta_U}{\text{CE}(\mathcal{Y}_U, \mathcal{Y}_{CF})}
	\label{eq:theta_U}
\end{gather}
As a result, it leads to an alternative improvement co-training process between the teacher $\mathcal{M}(\Theta_U)$ and the student $\Tilde{\mathcal{M}}(\Theta_S)$, which can more effectively recall class memberships thanks to the knowledge retained by $\mathcal{M}(\Theta_U)$.

\begin{algorithm}[t]
\caption{The Scheme of MRA}
\label{alg:mra}
\textbf{Input}: Prediction Set: $\mathcal{X}_p$, Number of Epochs: $K_E,K_D,K_R$
\textbf{Output}: Recalled Labels: $\hat{\mathcal{Y}}_p$
\begin{algorithmic}[1]
\FOR{e in \{1, $\cdots$, $K_E$\}}
    \STATE \textit{(1) Denoising Knowledge Distillation}
    \FOR{i in \{1, $\cdots$, $K_D$\}}
        \STATE $\Tilde{\mathcal{X}}_p,\Tilde{\mathcal{Y}}_{US}$ \COMMENT{Mixup augmentation by \Cref{eq:mixup_img,eq:y_S,eq:mixup_label}}
        \STATE $\Theta_S = \arg\min_{\Theta_S}{\text{CE}(\Tilde{\mathcal{Y}}_S,\Tilde{\mathcal{Y}}_{US})}$ \COMMENT{Update STM}
    \ENDFOR
    \STATE \textit{(2) Confident Membership Recall}
    \FOR{i in \{1, $\cdots$, $K_R$\}}
        \STATE $\mathcal{D}_{CF}$ \COMMENT{Confident agreements by \Cref{eq:Y_p,eq:lap_smooth,eq:joint_probs,eq:D_conf}}
        \STATE $\Theta_S = \arg\min_{\Theta_S}{\text{CE}(\mathcal{Y}_S, \mathcal{Y}_{CF})}$ \COMMENT{Update STM}
        \IF{$\mathcal{M}(\Theta_U)$ is trainable (\textbf{open-source case})}
            \STATE $\mathcal{D}_{CF}$  \COMMENT{Confident agreements by \Cref{eq:Y_p,eq:lap_smooth,eq:joint_probs,eq:D_conf}}
             \STATE $\Theta_U = \arg\min_{\Theta_U}{\text{CE}(\mathcal{Y}_U,\mathcal{Y}_{CF})}$\COMMENT{Update ULM}
        \ENDIF
    \ENDFOR
\ENDFOR
\RETURN $\hat{\mathcal{Y}}_p=\Tilde{\mathcal{M}}(\mathcal{X}_{p};\Theta_S)$  \COMMENT{Closed-source case}
\STATE \qquad$~~~~~\hat{\mathcal{Y}}_p=\mathcal{M}(\mathcal{X}_{p};\Theta_U)$  \COMMENT{Open-source case}
\end{algorithmic}
\end{algorithm}

In \Cref{alg:mra}, we concisely summarize the above MRA scheme. After MRA, the updated STM $\Tilde{\mathcal{M}}(\Theta_S)$ (in closed-source case) or ULM $\mathcal{M}(\Theta_U)$ (in open-source case) will serve as the RCM to predict the labels $\hat{\mathcal{Y}}_p$ of $\mathcal{X}_p$.

