}
Compute occupancy ratio: $\frac{\rho^E_{\text{tot}}(\bs, \ba)}{\rho^U_{\text{tot}}(\bs, \ba)} = \frac{c(\bs, \ba)}{1 - c(\bs, \ba)}$ based on updated $(\theta_c,\eta)$\;

% \tcc{2. Train MisoDICE Value Functions}
\For{\textit{a number of value function training steps}}{
    Train $(\theta_\nu, \phi)$ from Eq.~\ref{eq.valueobj} using the  occupancy ratio estimated above\;
}
Compute the weight $w^{\text{tot}}_{\pmb{\nu}^*}(\bs, \ba)$ using Eq.~\ref{v.2} w.r.t updated $(\theta_\nu, \phi)$\;
% \tcp*[f]{Ref: MisoDICE Sec 4.1 / Eq. (10)}

% \tcc{3. Train MisoDICE Local Policies via Weighted Behavior Cloning}
\For{\textit{a number of policy training steps}}{
    Update $\theta_\pi$ based on weighted BC in Eq.~\ref{eq.localBC} and the weight $w^{\text{tot}}_{\pmb{\nu}^*}(\bs, \ba)$\;
        % \tcp*[f]{Ref: MisoDICE Sec 4.4 / Eq. after (12)}
}

\Return{ local policies $\pi_i$ for $i = 1, \dots, n$}
