\title[Meta-solvers for nonlinear PDEs]{Automatic discovery of optimal meta-solvers for time-dependent nonlinear PDEs$^{\, *}$}

\author{Yougkyu Lee$^{\, 1}$}
\author{Shanqing Liu$^{\, 1}$}
