\section{Implementation details and further numerical results for solving incompressible Navier-Stokes equations}\label{app_ns}

In this section, we consider a vector-valued nonlinear equation, the incompressible Navier Stokes equation. Given domain $\Omega = [0,1]^3 \subseteq \R^{3}$, the incompressible Naiver Stokes equation is given by
\begin{equation}
\left\{\begin{split}
\rho \frac{\partial \mathbf{u}}{\partial t} + \rho (\mathbf{u} \cdot \nabla)\mathbf{u}&= -\nabla p + \mu \Delta \mathbf{u}, \,\,\, \text{ in } \Omega \times (0,1], \\
\nabla \cdot \mathbf{u} &= 0, \,\,\, \text{ in } \Omega \times (0,1], \\
\mathbf{u} &= \mathbf{u}_{0}, \text{ at } t=0, \\
\mathbf{u} &= \mathbf{u}_{D}, \text{ on } \partial\Omega \times (0,1],
\end{split}
\right.
\label{app:eqn:imcompressible-navier-stokes}
\end{equation}
where $\rho = \mu = 1$. 
In this case, the exact velocity $\mathbf{u}=(u_1, u_2, u_3)$ and the pressure $p$ of~\eqref{app:eqn:imcompressible-navier-stokes} are given by
\begin{align*}
    u_{1}(x, y, z, t) &= -a [e^{ax}\sin(ay+dz)+e^{az}\cos(ax+dy)]e^{-d^{2}t}, \\
    u_{2}(x, y, z, t) &= -a [e^{ay}\sin(az+dx)+e^{ax}\cos(ay+dz)]e^{-d^{2}t}, \\
    u_{3}(x, y, z, t) &= -a [e^{az}\sin(ax+dy)+e^{ay}\cos(az+dx)]e^{-d^{2}t}, \\
    p(x, y, z, t) &= -\frac{a^{2}}{2} [e^{2ax} + e^{2ay} + e^{2az} +  2 \sin(ax+dy)\cos(az+dx)e^{a(y+z)} \\
    &+ 2 \sin(ay+dz)\cos(ax+dy)]e^{a(z+x)} + 2 \sin(az+dx)\cos(ay+dz)]e^{a(x+y)}]e^{-2d^{2}t},
\end{align*}
where $a$ and $d$ are given. 

To solve \eqref{app:eqn:imcompressible-navier-stokes}, we employ the \textit{splitting method} instead of solving \textit{saddle point problem}.
We briefly describe the incremental pressure correction scheme~(IPCS).
\begin{subequations}

\begin{enumerate}
    \item Find $\mathbf{u}^{\ast}$ using IMEX:
    \begin{equation}
        \langle \rho\frac{\mathbf{u}^{\ast}-\mathbf{u}^{(n)}}{\Delta t}, \mathbf{v} \rangle  + AB_{3}(F, \mathbf{u}^{(n)}, \mathbf{u}^{(n-1)}, \mathbf{u}^{(n-2)}) + \langle \nabla p^{(n)} , \mathbf{v} \rangle + \langle \frac{\mu}{2} \nabla (\mathbf{u}^{(n)} + \mathbf{u}^{\ast}), \nabla \mathbf{v} \rangle = 0,
    \end{equation}
    where $F(\mathbf{u}) := \langle \rho (\mathbf{u} \cdot \nabla) \mathbf{u}, \mathbf{v} \rangle$.
    \item Find $p^{(n+1)}$ satisfying
    \begin{align}
        \langle \nabla p^{(n+1)}, \nabla q\rangle &= \langle \nabla p^{(n)}, \nabla q\rangle - \frac{\rho}{\Delta t}\langle \nabla \cdot \mathbf{u}^{\ast}, q\rangle, \\
        \frac{\partial p^{(n+1)}}{\partial n} &= 0.
    \end{align}
    This relation is derived from
    \begin{equation}
        \rho \frac{\mathbf{u}^{(n+1)}-\mathbf{u}^{\ast}}{\Delta t} + \nabla p^{(n+1)} - \nabla p^{(n)} = 0,
    \end{equation}
    where we use the condition $\nabla \cdot \mathbf{u}^{(n+1)}$.
    \item Find $\mathbf{u}^{(n+1)}$ satisfying
    \begin{equation}
        \rho \langle \mathbf{u}^{(n+1)}-\mathbf{u}^{\ast}, \mathbf{v} \rangle = -\Delta t \langle \nabla(p^{(n+1)}-p^{(n)}), \mathbf{v} \rangle.
    \end{equation}
\end{enumerate}

\end{subequations}
Moreover, we considered two different values of d. 
The implementation details are given in following: For training:
\begin{itemize}
    \item Case 1: $a_{i} \sim \mathcal{U}[\frac{\pi}{2}-0.1, \frac{\pi}{2}+0.1]$ and $d_{i} \sim \mathcal{U}[\frac{\pi}{4}-0.1, \frac{\pi}{4}+0.1]$.
    \item Case 2: $a_{i} \sim \mathcal{U}[{\pi}-0.1, {\pi}+0.1]$ and $d_{i} \sim \mathcal{U}[\frac{\pi}{8}-0.1, \frac{\pi}{8}+0.1]$.
    \item We sampled $3,000$ $(a_{i}, d_{i})$ pairs.
    \item Spatial mesh size: $\Delta x = \frac{1}{14}$.
    \item Time mesh size: $\Delta t = \frac{C  \Delta x}{\lVert \mathbf{u} \rVert}$, $C=0.7$, $\Delta t = \frac{1}{252}$.
    \item We randomly sampled $10$ time snapshots for each $(a_{i},d_{i})$ pair.
    \item Total number of training samples: $30,000$.
    \item Polynomial order for $\mathbf{u}$ and $p$ is $1$. 
\end{itemize}

For the test case:

\begin{itemize}
    \item Case 1: $a = \frac{\pi}{2}$ and $d=\frac{\pi}{4}$.
    \item Case 2: $a = {\pi}$ and $d=\frac{\pi}{8}$.
    \item Spatial mesh size: $\Delta x = \frac{1}{32}$.
    \item Time mesh size: $\Delta t = \frac{C  \Delta x}{\lVert \mathbf{u} \rVert}$, $C=0.7$, $\Delta t = \frac{1}{1215}$.
    \item We solved the equation in $\Omega \times [0, 1]$.
    \item Polynomial order for $\mathbf{u}$ and $p$ is $1$. 
\end{itemize}

\subsection{Identify all optimal meta-solvers in Pareto sense}

We implement the parametrized IMEX based meta-solvers. In particular, we consider $\NO= \{\text{DeepONet, U-DeepONet,}$ \ $ \text{KAN, JacobiKAN,  CheyKAN}\}$, in the choose of neural operators. 
For the classical Krylov methods, we consider $\kr = \{ \text{FGMRES, CG, BiCGStab} \}$. Moreover, for relaxation method we consider $\rela = \{\text{Jacobi, Gauss-Seidel, SOR, SSOR}\}$, and for the strategies of applying the relaxation method, we consider $S = \{\text{1-1-1, 3-1-3, 5-1-5, 7-1-7, 9-1-9}\}$. Moreover, we also implement the multi-grid techniques, where the levels of multi-grid is choose from $\{1,2,3\}$. 
As a results, we generate 900 different meta-solvers. 

For the performnace matrices, the evaluation is conducted in a eight-dimensional performance function $f = (f_1,\dots, f_8)$, where each dimension represents a particular performance criterion. In particular, $f_1$ is the computational time, $f_2$ is the relative error of velocity $\textbf{u}$,  $f_3$ is the relative error of pressure $\textbf{p}$, $f_4$ is the number of iterations, $f_5$ is the memory allocation, $f_6$ is the MACs, $f_7$ is the average MACs and $f_8$ is the training time, respectively. 

For $d=\frac{\pi}{4}$, there are 258 Pareto optimal solvers among 900. For $d=\frac{\pi}{8}$, there are 247 Pareto optimal solvers among 900. 
