\section{Implementation details and further numerical results for solving brittle fracture problem~(phase-field modeling)}\label{app-bf} 

\subsection{The model and implementation details}
Assume a domain $\Omega \subset \R^{2}$ is given.
The external boundary $\Gamma$ is decomposed into the Dirichlet boundary $\Gamma_{D}$ and Neumann boundary $\Gamma_{N}$, i.e., $\Gamma = \Gamma_{D} \cup \Gamma_{N}$.
Moreover, the Dirichlet boundary $\Gamma_{D}$ consists of a homogeneous boundary $\Gamma_{D,0}$ and non-homogeneous~(loading) boundary $\Gamma_{D,1}$. 
Let $\Omega_{c} \subset \Omega$ be a crack set.
Then, we consider the $n$-th loading step of the phase-field modeling of Brittle fracture.
The pair of solution spaces $\{V,Q\}$ is given by
\begin{align}
    V &= \{\mathbf{u} \in [H^{1}(\Omega)]^{d}\colon \mathbf{u}=0 \text{ on } \Gamma_{D,0}, \mathbf{u}=\mathbf{u}_{n} \text{ on } \Gamma_{D,1}\}, \\
    Q &= \{\alpha \in H^{1}(\Omega)\colon 0 \leq \alpha \leq 1, \alpha \geq \alpha_{n-1} \text{ in } \Omega\},
\end{align}
Then, the pair of solution $\{\mathbf{u}, \alpha\}$ is obtained by solving the following minimization problem:
\begin{equation}
\min_{\mathbf{u} \in V, \alpha \in Q} \mathcal{E}_{n}(\mathbf{u}, \alpha) := \mathcal{E}_{el} + \mathcal{E}_{d} - \mathcal{E}_{w} + \mathcal{E}_{irr},
\label{app:eqn:phase-field}
\end{equation}
where
\begin{equation}
\left\{\begin{split}
\mathcal{E}_{el}&=\int_{\Omega} \left(a(\alpha)\Psi^{+}(\varepsilon(\mathbf{u}))+\Psi^{-}(\varepsilon(\mathbf{u})\right)dx, \\
\mathcal{E}_{d}&=\frac{G_{c}}{c_{w}}\int_{\Omega} (\frac{w(\alpha)}{\ell}+\ell \vert \nabla \alpha Bro\vert^{2})dx, \\
\mathcal{E}_{w} &= \int_{\Omega} \mathbf{f}_{n} \cdot \mathbf{u} dx + \int_{\Gamma_{N}}\mathbf{t}_{n} \cdot \mathbf{u} ds, \\
\mathcal{E}_{irr} &= \frac{\gamma}{2}\int_{\Omega} \langle \alpha - \alpha_{n-1} \rangle_{-}^{2} dx.
\end{split}
\right.
\label{eqn:phase-field-def}
\end{equation}
Note that 
\begin{equation}
    \left\{ \begin{split}
        \varepsilon(\mathbf{u}) &= \frac{1}{2} \left[ \nabla \mathbf{u} + (\nabla \mathbf{u})^{T} \right], \\
        \lambda &= \frac{E \nu}{(1+\nu)(1-2\nu)}, \\
        \mu &= \frac{E}{2(1+\nu)}, \\
        \Psi^{+}(\varepsilon) &= \frac{1}{2} \kappa \langle \tr(\varepsilon)\rangle_{+}^{2} + 2\mu \mathbf{e}(\varepsilon) \cdot \mathbf{e}(\varepsilon), \\
        \kappa &= \lambda + \frac{2}{d}\mu,\\
        \mathbf{e}(\varepsilon) &= \varepsilon - \frac{\tr(\varepsilon)}{d}I, \\
        \Psi^{-}(\varepsilon) &= \frac{1}{2} \kappa \langle \tr(\varepsilon)\rangle_{-}^{2}, \\
        a(\alpha) &= (1 - k)(1 - \alpha)^{2} +k, \\
        w(\alpha) &= \begin{cases}
            \alpha, &\text{ AT1 model},\\
            \alpha^{2}, &\text{ AT2 model},\\
        \end{cases} \\
        c_{w} &= \begin{cases}
            \frac{8}{3}, &\text{ AT-1 model},\\
            2, &\text{ AT-2 model},\\
        \end{cases} \\
        \gamma &= \begin{cases}
            \frac{G_{c}}{\ell}\left(\frac{27}{64\tau^{2}}\right), &\text{ AT-1 model},\\
            \frac{G_{c}}{\ell}\left(\frac{1}{\tau^{2}}-1\right), &\text{ AT-2 model}.\\
        \end{cases} \\
    \end{split} \right.
\label{eqn:phase-field-parameter}
\end{equation}

In this experiment, we use the AT-2 model, $E=210.0$, $\nu =0.3$, $\ell = 0.01$, $G_{c}=2.7 \times 10^{-3}$, $k=10^{-8}$, $\tau=10^{-2}$, and $\gamma=2.7 \times 10^{3}$.


We also use the alternating minimization technique.
Let $\alpha^{(0)} = 0$.
For $n = 1, 2, \ldots$,
\begin{enumerate}
    \item Find $\mathbf{u}^{(n)} \in V$ satisfying
\begin{equation*}
    \frac{\partial \mathcal{E}_{n}}{\partial \mathbf{u}}(\mathbf{u}^{(n)}, \alpha^{(n-1)}) = 0,
\end{equation*}
where the symbol $\alpha^{(n-1)}$ denotes the previous damage.
\item After that, find $\alpha^{(n)} \in Q$ satisfying
\begin{equation*}
    \frac{\partial \mathcal{E}_{n}}{\partial \alpha}(\mathbf{u}^{(n)}, \alpha^{(n)}) = 0.
\end{equation*}
\item If $\Vert \alpha^{(n)} - \alpha^{(n-1)}\Vert_{\infty} < \varepsilon$, then $\mathbf{u}=\mathbf{u}^{(n)}$ and $\alpha=\alpha^{(n)}$. If not, $n \gets n+1$.
\end{enumerate}

For all local problems, we utilize the Newton-Raphson method. The implementation details are given in the following:

\subsubsection*{Common details}
\begin{itemize}
    \item The domain $\Omega$ is descretized by $6,252$ nodes with mesh size varying from $h_{min}=\frac{1}{500}$ to $h_{max}=\frac{1}{25}$.
    \item $\mathbf{f}_{n}=\mathbf{t}_{n}=0$.
    \item $\varepsilon=10^{-4}$ (Stop criteria for alternating minimization)
    \item Maximum number of iterations for the alternating minimization: $1000$.
    \item Maximum number of iterations for the Newton-Rapshon method: $1000$.
    \item Maximum number of iterations for the inner linearized problem: $2000$.
\end{itemize}
\subsubsection*{Training dataset}
\begin{itemize}
    \item We sampled $7$ pairs.
    \item Spatial mesh size for network: $\Delta x = \frac{1}{30}$
    \item Time step~(Quasi-static): $\Delta t = \frac{1}{50}$.
    \item $u_{T} \sim \mathcal{U}(0.001, 0.01)$, $\mathbf{u}_{n}=[0.0, u_{T}*n*\Delta t]$
    \item Total number of training/validation samples: $335/15$.
    \item Polynomial order for $\mathbf{u}$ and $\alpha$ is $1$. 
\end{itemize}

\subsubsection*{Test case 1}
\begin{itemize}
    \item The domain $\Omega$ is discretized by $6,252$ nodes with mesh size varying from $h_{min}=\frac{1}{500}$ to $h_{max}=\frac{1}{25}$.
    \item $u_{T}=0.006$, $\Delta t = \frac{1}{30}$ $\Rightarrow$ $\delta u_{T}= \frac{u_{T}}{\Delta T}=0.0002$.
\end{itemize}

\subsubsection*{Test case 2~(much more fine grid)}
\begin{itemize}
    \item The domain $\Omega$ is discretized by $37,949$ nodes with mesh size varying from $h_{min}=\frac{3}{2000}$ to $h_{max}=\frac{3}{100}$.
    \item $u_{T}=0.006$, $\Delta t = \frac{1}{30}$ $\Rightarrow$ $\delta u_{T}= \frac{u_{T}}{\Delta T}=0.0002$.
\end{itemize}

\subsubsection*{Modified approach}
\begin{itemize}
    \item Instead of using the penalty $\mathcal{E}_{irr}=\frac{\gamma}{2}\int_{\Omega}\langle \alpha - \alpha_{n-1} \rangle_{-}^{2}dx$, we use simple projection: we apply
    \begin{equation*}
        \displaystyle (\alpha_{n})_{j} \gets \max((\alpha_{n})_{j}, (\alpha_{n-1})_{j})
    \end{equation*}
    \item $u_{T}=0.007$, $\Delta t = \frac{1}{35}$ $\Rightarrow$ $\delta u_{T}= \frac{u_{T}}{\Delta T}=0.0002$.
\end{itemize}



