Here, we also briefly describe the Chebyshev semi-iterative method which can be used for smoother. Given a linear system $\mathbf{A}\mathbf{x} = \mathbf{b}$, the classical preconditioned Richardson iteration is given by
\begin{align}
\begin{cases}
    \mathbf{r}^{(i)} &= \mathbf{b} - \mathbf{A}\mathbf{x}^{(i)},\\
    \mathbf{x}^{(i+1)} &= \mathbf{x}^{(i)} + \mathbf{M}^{-1}(\mathbf{r}^{(i)}),
\end{cases}
\end{align}
where $\mathbf{M}^{-1}$ denotes a preconditioner.
Note that the classical relaxation methods can be represented by 
\begin{align}
    \mathbf{M} = \begin{cases}
        \mathbf{D}, &\text{Jacobi,}\\
        \mathbf{D}+\mathbf{L}, &\text{Gauss-Seidel,}\\
        \frac{1}{\omega} \mathbf{D}+\mathbf{L}, &\text{SOR,}\\
        \frac{1}{\omega (2- \omega)} (\mathbf{D} + \omega \mathbf{L})\mathbf{D}^{-1}(\mathbf{D} + \omega \mathbf{U}), &\text{SSOR,}\\
    \end{cases}
\end{align}
where $\mathbf{A} = \mathbf{D} + \mathbf{L} + \mathbf{U}$.

On the other hand, let us assume that $\lambda_{min}, \lambda_{max}$ are the smallest and largest eigenvalues of $A$, respectively.
In addition, a symbol $T_{n}(\xi)$ denotes the $n$-th order Chebyshev polynomial defined in the interval $[-1,1]$.
The translated and scaled residual polynomial $p_{n}(\xi)$ is defined as
\begin{equation}
    p_{n}(\xi) := \frac{T_{n}(\frac{\xi - a}{c})}{T_{n}(-\frac{a}{c})},
\end{equation}
where $a = \frac{\lambda_{max} + \lambda_{min}}{2}$ and $c = \frac{\lambda_{max} - \lambda_{min}}{2}$.
Then, the $i$-th approximation and residual of the Chebyshev semi-iterative method satisfy
\begin{equation}
    \mathbf{r}^{(i)} = \mathbf{b} - \mathbf{A}\mathbf{x}^{(i)} = p_{i}(\mathbf{A})\mathbf{r}^{(0)}.
\end{equation}

\begin{algorithm}
\caption{Chebyshev semi-iterative method}\label{alg:cheb}
\begin{algorithmic}
\Require $\lambda_{min}$, $\lambda_{max}$, $\mathbf{x}^{(0)}$, 
$\mathbf{r}^{(0)} = \mathbf{b}-\mathbf{A}\mathbf{x}^{(0)}$,
$\mathbf{x}^{(-1)}=\mathbf{r}^{(-1)}=\mathbf{0}$
\State $a \gets \frac{\lambda_{max}+\lambda_{min}}{2}$, $c \gets \frac{\lambda_{max}-\lambda_{min}}{2}$, $\eta \gets -\frac{a}{c}$
\State $\beta_{-1} \gets 0$, $\beta_{0} \gets \frac{c}{2}\frac{1}{\eta}=-\frac{c^{2}}{a}$, $\gamma_{0} \gets -a$
\State $i \gets 0$
\While{until convergence}
\State $\mathbf{x}^{(i+1)} \gets -(\mathbf{r}^{(i)} +a\mathbf{x}^{(i)}+\beta_{i-1}\mathbf{x}^{(i-1)})/\gamma_{i}$
\State $\mathbf{r}^{(i+1)} \gets -(\mathbf{A}\mathbf{r}^{(i)} -a\mathbf{r}^{(i)}-\beta_{i-1}\mathbf{r}^{(i-1)})/\gamma_{i}$
\State $i \gets i + 1$
\State $\beta_{i-1} \gets \frac{c}{2}\frac{T_{i-1}(\eta)}{T_{i}(\eta)}=\left(\frac{c}{2}\right)^{2}\frac{1}{\gamma_{i-1}}$ if $i \geq 2$
\State $\gamma_{i} \gets \frac{c}{2}\frac{T_{i+1}(\eta)}{T_{i}(\eta)} = -(a+\beta_{i-1})$
\EndWhile
\end{algorithmic}
\end{algorithm}



