\section{ Review on maximal monotone operator and  evolution equations}
This section is devoted to some essential properties of maximal monotone operators and  their  relation with  existence and uniqueness theory for  evolution equations.\\
Throughout the paper, $\mathcal{H}$ is a real Hilbert space, whose norm and scalar product are denoted respectively by $ \left\langle . , .\right\rangle $ and $ \lVert .\rVert$. The norm of  linear bounded  operators on $\mathcal{H}$ will also be denoted by $ \lVert .\rVert$ for convenience and if there is no ambiguity.\\ 
 \begin{definition} ([\cite{sobb}, pp. 20-22]):  The operator $\mathcal{A}: D(\mathcal{A}) \subset \mathcal{H} \rightarrow \mathcal{H}$ is said to be monotone if  $\langle \mathcal{A}(x)-\mathcal{A}(y), x-y\rangle \geq 0$, for all $x, y \in D(\mathcal{A})$ (i.e. $-\mathcal{A}$ is dissipative). If in addition,   the graph of $\mathcal{A} $  is not properly contained in the graph of any other monotone operator in $\mathcal{H}$, we say that  $\mathcal{A} $ is maximal monotone.
\end{definition} 
 \begin{theorem} ([\cite{sobb}, p. 34]):\label{theork1}
Let $\mathcal{A}$ be a maximal monotone operator on $\mathcal{H}$ and $\mathcal{B}$ a Lipschitzian monotone operator from $\mathcal{H}$ into $\mathcal{H}$. Then the operator $\mathcal{A}+\mathcal{B}$ is maximal monotone.
\end{theorem} 
\begin{theorem}  ([\cite{sobb}, p. 36]): \label{theork2}
Let $\mathcal{A}$ and $\mathcal{B}$ be two maximal monotone operators on $\mathcal{H}$. If $D(\mathcal{A}) \cap \operatorname{Int}(D(\mathcal{B})) \neq \emptyset$, where $\operatorname{int}(D(\mathcal{B}))$ denotes the interior of $D(\mathcal{B})$, then $\mathcal{A}+\mathcal{B}$ is a maximal monotone operator.
\end{theorem} 
Now, we introduce the notions of weak and strong  solutions of the following evolution equation:
\begin{eqnarray}\label{equation}
	\begin{cases}
		\frac{d}{d t}  x(t)=\mathcal{A} x(t)+f(t) , \quad    \hspace*{0.1cm} t>0,\\
		x(0)=x_{0}\in \mathcal{H},  \\
	\end{cases}
\end{eqnarray}
where $\mathcal{A}: D(\mathcal{A}) \subset \mathcal{H} \rightarrow \mathcal{H}$ is a  (possibly nonlinear) operator and $f$ is a given function.
\\
\begin{definition} ([\cite{sobb}, p. 64]):
 Let $f \in L^1(0, T ; \mathcal{H})$ with $T>0$.  The function $x \in C([0, T], \mathcal{H})$ 
 is called a strong  solution of  (\ref{equation}) if  it satisfies \\
$\bullet$ $x$ is absolutely continuous on any compact subset from $(0, T)$,\\
$\bullet$ $x(t) \in D(\mathcal{A})$ and $\frac{d x}{d t}(t)+\mathcal{A} x(t)= f(t)$, a.e. on $(0, T)$.
\end{definition} 
\begin{definition} ([\cite{sobb}, p. 64]):
A function $x\in C([0, T], \mathcal{H})$ is a weak solution for  (\ref{equation}) if there exist sequences $(f_{n})\in L^1(0, T ; \mathcal{H})$ such that $f_{n}\rightarrow f$ in $ L^1(0, T ; \mathcal{H})$ 
and $(x_{n})\in C([0, T], \mathcal{H})$ such that  $x_{n}$ is a strong
solution  of $\frac{d }{d t} x_{n}(t)=\mathcal{A} x_{n}(t)+f_{n}(t) $ and $x_{n}\rightarrow x$ uniformly on $[0, T]$.
\end{definition} 
The next result establishes the existence and uniqueness of the weak solution of system (\ref{equation}).
\begin{theorem}  ([\cite{sobb}, p.  65]):\label{4}
Let  $\mathcal{A}: D(\mathcal{A}) \subset \mathcal{H} \rightarrow \mathcal{H}$ be a  maximal monotone operator and $f\in L^1(0, T ; \mathcal{H})$. Then, for all $x_{0}\in \overline{D(\mathcal{A})}$  the  system  (\ref{equation})  admits  a unique weak solution $x\in C([0,+\infty), \mathcal{H})$.
\end{theorem} 
The following lemma gives a comparison principle.
\begin{lemma} ([\cite{k}, p. 102])\label{4nb}:
Let $J\subset\mathbb{R}$ and $f:\mathbb{R}\times J\rightarrow \mathbb{R}$ is continuous in $t\geq 0$  and locally Lipschitz  in $J$. For every $t_0\geq 0$, we consider the following  scalar differential equation:
  \begin{equation}\label{2b}
  \frac{d }{d t} x(t)= f(t,x(t)),  \hspace*{0.5cm} x(t_0)=x_0.
  \end{equation}
   Let $\left[t_0, T\right)$  ($t_0< T\leq \infty $) be the maximal interval of existence of the solution $x(t)$ of  (\ref{2b}) and suppose that $x(t) \in J$ for all $t \in\left[t_0, T\right)$. Let    $v(t)$ be a continuous function whose upper right-hand derivative $D^{+} v(t)$ satisfies the differential inequality
$$
D^{+} v(t) \leq f(t, v(t)), \quad v\left(t_0\right) \leq x_0,
$$
with $v(t) \in J$ for all $t \in\left[t_0, T\right)$. Then, $$v(t) \leq x(t),\hspace*{0.1cm} \forall t \in\left[t_0, T\right).$$
\end{lemma}
