\section{\texorpdfstring{\PurePoweredQSDinfty{}}{PurePoweredQSD} is \texorpdfstring{$\CeP$}{C=P}-hard}
\label{sec:PurePoweredQSD-hardness}

\begin{theorem}
    \label{thm:PurePoweredQSDinfty-CeP-hard}
    For all $n \geq 2$, $\PurePoweredQSDinfty\sbra*{1,0}$ is $\CeP$-hard.
\end{theorem}

\begin{proof}
    Noting that $\coCeP=\NQP$~\cite{ADH97,YY99}, a subclass of \PP{} that serves as a precise variant of \BQP{} that always rejects for \textit{no} instances, it suffices to show that \PurePoweredQSDinfty{} is \coNQP{}-hard. For any promise problem $(\calP_{\rm yes},\calP_{\rm no}) \in \coNQP[1,1-a(n)]$ with $a(n)\in(0,1)$, we assume without loss of generality that the \coNQP{} circuit $C_x$ has an output length of $n$. 

    To proceed, we adopt the construction from the proof of \Cref{lemma:PureQSD-is-BQPhard} and define a new circuit with output length $n'= n+1$: $C'_x \coloneqq C_x^{\dagger} \CNOT_{\sfO\to \sfF} C_x$, where both $\sfF$ and $\sfO$ are single-qubit registers. We say that $C'_x$ accepts if all qubits yield measurement outcomes of zero. 

    Now consider two pure states associated with $Q_0 = I$ and $Q_1=C'_x$: 
    $\ket{\psi_0} \coloneqq \ket{\bar{0}}\otimes \ket{0}_{\sfF}$ and $\ket{\psi_1} \coloneqq  C'_x (\ket{\bar{0}}\otimes \ket{0}_{\sfF})$. A direct calculation yields that: 
    \[ \abs*{\innerprod{\psi_0}{\psi_1}}^2 = \Pr\sbra*{C'_x \text{ accepts}} = 1-\Pr\sbra*{C_x \text{ accepts}}^2. \]

    As a consequence, we complete the proof by considering the following cases: 
    \begin{itemize}[topsep=0.33em, itemsep=0.33em, parsep=0.33em]
        \item For \textit{yes} instances, $\abs*{\innerprod{\psi_0}{\psi_1}} = \sqrt{1-\Pr\sbra{C_x\text{ accepts}}^2} =0$ implies that the pure states $\ket{\psi_0}$ and $\ket{\psi_1}$ are orthogonal. Consequently, $\Lambda_{\infty}(\ketbra{\psi_0}{\psi_0},\ketbra{\psi_1}{\psi_1}) = 1$. 
        \item For \textit{no} instances, we have
        \[\abs*{\innerprod{\psi_0}{\psi_1}} = \sqrt{1-\Pr\sbra{C_x\text{ accepts}}^2} \geq \sqrt{1-(1-a(n))^2} \geq \sqrt{a(n)} > 0,\] 
        where the last inequality follows from \Cref{fact:CePhard-ineq}. This indicates that the pure states $\ket{\psi_0}$ and $\ket{\psi_1}$ are not orthogonal. Thus, $\Lambda_{\infty}(\ketbra{\psi_0}{\psi_0},\ketbra{\psi_1}{\psi_1}) = 0$. \qedhere
    \end{itemize}
\end{proof}

\begin{fact}
    \label{fact:CePhard-ineq}
    $\forall x\in[0,1]$,  $\sqrt{1-(1-x)^2} \geq \sqrt{x}$.
\end{fact}

\begin{proof}
    Let $f(x) \coloneqq \sqrt{1-(1-x)^2} - \sqrt{x} = \sqrt{x}(\sqrt{2-x}-1)$, with the endpoint evaluations $f(0)=0$ and $f(1)=0$. To prove this inequality, it suffices to prove that $f''(x) < 0$, specifically $f(x)$ is concave on $x\in[0,1]$. A direct calculation shows that 
    \[4((2-x)x)^{3/2} f''(x) = (2-x)^{3/2} - 4 \coloneqq g(x),\] 
    and the sign of $f''(x)$ is fully determined by that of $g(x)$. Noting that $g(x)$ is monotonically non-increasing on $x\in[0,1]$, we find that $g(x) \geq g(0) = 2(\sqrt{2}-2) < 0$ on this interval, which implies $f''(x) < 0$, as desired.
\end{proof}

