\newcommand{\Xl}{X^{\leftarrow}}
\newcommand{\Xr}{X^{\rightarrow}}
\begin{proof}
  We consider the distance to either Pareto border separately and then conclude via a union bound over both cases.
  To this end, let $(\Xl_t)_{t \in \N}$ be such that for all $t \in \N$, we have $\Xl_t = \min_{z \in P^{(t)}} g_2(z)$, and analogously $(\Xr_t)_{t \in \N}$ such that for all $t \in \N$, we have $\Xr_t = \min_{z \in P^{(t)}} \bigl(\frac{n}{2} - g_2(z)\bigr)$.
  Note that for all $t \in \N$, we have $d_{\mathrm{PF}}(P^{(t)}) = \min \{\Xl_t, \Xr_t\}$.

  In what follows, we only analyze~$\Xl$, as the arguments for~$\Xr$ are identical when flipping all bits in the second half of the initial individual~$x^{(0)}$, which results in equally likely algorithm trajectories in either case, due to the uniform random choice of~$x^{(0)}$.

  Due to Chernoff bounds (\Cref{thm:chernoff-lower-bound}) applied to $g_2(x^{(0)}) = \nbOnes{x_{[n/2 .. n]}^{(0)}}$ with $\delta = \frac{1}{2}$, noting that $\E[g_2(x^{(0)})] = \frac{n}{4}$, we have with probability at least $1 - \exp(-\frac{n}{32})$ that $g_2(x^{(0)}) \geq \frac{n}{8}$ and thus $\Xl_0 \geq \frac{n}{8}$.
  For the rest of the proof, we implicitly condition on $\Xl_0 \geq \frac{n}{8}$.

  We make a case distinction with respect to which mutation operator we consider.
  We start with the modified SEMO, as it is simpler and since the case for the modified GSEMO follows the same outline but adds more complexity.

  \textbf{Modified SEMO.}
  We define $\floor{\frac{n}{8}} - \ceil{\sqrt{n}}$ geometric random variables $\{D_i\}_{i \in [\sqrt{n} .. n/8 - 1]}$, each of which represents the time that it takes the modified SEMO to reduce the current~$\Xl$ value.
  To this end, let $T_{\floor{n/8}} \coloneqq \inf \{t \in \N \mid \Xl_t < \floor{\frac{n}{8}}\}$.
  Moreover, for all $i \in [\floor{\frac{n}{8}} - \ceil{\sqrt{n}}]$, let $T_{\floor{n/8} - i} \coloneqq \inf \{t \in \N \mid t \geq T_{\floor{n/8} - i + 1} \land \Xl_t < \floor{\frac{n}{8}} - i\}$, and let $D_{\floor{n/8} - i} \coloneqq T_{\floor{n/8} - i} - T_{\floor{n/8} - i + 1}$.
  Note that since SEMO uses 1-bit flips, the stopping times $\{D_i\}_{i \in [\sqrt{n} .. n/8 - 1]}$ are all positive and independent.

  Let $i \in [\sqrt{n} .. n/8 - 1]$.
  Note that~$D_i$ follows a geometric distribution with a to-be-determined success probability~$p_i$, since each try to reduce the current~$\Xl$ value of~$i$ is identical and independent of any other try, as the reduction can only occur by using the (unique) individual~$z$ in the population with $g_2(z) = i$, as SEMO only uses 1-bit flips.
  The probability to choose~$z$ is by the definition of the modified SEMO exactly $\frac{1}{n/2 + 1}$.
  Given that~$z$ is chosen, the probability to reduce~$\Xl$ is given exactly by flipping one of the~$i$ $1$s, which has probability~$\frac{i}{n}$.
  Thus, $p_i = \frac{1}{n/2 + 1} \cdot \frac{i}{n}$.

  Let $T^{\star} \coloneqq \inf \{t \in \N \mid \Xl_t < \ceil{\sqrt{n}}\} - T_{\floor{n/8}}$, and note that $T^{\star} = \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} D_i$.
  We aim at applying \Cref{thm:geometric-sum-bound}, using the theorem's notation.
  To this end, using our exact bound for almost all success probabilities and \Cref{thm:sums-to-integrals}, we get for sufficiently large~$n$
  \begin{align*}
    \mu
     & \coloneqq\sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \E[D_i]
    = \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \frac{1}{p_i}
    = \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \frac{(n / 2 + 1) n}{i}                                                             \\
     & \geq \frac{n^2}{2} \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \frac{1}{i}
    \geq \frac{n^2}{2} \int_{[\lceil \sqrt{n} \rceil, \lfloor n / 8\rfloor]} \frac{1}{i} \mathrm{d} i                                 \\
     & \geq \frac{n^2}{2} \left(\ln\left(\left\lfloor \frac{n}{8} \right\rfloor\right) - \ln \left\lceil \sqrt{n} \right\rceil\right)
    \geq \frac{n^2}{2} \ln \frac{\sqrt{n}}{16}
    \geq \frac{n^2}{64} \ln n .
  \end{align*}
  Moreover, we get
  \begin{align*}
    s
     & \coloneqq \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \frac{1}{p_i^2}
    \leq \sum\nolimits_{i \in [\sqrt{n} .. n/8 - 1]} \left(\frac{(n / 2 + 1) n}{i}\right)^2
    \leq n^4 \sum\nolimits_{i \in \N_{\geq \sqrt{n}}} \frac{1}{i^2}          \\
     & \leq n^4 \int_{\sqrt{n} - 1}^{\infty} \frac{1}{i^2} \mathrm{d} i
    = n^4 \cdot (n^{-1/2} + 1)
    \leq 2 n^{7/2}.
  \end{align*}
  Thus, by \Cref{thm:geometric-sum-bound}, we get for $\lambda \coloneqq \frac{n^2}{128} \ln n \leq \frac{\mu}{2}$ that
  \begin{align*}
    \Pr[T^{\star} \leq \lambda]
    \leq \Pr[T^{\star} \leq \mu - \lambda]
    \leq \exp\left(-\frac{\lambda^2}{2 s}\right)
    = \exp\left(-\frac{1}{2 \cdot 128^2} \sqrt{n} \ln^2 n\right) .
  \end{align*}
  Together with the probability of $1 - \exp\bigl(-\Theta(n)\bigr)$ of the initial Chernoff bound for the initialization, the overall probability of~$\Xl$ being at least~$\sqrt{n}$ for at least $cn^2 \ln n$ iterations is at least $\bigl(1 - \exp\bigl(-\Theta(n)\bigr)\bigr)\bigl(1 - \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr)\bigr) \geq 1 - \exp\bigl(-\Omega(\sqrt{n})\bigr)$.
  This proves the claim for~$\Xl$.
  The union bound over the cases~$\Xl$ and~$\Xr$ concludes the proof for the modified SEMO.

  \textbf{Modified GSEMO.}
  We follow the same outline as in the case for the modified SEMO above.
  However, as standard bit mutation can flip more than one bit at a time, some of the stopping times we defined before may be identical and thus not independent.
  We circumvent this problem by only considering values of~$\Xl$ where it is very unlikely to make progress by flipping at least~$11$ ones within~$n^3$ iterations.
  Conditional on this event, we then proceed as in the analysis of the modified SEMO, allowing though to reduce~$\Xl$ by up to~$10$ with each improvement.

  Let $T' \coloneqq \inf \{t \in \N \mid \Xl_t < \ceil{\sqrt{n}}\} - \inf \{t \in \N \mid \Xl_t < \floor{2 n^{3/5}}\}$.
  We aim at showing that $\Pr[T' > c n^2 \ln n] \geq 1 - \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr)$.

  Let $t \in \N$, and assume that $\Xl_t \in [\sqrt{n} .. 2 n^{3/5}]$.
  Assuming that the algorithm actually selects an individual in iteration~$t$ (and does not immediately continue with the next iteration), the probability to reduce~$\Xl_t$ when flipping exactly $k \in [11 .. \Xl_t]$ ones is at most
  \begin{equation*}
    \binom{\Xl_t}{k} \frac{1}{n^k} \left(1 - \frac{1}{n}\right)^{X_t - k}
    \leq \left(\frac{\Xl_t}{n}\right)^k
    \leq 2 n^{-2k/5} ,
  \end{equation*}
  which is maximized for $k = 11$.
  Taking a union bound over all at most~$n$ values for~$k$, we see that the probability to make progress by flipping at least~$11$ ones is at most $2 n^{-22/5 + 1} = 2 n^{-17/5}$ during a single iteration (and for the considered range of~$\Xl$).
  Via a union bound over~$n^3$ iterations, the probability to make progress within~$n^3$ iterations by flipping at least~$11$ bits is thus at most $2 n^{-17/5 + 3} = 2 n^{-2/5}$.

  Furthermore, we show that during~$n^3$ iterations, it is very unlikely to flip at least~$\floor{n^{3/5}}$ ones.
  Similar to above, for any value of $\Xl \in [0 .. \frac{n}{2}]$, the probability to flip exactly $k \in [n^{3/5} .. n]$ ones is at most $\binom{\Xl_t}{k} \frac{1}{n^{k}} \leq (\frac{n / 2}{n})^{k} = 2^{-k}$, which is maximized for $k = \floor{n^{3/5}}$.
  Via a union bound over all at most~$n$ values for~$k$ and all~$n^3$ iterations we consider, the probability to flip at least~$\floor{n^{3/5}}$ ones once is at most $n^4 \cdot 2^{-\floor{n^{3/5}}} \leq \exp\bigl(-\Theta(n^{3/5})\bigr)$.
  In the following, we condition on never flipping at least~$\floor{n^{3/5}}$ ones within the first~$n^3$ iterations.

  Like in the case for the modified SEMO, we aim at applying \Cref{thm:geometric-sum-bound} to a well-chosen set of $J \in [\floor{2 n^{3/5}} - \ceil{\sqrt{n}}]$ independent geometric random variables, where~$J$ is a random variable.
  To this end, assume for the following definitions that once $\Xl < \floor{n^{3/5}}$,
  \begin{enumerate}[label=(\alph*)]
    \item\label[assumption]{item:never-more-than-ten-ones-flipped}
          the modified GSEMO \emph{never} reduces~$\Xl$ by flipping at least~$11$ ones, and
    \item\label[assumption]{item:fill-up-the-population}
          the population contains for each $i \in [\Xl .. \frac{n}{2}]$ an individual with $g_2$-value of exactly~$i$.
  \end{enumerate}
  Let $T_0 \coloneqq \inf \{t \in \N \mid \Xl_t < \floor{2 n^{3/5}}\}$, and for all $i \in [J]$, let $T_i \coloneqq \inf \{t \in \N \mid t \geq T_{i-1} \land \Xl_t < \Xl_{T_{i - 1}}\}$, and let $T_J \coloneqq \inf \{t \in \N \mid \Xl_t < \ceil{\sqrt{n}}\}$.
  Last, for all $i \in [J]$, let $D_i \coloneqq T_i - T_{i - 1}$.

  We make three observations:
  \begin{enumerate}
    \item\label[observation]{item:high-starting-value}
          Since we condition on never flipping at least~$\floor{n^{3/5}}$ ones within the first~$n^3$ iterations, we have that if $T_0 \leq n^3$, then $\Xl_{T_0} \geq \floor{2 n^{3/5}} - \floor{n^{3/5}} \geq \floor{n^{3/5}}$.

    \item\label[observation]{item:identical-stopping-times}
          Conditional on the modified GSEMO never reducing~$\Xl$ by flipping at least~$11$ ones during the first~$n^3$ iterations once $\Xl < \floor{n^{3/5}}$, it holds for all $t \in [0 .. n^3 - 1]$ that $\Pr[T' \leq t] \leq \Pr[\sum_{i \in [J]} D_i \leq t]$, because the modified GSEMO without \cref{item:fill-up-the-population} (referring to~$T'$) has at most as many options to reduce~$\Xl$ as the modified GSEMO with \cref{item:fill-up-the-population} within the first~$n^3$ iterations.

    \item\label[observation]{item:independence-of-the-transition-times}
          The variables $\{D_i\}_{i \in [J]}$ are independent, because when~$\Xl$ is reduced, the algorithm always transitions into a state that is independent of the time it took to get there (by \cref{item:fill-up-the-population} above).
          Thus, \Cref{thm:geometric-sum-bound} is applicable to any subset of $\{D_i\}_{i \in [J]}$ of deterministic cardinality, and the probability bound carries over to~$T'$ if we consider bounds within at most~$n^3$ iterations starting from~$T_0$.
  \end{enumerate}

  We aim at choosing a deterministic subset of~$[J]$ that maximizes the probability bound we get from \Cref{thm:geometric-sum-bound}, relying on \cref{item:independence-of-the-transition-times}.
  To this end, let $T^{\star} \coloneqq \sum_{i \in [J]} D_i$, and let $(p_i)_{i \in [J]}$ denote the success probabilities of $(T_i)_{i \in [J]}$.
  We proceed by estimating $\mu \coloneqq \E[T^{\star}]$ and $s \coloneqq \sum_{[i \in [J]]} \frac{1}{p_i^2}$ independently for all feasible deterministic subsets of~$[J]$.
  To this end, we bound for all $i \in [J]$ the success probability~$p_i$ in both directions, recalling that we never make progress by flipping more than~$11$ ones, by \cref{item:never-more-than-ten-ones-flipped}.
  For the lower bound, there is always at least one individual in the population that allows to make progress by flipping exactly~$1$ bit (by \cref{item:fill-up-the-population}) out of the~$\Xl_{T_{i - 1}}$ possible improvements.
  Thus, we have $p_i \geq \frac{1}{n/2 + 1} \cdot \bigl(\Xl_{T_{i - 1}}/n\bigr) (1 - \frac{1}{n})^{9} \geq \frac{1}{e} \cdot \frac{1}{n/2 + 1} \cdot \bigl(\Xl_{T_{i - 1}}/n\bigr)$.
  For the upper bound, there are by \cref{item:fill-up-the-population} always~$10$ individuals in the population that improve~$\Xl_{T_{i - 1}}$ if the appropriate bits are flipped, of which there can be multiple possibilities per individual.
  For our bound, we assume optimistically that for each individual, a $1$-bit flip is sufficient, but we account for it~$10$ times.
  Thus, we obtain $p_i \leq 10 \frac{10}{n/2 + 1} \bigl(\Xl_{T_{i - 1}}/n\bigr) (1 - \frac{1}{n})^{9} \leq \frac{100}{n/2 + 1} \bigl(\Xl_{T_{i - 1}}/n\bigr)$.

  For~$\mu$, we aim at a lower bound.
  Note that by \cref{item:high-starting-value}, each subset we consider needs to have a cardinality of at least $(\floor{n^{3/5}} - \ceil{\sqrt{n}}) / 10$, as the largest improvement reduces~$\Xl$ by~$10$ and as $\Xl_{T_0} \geq \floor{n^{3/5}}$.
  Thus, we get by our upper bound on~$p_i$ and by \Cref{thm:sums-to-integrals}
  \begin{align*}
    \mu
     & = \sum\nolimits_{i \in [J]} \E[D_i]
    \geq \frac{n^2}{100} \sum\nolimits_{i \in [(\floor{n^{3/5}} - \ceil{\sqrt{n}}) / 10]} \frac{1}{\ceil{\sqrt{n}} + 10i}          \\
     & \geq \frac{n^2}{100} \sum\nolimits_{i \in [\ceil{\sqrt{n}} / 10 + 1 .. \floor{n^{3/5}} / 10 - 1]} \frac{1}{10 i}            \\
     & \geq \frac{n^2}{1000} \int_{[\ceil{\sqrt{n}} / 10 + 1, \floor{n^{3/5}} / 10]} \frac{1}{i} \mathrm{d}i                       \\
     & = \frac{n^2}{1000} \left(\ln\left(\frac{\floor{n^{3/5}}}{10}\right) - \ln\left(\frac{\ceil{\sqrt{n}}}{10} + 1\right)\right) \\
     & \geq \frac{n^2}{1000} \ln \frac{\floor{n^{3/5}}}{2 \ceil{\sqrt{n}}}
    \geq \frac{n^2}{1000} \ln \frac{n^{1/10}}{4}
    \geq \frac{n^2}{20000} \ln n .
  \end{align*}
  For~$s$, we aim at an upper bound, using our lower bound on~$p_i$.
  We obtain
  \begin{align*}
    s
     & = \sum\nolimits_{i \in [J]} \frac{1}{p_i^2}
    \leq \sum\nolimits_{i \in [\sqrt{n} .. 2 n^{3/5}]} \left(e \left(\frac{n}{2} + 1\right) \frac{n}{i}\right)^2
    \leq e^2 n^4 \sum\nolimits_{i \in \N_{\geq \sqrt{n}}} \frac{1}{i^2}
    \leq 2 e^2 n^{7/2} .
  \end{align*}

  Applying \Cref{thm:geometric-sum-bound} for $\lambda \coloneqq \frac{n^2}{40000} \ln n \leq \frac{\mu}{2}$, we get
  \begin{equation*}
    \Pr[T^{\star} \leq \lambda]
    \leq \Pr[T^{\star} \leq \mu - \lambda]
    \leq \exp\left(-\frac{\lambda^2}{2s}\right)
    \leq \exp\left(-\frac{1}{40000^2 \cdot 4e^2} \sqrt{n} \ln^2 n\right) .
  \end{equation*}
  By \cref{item:identical-stopping-times}, since $\lambda < n^3$, this bound carries over to~$T'$.

  Combining the converse probability of at least $1 - \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr)$ with the conditional probability of at least $1 - n^{-2/5}$ that we never make progress by flipping more than~$11$ bits within the first~$n^3$ iterations (for the appropriate range of~$\Xl$) as well as with the conditional probability of at least $1 - \exp\bigl(-\Theta(n^{3/5})\bigr)$ that $\Xl_{T_0} \geq \floor{n^{3/5}}$ and with the conditional probability of at least $1 - \exp\bigl(-\Theta(n)\bigr)$ from the Chernoff bound for the initialization, we conclude that the overall probability that $\Xl \geq \sqrt{n}$ for~$\lambda$ iterations is at least $1 - \Theta(n^{-2/5})$.
  This is in the desired order and thus concludes the case for~$\Xl$.
  Taking the union bound for the cases~$\Xl$ and~$\Xr$ concludes the case for the GSEMO and thus the proof.
\end{proof}

\idealizedProcessLowerBound*

\begin{proof}
  We proceed similar to the proof of \Cref{lem:time-for-expanding-toward-the-PF-borders} and consider the distance of the algorithm to the Pareto borders,~$d_{\mathrm{PF}}$, defined just before \Cref{lem:time-for-expanding-toward-the-PF-borders}.
  That is, we disregard whether the individuals we choose as parents are Pareto-optimal or not.
  We aim at bounding the number of iterations until this value is zero, that is, $S \coloneqq \inf \{t \in \N \mid d_{\mathrm{PF}}(P^{(t)}) = 0\}$.
  Note that~$S$ is stochastically dominated by the actual runtime of the algorithm, since a distance of zero to the Pareto borders is a necessary condition for the algorithm to cover the Pareto front.

  Formally, we consider $(X_t)_{t \in \N}$ such that for all $t \in \N$, we have $X_t \coloneqq d_{\mathrm{PF}}(P^{(t)})$.
  We aim at applying \Cref{thm:geometric-sum-bound} to the waiting times for~$X$ to decrease, which we define later.
  To this end, we only discuss global mutation, noting that the case for one-bit mutation works the same but simplifies many of the arguments (and leads to slightly better transition probabilities).

  Before we define the waiting times, we determine how many of them we need to consider with high probability.
  To this end, we first prove that with high probability, the algorithm does not decrease~$X$ by at least $\ceil{\sqrt{n} / 2}$ in a single iteration within the first~$n^3$ iterations.
  Note that this event implies that~$X$ does not skip the interval $[\floor{\sqrt{n} / 2} .. \ceil{\sqrt{n}}]$ within the first~$n^3$ iterations, recalling that we assume $X_0 \geq \ceil{\sqrt{n}}$.
  We bound the probability for iteration $t \in [0 .. n^3 - 1]$ that~$X_t$ decreases by at least~$\ceil{\sqrt{n} / 2}$.
  % \merk{Added some explanations in the following.}
  In order to decrease~$X_t$ by at least $\ceil{\sqrt{n} / 2}$, regardless of which individual we choose as parent, we
  have two possibilities: The first one is to flip some bits of the~$X_t$ bits of one value of which the parent has fewer.
  Since we need to decrease~$X_t$ by at least~$\ceil{\sqrt{n} / 2}$ and since there are at most~$X_t$ bits to choose from, this requires to flip $k \in [\floor{\sqrt{n} / 2} .. X_t]$ of these bits.
  Thus, recalling that by definition follows that $X_t \leq \floor{n / 2} / 2 \leq \frac{n}{4}$, the probability to do so is at most
  \begin{equation*}
    \binom{X_t}{k} \frac{1}{n^k}
    = \frac{1}{n^k} \cdot \prod\nolimits_{i \in [k]} \frac{X_t - i + 1}{i}
    \leq \left(\frac{X_t}{n}\right)^k
    \leq 4^{-k} ,
  \end{equation*}
  which is maximized for $k = \floor{\sqrt{n} / 2}$.

  The second possibility is to flip bits among the other $\floor{n / 2} - X_t$ bits.
  Flipping all $\floor{n / 2} - X_t$ of these bits results in $X_{t + 1} = 0$.
  And in order to make sure that $X_{t + 1} \leq X_t - \ceil{\sqrt{n} / 2}$, there must remain at most $X_t - \ceil{\sqrt{n} / 2}$ bits of this value after flipping, thus requiring to flip at least $\floor{n / 2} - X_t - (X_t - \ceil{\sqrt{n} / 2})$ bits.
  Thus, this case requires to flip $\ell \in [\floor{n / 2} - 2 X_t + \floor{\sqrt{n} / 2} .. \floor{n / 2} - X_t]$ bits.
  Hence, the probability for this case is at most
  \begin{equation*}
    \binom{\floor{n / 2} - X_t}{\ell} \frac{1}{n^\ell}
    = \frac{1}{n^\ell} \cdot \prod\nolimits_{i \in [\ell]} \frac{\floor{n / 2} - X_t - i + 1}{i}
    \leq \left(\frac{n/2}{n}\right)^\ell
    = 2^{- \ell} ,
  \end{equation*}
  which is maximized for $\ell = \floor{\sqrt{n} / 2}$.

  Combined with the other probability, this results in an overall probability of at most $2 \cdot 2^{-\floor{\sqrt{n} / 2}}$ for iteration~$t$.
  Via a union bound over all~$n^3$ iterations, the probability that~$X$ is never decreased by at least $\ceil{\sqrt{n} / 2}$ in a single iteration within the first~$n^3$ iterations is at least $1 - n^3 \cdot 2 \cdot 2^{-\floor{\sqrt{n} / 2}} \geq 1 - \exp\bigl(-\Theta(\sqrt{n})\bigr)$.
  In the following, we condition on this event.

  Similar to the calculations above, we show that with high probability, the (G)SEMO does not decrease~$X$ during the first~$n^3$ iterations by at least~$8$ in a single iteration once its value is at most~$\ceil{\sqrt{n}}$.
  Let $t \in [0 .. n^3 - 1]$ be the current iteration we consider.
  The probability to decrease~$X_t$ by at least~$8$ bits, regardless of which individual we choose as parent, requires to flip at least $k \in [8 .. X_t]$ out of the~$X_t$ bits that decrease~$X_t$, or to flip at least $\ell \in [\floor{n / 2} - 2 X_t + 8 .. \floor{n / 2} - X_t]$ bits of the other value.
  Thus, the probability to make progress of at least~$8$ during a single mutation is, similar to above, at most $2 \sqrt{n}^{-8} = 2 n^{-4}$.
  A union bound over all~$n^3$ iterations yields that~$X$ is never decreased by at least~$8$ in a single iteration during this time with probability at least $1 - n^3 \cdot 2 n^{-4} = 1 - 2n^{-1}$.
  In the following, we also condition on this event.

  We proceed with defining the waiting times we aim at bounding.
  We denote the random number of decreases of~$X$ (and thus the number of waiting times we aim to bound) by $J \in [\ceil{\sqrt{n}}]$.
  Let $T_0 \coloneqq \inf \{t \in \N \mid X_t \leq \ceil{\sqrt{n}}\}$, and for all $i \in [J - 1]$, let $T_i \coloneqq \inf \{t \in \N \mid t \geq T_{i - 1} \land X_t < X_{T_{i - 1}}\}$, and let $T_J \coloneqq \inf \{t \in \N \mid t \geq T_{J - 1} \land X_t = 0\}$.
  Furthermore, for all $i \in [J]$, let $D_i \coloneqq T_i - T_{i - 1}$.
  The $\{D_i\}_{i \in [J]}$ are our waiting times of interest, noting that $S = T_0 + \sum_{i \in [J]} D_i$.
  For convenience, we define $T^\star \coloneqq \sum_{i \in [J]} D_i$.

  In order to consider independent geometric random variables, we consider a \emph{variant} of the (G)SEMO that is identical to the original (G)SEMO as long as~$X$ is larger than~$\ceil{\sqrt{n}}$.
  Once~$X$ is at most~$\ceil{\sqrt{n}}$, the variant decreases~$X$ always by at most~$7$ in a single iteration, and whenever~$X$ decreases, the population of the variant contains individuals in the population with a distance of $i \in [X .. X + 6]$ to either Pareto border in the population; the variant takes the~$13$ individuals that were not created by mutation from other parts of the population that have a larger distance to the Pareto borders (noting that we have enough individuals to do so, as we assume that the population size is already linear in~$n$).
  The variant always picks the same individuals for mutation as the original algorithm, with the difference that if the original algorithm picks an individual that was swapped closer to the Pareto borders in the variant, the variant picks this updated individual instead.
  If the original algorithm picks an individual that is not present in the variant (which happens if the original algorithm decreases~$X$ by at least~$8$ in a single iteration), then the variant chooses a parent uniformly at random from its population.
  We use the same notation for the variant as we use for the original algorithm, but we use the indices ``$\mathrm{orig}$'' for the original algorithm and ``$\mathrm{var}$'' for the variant if it is not clear from context which algorithm we are referring to.

  For the variant introduced above, the variables $\{D_i\}_{i \in [J]}$ are independent, as each improvement of~$X$ results in the population containing the same individuals that can further improve~$X$, regardless of how the progress was achieved.
  Moreover, conditional on the original (G)SEMO never decreasing~$X$ by at least~$8$ during the first~$n^3$ iterations, since the variant has at least as many possibilities to decrease~$X$ as the original (G)SEMO in each iteration, we have for all $t \in [0 .. n^3 - 1]$ that $\Pr[S_{\mathrm{orig}} \leq t] \leq \Pr[S_{\mathrm{var}} \leq t]$.
  We continue by bounding $\Pr[S_{\mathrm{var}} \leq t]$ from above by \Cref{thm:geometric-sum-bound} for any feasible value of~$J$ by considering $\{D_i\}_{i \in [J]}$ for the (G)SEMO variant, noting that the latter follow each a geometric distribution, with success probabilities $\{p_i\}_{i \in [J]}$.
  For all $i \in [J]$, we bound~$p_i$ from above and below, recalling that we assume that the population size of the (G)SEMO and thus of the variant is already $\Theta(n)$.
  For the lower bound, we pick one specific individual with the smallest distance to a Pareto border as parent and flip exactly one bit such that~$X_{T_{i - 1}}$ decreases.
  Hence, we have $p_i \geq \frac{1}{\Theta(n)} (X_{T_{i - 1}} / n) (1 - \frac{1}{n})^6 \geq X_{T_{i - 1}} / \Theta(n^2)$.
  For the upper bound, we note that we always have~$14$ individuals ($7$ per Pareto border) that can be improved by flipping any appropriate number of bits.
  We assume that for each individual, flipping a single bit is sufficient, and we account for this probability~$7$ times per individual (instead of the appropriate numbers).
  Thus, we get $p_i \leq 7 \cdot \frac{14}{\Theta(n)} (X_{T_{i - 1}} / n) (1 - \frac{1}{n})^6 \leq X_{T_{i - 1}} / \Theta(n^2)$.
  Overall, we have $p_i = X_{T_{i - 1}} / \Theta(n^2)$.

  We continue by bounding $\mu \coloneqq \E[T^\star]$ from below.
  To this end, we note that since the variant only decreases~$X$ by at most~$7$ in each iteration, any realization of a run of the variant satisfies that $J \geq \floor{\ceil{\sqrt{n}} / 7}$.
  Thus, we bound by linearity of expectation and by \Cref{thm:sums-to-integrals},
  \begin{align*}
    \mu
    = \E\left[\sum\nolimits_{i \in [J]} D_i\right]
     & = \sum\nolimits_{i \in [J]} \E[D_i]
    \geq \Theta(n^2) \sum\nolimits_{i \in [\floor{\ceil{\sqrt{n}} / 7} - 1]} \frac{1}{7 i} \\
     & \geq \Theta(n^2) \int_{[1, \floor{\ceil{\sqrt{n}} / 7}]} \frac{1}{7i} \textrm{d} i
    \geq \Theta(n^2 \log n) .
  \end{align*}

  Moreover, we bound $s \coloneqq \sum_{i \in [J]} \frac{1}{p^2_i}$ from above as
  \begin{equation*}
    s
    = \sum\nolimits_{i \in [J]} \frac{1}{p^2_i}
    \leq \Theta(n^4) \sum\nolimits_{i \in [\ceil{\sqrt{n}}]} \frac{1}{i^2}
    \leq \Theta(n^4) \sum\nolimits_{i \in \N_{\geq \sqrt{n}}} \frac{1}{i^2}
    = \Theta(n^{7/2}).
  \end{equation*}

  Applying \Cref{thm:geometric-sum-bound} with $\lambda \coloneqq \Theta(n^2 \log n)$ such that $\lambda \leq \frac{\mu}{2}$, we get
  \begin{equation*}
    \Pr[T^\star \leq \lambda]
    \leq \Pr[T^\star \leq \mu - \lambda]
    \leq \exp\left(-\frac{\lambda^2}{2 s}\right)
    \leq \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr) .
  \end{equation*}

  Since $T^\star \leq S$, it follows that $\Pr[S \leq \lambda] \leq \Pr[T^\star \leq \lambda] \leq \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr)$.
  A union bound over this failure probability as well as the two failure probabilities of the events that we condition on yields that $\Pr[S > \lambda] \geq 1 - \exp\bigl(-\Theta(-\sqrt{n})\bigr) - 2 n^{-1} - \exp\bigl(-\Theta(\sqrt{n} \log^2 n)\bigr) \geq 1 - \Theta(n^{-1})$.
  This concludes the proof.
\end{proof}


