\subsubsection{\omm and \ojzj}

\timeToParetoFrontOMMOJZJ*

\begin{proof}
  The proof is very similar to that of \Cref{lem:time-to-Pareto-front}. %In case of $\ojzjk$, we can assume that $n/4 \leq \ones{x^{(0)}} \leq 3n/4$ (which happens with probability at least $1-\exp(-\Omega(n))$ by a Chernoff bound).
  Denote by the random variable $T$ the time until there are at least $n/2$ individuals (which are also on the Pareto front). We show that $\Pr[T \geq 8en^2]=\exp(-\Omega(n))$.
  As long as $\vert{P^{(t)}}\vert < n/2$ there are two cases no matter which objective function is considered.
  \begin{itemize}
    \item[(1)] Suppose that there is an individual $x' \in P^{(t)}$ with $\ones{x'} \leq \floor{n/4}$ (i.e. $\ones{x'} = \floor{n/4}$ for $\ojzjk$). Since $\vert{P^{(t)}}\vert < n/2$, one finds $m \in [0,n/2]$ such that there is no individual $y' \in P^{(t)}$ with $\ones{y'}=n/4+m$. Hence, there is an individual $x \in P^{(t)}$ with $\ones{x} < n/2+\floor{n/4}$, but no $y$ with $\ones{y}=\ones{x}+1$.
    \item[(2)] Suppose that there is no individual $x' \in P^{(t)}$ with $\ones{x'} \leq \floor{n/4}$. Then one finds an individual $x \in P^{(t)}$ with $\ones{x}>n/4$, but no individual $y$ with $\ones{y}=\ones{x}-1$.
  \end{itemize}
  In both cases such a missing individual $y$ can be created by selecting $x$ as a parent and flipping one out of $\lceil{n/4}\rceil \geq n/4$ bits where the remaining bits are kept unchanged which happens (for both modified algorithms and problem classes) with probability at least $\frac{1}{(n+1)4e} \eqqcolon r$. Hence, $T$ is stochastically dominated by the sum of $\lceil{n/2}\rceil-1$ geometrically distributed random variables $V_1, \ldots , V_{\lceil{n/2}\rceil-1}$ with success probability $r$. Let $V\coloneqq \sum_{i=1}^{\lceil{n/2}\rceil-1}V_i$. Note that
  \[\mathbb{E}[V]=(\lceil{n/2}\rceil-1)(4en+4e) \leq n/2 \cdot (4en+4e) = 2en^2 + 2en \leq 4en^2.\]
  With \Cref{thm:geometric-sum-bound} we obtain for $\lambda\coloneqq 4en^2$, and $s\coloneqq (\lceil{n/2}\rceil-1)/r^2=16e^2(\lceil{n/2}\rceil-1)(n+1)^2$
  \begin{align*}
    \Pr[T \geq 8en^2] & \leq \Pr[V\geq 8en^2] \leq \Pr[V \geq \mathbb{E}[V]+4en^2]                                                       \\
                      & \leq \exp \left(-\frac{1}{4}\min\left\{\frac{\lambda^2}{s},\lambda r\right\}\right) = \exp(-\Omega(n)). \qedhere
  \end{align*}
\end{proof}

\timeForExpandingTowardThePFBordersOMMOJZJ*

\begin{proof}
  At first we investigate the modified (G)SEMO maximizing $\ojzjk$ for $\sqrt{n} \leq k < n/4$. We can assume that $n/4 \leq \ones{x^{(0)}} \leq 3n/4$ (by a Chernoff bound this happens with probability at least $1-\exp(-\Omega(n))$). Hence, the distance to the Pareto borders is at least $\sqrt{n}$ and one can decrease this distance only by flipping $\sqrt{n}$ specific bits at once which happens with probability at most $n^{-\sqrt{n}}$ (for both modified algorithms). By a union bound on $c n^2 \ln n$ generations for any constant $c$, we obtain the result. \\
  Now we investigate the modified (G)SEMO maximizing \omm or $\ojzjk$ for $1 < k < \sqrt{n}$.
  The proof is very similar to the proof of \Cref{lem:time-for-expanding-toward-the-PF-borders} with the minor difference that we consider $(X_t^{\leftarrow})_{t \in \mathbb{N}}$ with $X_t^{\leftarrow} = \min_{z \in P^{(t)}} \ones{z}$ and analogously $(X_t^{\rightarrow})_{t \in \mathbb{N}}$ with $X_t^{\rightarrow} = \min_{z \in P^{(t)}} n-\ones{z}$. Note that $d_{\text{PF}}(P^{(t)}) = \min\{X_t^{\rightarrow},X_t^{\leftarrow}\}$. By completely the same arguments from \Cref{lem:time-for-expanding-toward-the-PF-borders} for both modified algorithms, we obtain with probability $1-\Theta(n^{-2/5})$ that $X^{\leftarrow}_t$ is at least $\sqrt{n}$ for at least $cn^2 \ln n$ generations for a sufficiently small constant $c$.

  For $\ojzjk$, in case of $k > \sqrt{n}$, we note that the distance of the algorithm cannot attain, with the same probability bound as above, values outside of $[k .. n - k]$ because all individuals with a number of~$1$s outside of this interval (besides the all-$1$s and the all-$0$s bit string) are dominated by any solution inside this interval.
  Since the proof above shows that the algorithm only makes (with high probability) changes of at most~$\sqrt{n}$ to the number of~$1$s, the extremal solutions of the Pareto front cannot be reached during the considered time.
\end{proof}

\subsubsection{\omm}

\idealizedProcessLowerBoundOMM*

\begin{proof}
  As in the proof of \Cref{lem:idealized-process-lower-bound} we consider $S\coloneqq \inf\{t \in \mathbb{N} \mid d_{\text{PF}}(P^{(t)}) =0\}$ which is stochastically dominated by the actual runtime of the algorithm, since a distance of zero to the Pareto borders is a necessary condition for the algorithm to cover the whole Pareto front. By using the same arguments from \Cref{lem:idealized-process-lower-bound}, one can show that there is a sufficiently small constant $d$ such that $S>dn^2\log(n)$ with probability at least $1-\Theta(n^{-1})$.
\end{proof}

\gsemoLowerBoundOMM*

\begin{proof}
  By \Cref{lem:time-to-Pareto-front-OMM-OJZJ,lem:time-for-expanding-toward-the-PF-borders-OMM-OJZJ}, it follows with probability at least $1 - \Theta(n^{-1})$ that the (G)SEMO reaches the Pareto front with a population size of at least~$n / 2$ while the distance to the Pareto borders is still at least~$\sqrt{n}$.
  By \Cref{lem:idealized-process-lower-bound-OMM}, it takes the (G)SEMO $\Omega(n^2 \log n)$ objective-function evaluations until it covers the entire Pareto front, concluding the proof.
\end{proof}

\subsubsection{\ojzj}

\idealizedProcessLowerBoundOJZJ*

\begin{proof}
  In order to create $1^n$, one has to choose an individual $x$ with $\ones{x}=n-k$ and flip $k$ specific bits or another individual $y$ with $\ones{y}<n-k$ and flip $\ones{y} \geq k+1$ specific bits. This happens with probability at most $1/\Theta(n) \cdot 1/n^k + 1/n^{k+1} = O(1/n^{k+1})$ which gives $\Omega(n^{k+1})$ objective evaluations in expectation.
\end{proof}

\gsemoLowerBoundOJZJ*

\begin{proof}
  By \Cref{thm:chernoff-lower-bound}, with probability at least $1 - \exp(-\Theta(n))$, the initial solution of the (G)SEMO has at least~$k$ ones and at most $n - k$ ones.
  Then, as in the proof of \Cref{thm:gsemo-lower-bound-OMM}, the (G)SEMO reaches with probability at least $1 - \Theta(n^{-1})$ the Pareto front with a population size of at least~$n / 2$.
  The lower bound follows then by \Cref{lem:idealized-process-lower-bound-OJZJ}.
\end{proof}


