\section{Notation, terminology and preliminary results}
\label{prelim}

Let $G$ be a graph. The \emph{(open) neighborhood} of a vertex $v\in V(G)$, denoted by $N_G(v)$, is the set of neighbors of $v$ in $G$. The \emph{closed neighborhood} of a vertex $v\in V(G)$ is the set $N_G[v]=N_G(v)\cup \{v\}$. For a set $X\subseteq V(G)$, the \emph{(open) neighborhood} of $X$, denoted by $N_G(X)$, is the set $\{v\in V(G)\setminus X \, \colon v \text{ is adjacent to a vertex in } X\}$. The \emph{closed neighborhood} of $X$ is the set $N_G[X]= N_G(X)\cup X$. We simply use $N(v), N[v], N(X)$, and $N[X]$ to denote $N_G(v), N_G[v], N_G(X),$ and  $N_G[X]$, respectively when the context of the graph $G$ is clear. We use $G[X]$ to denote the subgraph of $G$ induced by the vertices in $X$. A vertex $v$ dominates itself and all its neighbors. A set $X\subseteq V(G)$ is called a \emph{clique} of $G$ if every pair of vertices of $X$ are adjacent. For disjoint subsets $X$ and $Y$ of $V(G)$, $G[X,Y]$ denotes the set of edges $\{e\in E(G)  \, \colon e$ has one endpoint in $X$ and the other endpoint in $Y\}$. If the graph $G$ is clear from the context, we write $[X,Y]$ rather than $G[X,Y]$. We say that $G[X,Y]$ is complete if every vertex in $X$ is adjacent to every vertex in $Y$ in $G$. For a given positive integer $k$, we use the notation $[k]$ to denote the set $\{1,\ldots, k\}$.

For a set $D \subseteq V(G)$ and a vertex $u \in D$, the \emph{$D$-external private neighborhood} of $u$, denoted by $\epn(u,D)$, is the set $\{v \in V(G) \setminus D  \, \colon  N(v) \cap D = \{u\}\}$. A vertex in $\epn(u,D)$ is a \emph{$D$-external private neighbor} of $u$. We say that a vertex $v\in V(G)\setminus D$ is $D$-\emph{defended} if there exists a vertex $u \in N(v)\cap D$ such that $(D\setminus \{u\})\cup \{v\}$ is a dominating set of $G$. Specifically, we say that $v\in V(G)\setminus D$ is $D$-\emph{defended by a vertex} $u$ if $u\in N(v)\cap D$ and $(D\setminus \{u\})\cup \{v\}$ is a dominating set of $G$. We note that $D$ is a secure dominating set of $G$ if and only if every vertex in $V(G) \setminus D$ is $D$-defended. We also note that if $D$ is a dominating set of $G$ and $\epn(u,D)=\emptyset$ for some $u\in D$, then every neighbor of $u$ in $V(G)\setminus D$ is $D$-defended by $u$. We state this observation formally as follows.

\begin{obs}
\label{epnempty}
If $D$ is a dominating set of a graph $G$ and $\epn(u,D)=\emptyset$ for some vertex $u \in D$, then every neighbor of $u$ that belongs to $V(G)\setminus D$ is $D$-defended by $u$.
\end{obs}

As a consequence of Observation~\ref{epnempty}, if $D$ is a dominating set of $G$ and $\epn(u,D)=\emptyset$ for every $u\in D$, then every vertex in $V(G) \setminus D$ is $D$-defended, implying that $D$ is a secure dominating set of $G$. For a given dominating set $D$ of $G$, we partition $D$ as $A_D\cup B_D$, where the sets $A_D$ and $B_D$ are defined as follows.
\begin{align*}
\tag{$\mathcal{P}_1$}
\label{indeppart}
    \bullet	\, &  \, A_D= \{u\in D \, \colon  \text{ there exists a neighbor of } u \text{ in } V(G)\setminus D \text{ that is not } D\text{-defended.}\} \\
    \bullet	\, &  \,  B_D=D\setminus A_D.
\end{align*}

We now prove the following useful lemma. We remark that some of the facts that appear in the following lemma have appeared implicitly in several papers (see~\cite{Cockayne03,merouane15}).

\begin{lemma}
\label{mainthmlem-1}	
Let $D$ be a dominating set of $G$ and $A_D\cup B_D$ be a partition of $D$ as defined in~{\rm (}\ref{indeppart}{\rm )}. \\[-24pt]
\begin{enumerate}
\item If $A_D=\emptyset$, then $D$ is a secure dominating set of $G$.
\item If a vertex $v$ in $V(G)\setminus D$ is not $D$-defended, then $N(v)\cap D\subseteq A_D$.
\item If $u$ is a vertex in $A_D$, then $\epn(u,D)\ne  \emptyset$.
\item If a vertex $v$ in $V(G)\setminus D$ is not $D$-defended, then for every neighbor $u$ of $v$ in $D$, the vertex $v$ has a non-neighbor in $\epn(u,D)$, that is, $\epn(u,D) \setminus N(v) \ne \emptyset$.
\item If $D'$ is a superset of $D$, then $A_{D'}\subseteq A_D$ and $B_D\subseteq B_{D'}$, where $A_{D'}\cup B_{D'}$ is a partition of $D'$ as defined in~{\rm (}\ref{indeppart}{\rm )}.
\end{enumerate}
\end{lemma}
\begin{proof}
Parts~(a) and (b) follow by the definition of the sets $A_D$ and $B_D$, while part~(c) follows by Observation~\ref{epnempty}.

To prove part~(d), let $v$ be a vertex in $V(G)\setminus D$ that is not $D$-defended. Suppose, to the contrary, that there exists a neighbor $u \in D$ of $v$ such that $v$ is adjacent to every vertex in $\epn(u,D)$. We note that this also includes the case when $\epn(u,D)=\emptyset$. However, then, $(D\setminus\{u\}) \cup \{v\}$ is a dominating set of $G$, contradicting the fact that the vertex $v$ is not $D$-defended.


To prove part~(e), let $D'$ be a superset of $D$. Since the property of being a dominating set is superhereditary, $D'$ is a dominating set of $G$. We partition $D'$ as $A_{D'}\cup B_{D'}$ as defined in~(\ref{indeppart}). Let $u$ be a vertex in $A_{D'}$. By~(c), $\epn(u,D')\ne \emptyset$. First we show that $u\in D$. Suppose, to the contrary, that $u \notin D$. Since $D$ is a dominating set of $G$, every vertex in $V(G)\setminus D$ is adjacent to a vertex in $D$. Moreover since $D \subseteq D'$, we have $V(G) \setminus D' \subseteq V(G)\setminus D$. This implies that every vertex $x$ in $\epn(u,D')$ is adjacent to a vertex in $D$ that is different than $u$ (since, by supposition, $u \notin D$), contradicting the fact that $\epn(u,D')\ne \emptyset$. Hence, $u \in D$. Since $u \in A_{D'}$, by the definition of $A_{D'}$, there exists a neighbor of $u$ in $V(G)\setminus D'$, say $w$, that is not $D'$-defended. Thus, by part~(d), we have $\epn(u,D') \setminus N(w) \ne \emptyset$. Since $D\subseteq D'$, we have $w\in V(G)\setminus D'\subseteq V(G)\setminus D$ and $\epn(u,D') \subseteq \epn(u,D)$, and so $\epn(u,D) \setminus N(w) \ne \emptyset$, implying that $w$ is not $D$-defended by~$u$. Thus, $u \in A_D$. Since $u$ is an arbitrary vertex in $A_{D'}$, we infer that $A_{D'} \subseteq A_D$. Thus since $D\subseteq D'$, we have $B_D = D \setminus A_D \subseteq D' \setminus A_D \subseteq D'\setminus A_{D'} = B_{D'}$, that is, $B_D\subseteq B_{D'}$.
\end{proof}
